CREATE OR REPLACE FUNCTION public.fn_sync_tenant_to_sys_companies()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
    INSERT INTO public.sys_companies (id, name, is_active, created_at, updated_at)
    VALUES (NEW.id, NEW.name, COALESCE(NEW.is_active, true), COALESCE(NEW.created_at, now()), now())
    ON CONFLICT (id) DO UPDATE SET 
        name = EXCLUDED.name, 
        is_active = EXCLUDED.is_active, 
        updated_at = now();
    RETURN NEW;
END;
$$;

