CREATE OR REPLACE FUNCTION public.fn_get_next_sequence(
    p_company_id UUID,
    p_document_type_code TEXT,
    p_fiscal_year_id INT DEFAULT NULL,
    p_branch_id UUID DEFAULT NULL
)
RETURNS TEXT AS
$func$
DECLARE
    v_prefix TEXT;
    v_fiscal_year_name TEXT := '';
    v_current_value BIGINT;
    v_padding INT := 5;
    v_next_val BIGINT;
    v_generated_number TEXT;
BEGIN
    -- 1. Ensure company exists in sys_companies to satisfy foreign key
    IF p_company_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.sys_companies WHERE id = p_company_id) THEN
        BEGIN
            INSERT INTO public.sys_companies (id, name, is_active, created_at, updated_at)
            VALUES (p_company_id, 'Ø´Ø±ÙƒØ© Ø§Ù„Ù†Ø¸Ø§Ù…', true, now(), now())
            ON CONFLICT (id) DO UPDATE SET is_active = true, updated_at = now();
        EXCEPTION WHEN OTHERS THEN
            SELECT id INTO p_company_id FROM public.sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
        END;
    END IF;

    SELECT prefix INTO v_prefix 
    FROM public.sys_document_types 
    WHERE code = p_document_type_code;

    IF v_prefix IS NULL OR v_prefix = '' THEN
        v_prefix := UPPER(SUBSTRING(COALESCE(p_document_type_code, 'DOC') FROM 1 FOR 3));
    END IF;

    -- 2. Ensure document type exists in sys_document_types to satisfy foreign key
    IF NOT EXISTS (SELECT 1 FROM public.sys_document_types WHERE code = p_document_type_code) THEN
        INSERT INTO public.sys_document_types (code, name, prefix, is_active)
        VALUES (
            p_document_type_code,
            INITCAP(REPLACE(p_document_type_code, '_', ' ')),
            v_prefix,
            true
        )
        ON CONFLICT (code) DO NOTHING;
    END IF;

    IF p_fiscal_year_id IS NOT NULL THEN
        BEGIN
            SELECT name INTO v_fiscal_year_name
            FROM public.fiscal_years
            WHERE id = p_fiscal_year_id;
        EXCEPTION WHEN OTHERS THEN
            v_fiscal_year_name := '';
        END;
    END IF;

    UPDATE public.sys_sequences
    SET current_value = current_value + 1,
        updated_at = now()
    WHERE id = (
        SELECT id FROM public.sys_sequences
        WHERE (company_id = p_company_id OR (company_id IS NULL AND p_company_id IS NULL))
          AND document_type_code = p_document_type_code
          AND (fiscal_year_id = p_fiscal_year_id OR (fiscal_year_id IS NULL AND p_fiscal_year_id IS NULL))
        ORDER BY id ASC
        LIMIT 1
        FOR UPDATE
    )
    RETURNING current_value, padding_length INTO v_next_val, v_padding;

    IF NOT FOUND THEN
        INSERT INTO public.sys_sequences (
            company_id, document_type_code, fiscal_year_id, current_value, padding_length
        ) VALUES (
            p_company_id, p_document_type_code, p_fiscal_year_id, 1, 5
        ) RETURNING current_value, padding_length INTO v_next_val, v_padding;
    END IF;

    v_padding := COALESCE(v_padding, 5);

    IF v_fiscal_year_name IS NOT NULL AND v_fiscal_year_name != '' THEN
        v_generated_number := v_prefix || '-' || v_fiscal_year_name || '-' || LPAD(v_next_val::TEXT, v_padding, '0');
    ELSE
        v_generated_number := v_prefix || '-' || LPAD(v_next_val::TEXT, v_padding, '0');
    END IF;

    RETURN v_generated_number;
END;
$func$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION public.fn_get_next_sequence(
    p_company_id TEXT,
    p_document_type_code TEXT,
    p_fiscal_year_id INT DEFAULT NULL,
    p_branch_id UUID DEFAULT NULL
)
RETURNS TEXT AS $$
BEGIN
    RETURN public.fn_get_next_sequence(
        CASE WHEN p_company_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' 
             THEN p_company_id::UUID ELSE NULL END,
        p_document_type_code,
        p_fiscal_year_id,
        p_branch_id
    );
END;
$$ LANGUAGE plpgsql;

GRANT EXECUTE ON FUNCTION public.fn_get_next_sequence(UUID, TEXT, INT, UUID) TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.fn_get_next_sequence(TEXT, TEXT, INT, UUID) TO authenticated, anon, service_role;

