CREATE TABLE IF NOT EXISTS public.treasuries (
    id BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    type TEXT NOT NULL DEFAULT 'employee',
    employee_id UUID,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    user_id UUID,
    notes TEXT,
    account_id INTEGER,
    approval_status TEXT DEFAULT 'approved' NOT NULL,
    company_id UUID REFERENCES public.sys_companies(id),
    deleted_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS public.treasury_balances (
    id BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    treasury_id BIGINT REFERENCES public.treasuries(id) ON DELETE CASCADE,
    currency TEXT NOT NULL,
    balance NUMERIC(15,2) DEFAULT 0.00,
    cost_base NUMERIC(18,4) DEFAULT 0.00,
    book_rate NUMERIC(18,6) DEFAULT 1.000000,
    account_id INTEGER REFERENCES public.accounts(id),
    created_at TIMESTAMPTZ DEFAULT now(),
    updated_at TIMESTAMPTZ DEFAULT now(),
    CONSTRAINT treasury_balances_currency_check CHECK (currency = ANY (ARRAY['EGP', 'USD', 'EUR', 'GBP'])),
    CONSTRAINT treasury_balances_treasury_id_currency_key UNIQUE (treasury_id, currency)
);

CREATE TABLE IF NOT EXISTS public.treasury_transactions (
    id BIGINT NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    treasury_id BIGINT REFERENCES public.treasuries(id),
    from_treasury_id BIGINT REFERENCES public.treasuries(id),
    to_treasury_id BIGINT REFERENCES public.treasuries(id),
    amount NUMERIC(15,2) NOT NULL,
    currency TEXT NOT NULL,
    type TEXT NOT NULL,
    description TEXT,
    created_by UUID,
    created_at TIMESTAMPTZ DEFAULT now(),
    transaction_type TEXT,
    balance_before NUMERIC(15,2),
    balance_after NUMERIC(15,2),
    related_treasury_id BIGINT REFERENCES public.treasuries(id),
    category_id INTEGER,
    customer_id INTEGER,
    supplier_id UUID,
    clearing_agent_id BIGINT,
    shipping_company_id BIGINT,
    shareholder_id UUID,
    currency_snapshot JSONB,
    journal_entry_id BIGINT REFERENCES public.journal_entries(id) ON DELETE SET NULL,
    source_type TEXT,
    revenue_account_id BIGINT,
    expense_account_id BIGINT,
    reference_type TEXT,
    reference_id TEXT,
    notes TEXT,
    exchange_rate NUMERIC(15,6) DEFAULT 1.0,
    amount_in_base_currency NUMERIC(18,2),
    cost_base_released NUMERIC(18,4) DEFAULT 0.00,
    status TEXT DEFAULT 'confirmed',
    payload JSONB DEFAULT '{}'::jsonb,
    company_id UUID REFERENCES public.sys_companies(id),
    deleted_at TIMESTAMPTZ
);

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.table_constraints 
        WHERE constraint_name = 'treasury_transactions_related_treasury_id_fkey' AND table_schema = 'public'
    ) THEN
        ALTER TABLE ONLY public.treasury_transactions 
        ADD CONSTRAINT treasury_transactions_related_treasury_id_fkey 
        FOREIGN KEY (related_treasury_id) REFERENCES public.treasuries(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.table_constraints 
        WHERE constraint_name = 'treasury_transactions_from_treasury_id_fkey' AND table_schema = 'public'
    ) THEN
        ALTER TABLE ONLY public.treasury_transactions 
        ADD CONSTRAINT treasury_transactions_from_treasury_id_fkey 
        FOREIGN KEY (from_treasury_id) REFERENCES public.treasuries(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.table_constraints 
        WHERE constraint_name = 'treasury_transactions_to_treasury_id_fkey' AND table_schema = 'public'
    ) THEN
        ALTER TABLE ONLY public.treasury_transactions 
        ADD CONSTRAINT treasury_transactions_to_treasury_id_fkey 
        FOREIGN KEY (to_treasury_id) REFERENCES public.treasuries(id) ON DELETE SET NULL;
    END IF;
END $$;

