    END LOOP;
END $$;

DO $$
DECLARE
    v_tables TEXT[] := ARRAY[
        'clearing_agents', 'shipping_companies', 'stations', 'treasuries',
        'treasury_balances', 'treasury_transactions', 'cheques',
        'lot_receipts', 'lot_returns', 'lot_grading_results',
        'packing_orders', 'packing_order_cost_items', 'packing_order_sortings', 'packing_recipes',
        'export_shipment_items', 'shipment_cost_items', 'shipment_cost_breakdown',
        'shipment_cost_allocations', 'shipment_profitability_snapshots', 'shipment_recipe_snapshots',
        'station_products', 'station_product_batches',
        'stock_transfers', 'stock_batches', 'stock_movements',
        'fiscal_years', 'fiscal_year_closing_entries', 'fiscal_year_closing_progress',
        'fiscal_year_inventory_snapshot', 'fiscal_year_backup_metadata', 'fiscal_year_audit_log',
        'financial_audit_log', 'audit_logs_text', 'ledger_entries',
        'prep_center_cost_items', 'supplier_settlements'
    ];
    v_tbl TEXT;
    v_seq_name TEXT;
    v_exists BOOLEAN;
BEGIN
    FOREACH v_tbl IN ARRAY v_tables LOOP
        -- ØªØ­Ù‚Ù‚ Ù…Ù† ÙˆØ¬ÙˆØ¯ Ø§Ù„Ø¬Ø¯ÙˆÙ„
        SELECT EXISTS (
            SELECT 1 FROM information_schema.tables
            WHERE table_schema = 'public' AND table_name = v_tbl
        ) INTO v_exists;

        IF v_exists THEN
            v_seq_name := 'public.' || quote_ident(v_tbl || '_id_seq');
            EXECUTE 'CREATE SEQUENCE IF NOT EXISTS ' || v_seq_name || ';';
            BEGIN
                EXECUTE 'SELECT setval(''' || v_seq_name || ''', COALESCE((SELECT MAX(id) FROM public.' || quote_ident(v_tbl) || '), 0) + 1, false);';
            EXCEPTION WHEN OTHERS THEN NULL;
            END;
            BEGIN
                EXECUTE 'ALTER TABLE public.' || quote_ident(v_tbl) || ' ALTER COLUMN id SET DEFAULT nextval(''' || v_seq_name || '''::regclass);';
            EXCEPTION WHEN OTHERS THEN NULL;
            END;
            BEGIN
                EXECUTE 'ALTER SEQUENCE ' || v_seq_name || ' OWNED BY public.' || quote_ident(v_tbl) || '.id;';
            EXCEPTION WHEN OTHERS THEN NULL;
            END;
            EXECUTE 'GRANT ALL ON SEQUENCE ' || v_seq_name || ' TO anon, authenticated, service_role;';
        END IF;
    END LOOP;
END $$;

-- ============================================================================
-- Ø§Ù„Ù…Ø±Ø§Ø­Ù„ 1 Ùˆ 2 Ùˆ 3: Ø­Ø°Ù Ø¬Ù…ÙŠØ¹ Ø§Ù„Ø¨ÙŠØ§Ù†Ø§Øª ÙˆØ§Ù„Ù‚ÙŠÙˆØ¯ ÙˆØ§Ù„Ø­Ø±ÙƒØ§Øª Ø§Ù„ØªØ´ØºÙŠÙ„ÙŠØ© ÙˆØ§Ù„Ù…Ø®Ø§Ø²Ù† Ø¨Ø£Ù…Ø§Ù† Ø¯ÙŠÙ†Ø§Ù…ÙŠÙƒÙŠ
-- ============================================================================

DO $$
DECLARE
    tbl TEXT;
    v_tables TEXT[] := ARRAY[
        -- Accounting & Ledger
        'posting_profile_rules', 'ledger_entries', 'account_ledger_entries', 'account_ledger',
        'journal_entry_lines', 'journal_entry_dimensions', 'journal_entries', 'account_balance_history',
        'cost_center_distributions', 'cost_center_transactions', 'cheque_history', 'cheques', 'bank_account_transactions',
        'cash_receipts', 'payment_vouchers', 'cash_payments', 'treasury_transactions', 'cashbox_transactions', 'transactions',
        'financial_audit_log', 'fiscal_year_audit_log', 'audit_logs', 'audit_logs_text',
        'fiscal_year_closing_entries', 'fiscal_year_closing_lock', 'fiscal_year_closing_progress',
        'fiscal_year_inventory_snapshot', 'fiscal_year_backup_metadata', 'fx_revaluations',
        'sys_sequences', 'fiscal_years',
        'general_cost_items', 'shipment_cost_allocations', 'shipment_cost_breakdown',
        'shipment_profitability_snapshots', 'shipment_recipe_snapshots',
        
        -- Inventory, Lots & Crops
        'inventory_cost_audit_log', 'inventory_item_balance_adjustments', 
        'inventory_period_snapshots', 'inventory_period_totals', 'inventory_valuation_history',
        'lot_balance_history', 'lot_cost_adjustments', 'lot_expenses', 'lot_receipt_items', 
        'lot_returns', 'lot_receipts', 'lots', 'crop_purchases', 'fruit_types', 'cost_centers',
        
        -- Warehouse, Stock & Stations
        'stock_adjustments', 'stock_batch_transactions', 'stock_batches', 
        'stock_movement_items', 'stock_movements', 'stock_transfers', 
        'station_raw_materials', 'station_product_batches', 'station_products', 'station_expenses', 'stations',
        'raw_material_movements', 'raw_material_expenses', 'raw_materials',
        
        -- Packing, Sorting & Products
        'packing_order_carton_barcodes', 'packing_order_consumables', 'packing_order_details', 
        'packing_order_history', 'packing_order_inputs', 'packing_order_items', 
        'packing_order_lot_inputs', 'packing_order_materials', 'packing_order_outputs', 
        'packing_order_raw_materials', 'packing_order_sortings', 'packing_order_lines',
        'packing_order_cost_items', 'packing_wastes', 'packing_orders', 
        'packing_operations', 'sorting_operations', 'recipes', 'products',
        
        -- Purchases & Orders
        'supplier_payment_allocations', 'purchase_invoice_edits', 'purchase_invoice_items', 'purchase_invoices', 
        'purchase_order_items', 'purchase_orders', 'purchases',
        
        -- Shipments & Sales
        'shipment_cost_items', 'export_shipment_containers', 'export_shipment_costs', 'export_shipment_customs', 
        'export_shipment_documents', 'export_shipment_history', 'export_shipment_items', 
        'export_shipments', 'proforma_invoice_items', 'proforma_invoices',
        'invoice_items', 'invoice_edits', 'invoices',
        
        -- Entities & Partners
        'customer_addresses', 'customers', 'suppliers_backup', 'supplier_settlements', 'suppliers', 
        'clearing_agents', 'shipping_company_expenses', 'shipping_companies', 
        'transport_transactions', 'transport_suppliers',
        'shareholder_profit_distributions', 'shareholder_transactions', 'shareholders', 
        'profit_distribution_settings', 'employees',
        
        -- Facilities & References
        'treasury_balances', 'treasuries', 'bank_accounts', 'warehouses',
        'raw_material_categories', 'expense_categories', 'cost_report_categories', 'unit_conversions',
        'deleted_account_codes', 'deleted_entity_codes', 'product_categories'
    ];
BEGIN
    FOR i IN 1..3 LOOP
        FOREACH tbl IN ARRAY v_tables
        LOOP
            BEGIN
                IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = tbl) THEN
                    EXECUTE 'DELETE FROM public.' || quote_ident(tbl);
                END IF;
            EXCEPTION
                WHEN undefined_table THEN
                    NULL;
                WHEN OTHERS THEN
                    IF i = 3 THEN
                        RAISE NOTICE 'Notice: skipped deleting from table %: %', tbl, SQLERRM;
                    END IF;
            END;
        END LOOP;
    END LOOP;

    -- Ø¥Ø¹Ø§Ø¯Ø© Ø¥Ù†Ø´Ø§Ø¡ Ù‚ÙÙ„ Ø§Ù„Ø¥ØºÙ„Ø§Ù‚ Ø§Ù„Ø£Ø³Ø§Ø³ÙŠ Ù„Ù…Ù†Ø¹ Ø£Ø®Ø·Ø§Ø¡ Ø§Ù„Ø¥ØºÙ„Ø§Ù‚ Ø§Ù„Ù…Ø³ØªÙ‚Ø¨Ù„ÙŠØ©
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'fiscal_year_closing_lock') THEN
        EXECUTE 'INSERT INTO public.fiscal_year_closing_lock (id, status) VALUES (1, ''FREE'') ON CONFLICT (id) DO NOTHING;';
    END IF;

END $$;

-- ============================================================================
-- Ø§Ù„Ù…Ø±Ø­Ù„Ø© 3.1: Ø­Ø°Ù ÙˆØªÙ†Ø¸ÙŠÙ Ø­Ø³Ø§Ø¨Ø§Øª ÙˆØ¨ÙŠØ§Ù†Ø§Øª Ø§Ù„Ù…ÙˆØ¸ÙÙŠÙ† Ø¨Ø§Ù„ÙƒØ§Ù…Ù„ Ù„Ù„Ø§Ø³ØªØ¹Ø¯Ø§Ø¯ Ù„ØªØ³Ù„ÙŠÙ… Ø§Ù„Ø¹Ù…ÙŠÙ„
-- ÙŠØ¶Ù…Ù† ØªØµÙÙŠØ± Ù‚Ø§Ø¦Ù…Ø© Ø§Ù„Ù…ÙˆØ¸ÙÙŠÙ† Ø¨Ù†Ø³Ø¨Ø© 100% Ù…Ø¹ Ø§Ù„Ø­ÙØ§Ø¸ Ø§Ù„ØªØ§Ù… ÙˆØ§Ù„Ø£ÙƒÙŠØ¯ Ø¹Ù„Ù‰ Ø­Ø³Ø§Ø¨ Ø§Ù„Ù…Ø§Ù„Ùƒ/Ø§Ù„Ù…Ø¯ÙŠØ± Ø§Ù„Ø±Ø¦ÙŠØ³ÙŠ
-- ============================================================================
DO $$
DECLARE
    v_admin_id UUID;
    v_emp RECORD;
BEGIN
    -- 1. ØªØ­Ø¯ÙŠØ¯ Ø§Ù„Ù…Ø¹Ø±Ù‘Ù Ø§Ù„Ø®Ø§Øµ Ø¨Ø§Ù„Ù…Ø³Ø¤ÙˆÙ„ Ø§Ù„Ø±Ø¦ÙŠØ³ÙŠ (Admin/Owner) Ù„Ø¶Ù…Ø§Ù† Ø¹Ø¯Ù… Ù…Ø³Ø§Ø³ Ø­Ø³Ø§Ø¨Ù‡ Ø¥Ø·Ù„Ø§Ù‚Ø§Ù‹
    -- Ø§Ù„Ø£ÙˆÙ„ÙˆÙŠØ©:
    -- Ø£) Ù…Ø³ØªØ®Ø¯Ù… Ø¨Ø¨Ø±ÙŠØ¯ Ø±Ø³Ù…ÙŠ Ø­Ù‚ÙŠÙ‚ÙŠ (Ù„Ø§ ÙŠÙ†ØªÙ‡ÙŠ Ø¨Ù€ @fruityfarms.local Ø£Ùˆ @%.local) ÙˆÙŠÙ…ØªÙ„Ùƒ ØµÙ„Ø§Ø­ÙŠØ§Øª Ø¥Ø¯Ø§Ø±ÙŠØ©
    -- Ø¨) Ø£Ù‚Ø¯Ù… Ù…Ø³ØªØ®Ø¯Ù… ØªÙ… Ø¥Ù†Ø´Ø§Ø¤Ù‡ ÙÙŠ Ø§Ù„Ù†Ø¸Ø§Ù… (Superadmin/First User)
    SELECT id INTO v_admin_id
    FROM public.users
    WHERE (email NOT ILIKE '%@%.local' AND email NOT ILIKE '%@fruityfarms.local')
      AND (is_admin = true OR email ILIKE '%admin%' OR email ILIKE '%owner%' OR email ILIKE '%eslam%')
    ORDER BY is_admin DESC, created_at ASC
    LIMIT 1;

    IF v_admin_id IS NULL THEN
        SELECT id INTO v_admin_id
        FROM public.users
        WHERE email NOT ILIKE '%@%.local' AND email NOT ILIKE '%@fruityfarms.local'
        ORDER BY created_at ASC
        LIMIT 1;
    END IF;

    IF v_admin_id IS NULL THEN
        SELECT id INTO v_admin_id
        FROM public.users
        ORDER BY is_admin DESC, created_at ASC
        LIMIT 1;
    END IF;

    -- 2. ØªØµÙÙŠØ± ÙˆØ­Ø°Ù ÙƒØ§ÙØ© Ø­Ø³Ø§Ø¨Ø§Øª Ø§Ù„Ù…ÙˆØ¸ÙÙŠÙ† (Ø¬Ù…ÙŠØ¹ Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª Ø¹Ø¯Ø§ Ø­Ø³Ø§Ø¨ Ø§Ù„Ù…Ø¯ÙŠØ± Ø§Ù„Ø±Ø¦ÙŠØ³ÙŠ Ø§Ù„Ù…Ø­Ø¯Ø¯)
    IF v_admin_id IS NOT NULL THEN
        FOR v_emp IN
            SELECT u.id, u.email, u.full_name
            FROM public.users u
            WHERE u.id <> v_admin_id
              AND (
                  u.email ILIKE '%@fruityfarms.local'
                  OR u.email ILIKE '%@%.local'
                  OR u.is_admin = false
                  OR EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = u.id AND ur.role = 'employee')
                  OR EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = u.id AND ur.role NOT IN ('owner', 'admin'))
              )
        LOOP
            -- Ø£. Ø­Ø°Ù Ø£Ø¯ÙˆØ§Ø± ÙˆØµÙ„Ø§Ø­ÙŠØ§Øª Ø§Ù„Ù…ÙˆØ¸Ù
            IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'user_roles') THEN
                DELETE FROM public.user_roles WHERE user_id = v_emp.id;
            END IF;

            -- Ø¨. Ø­Ø°Ù Ø§Ù„Ù…ÙˆØ¸Ù Ù…Ù† Ø¬Ø¯ÙˆÙ„ public.users
            DELETE FROM public.users WHERE id = v_emp.id;

            -- Ø¬. Ø­Ø°Ù Ø­Ø³Ø§Ø¨ Ø§Ù„Ù…ÙˆØ¸Ù Ù…Ù† auth.identities Ùˆ auth.users Ù„ØªÙ…ÙƒÙŠÙ† Ø¥Ø¹Ø§Ø¯Ø© ØªØ³Ø¬ÙŠÙ„ Ù†ÙØ³ Ø§Ù„Ø§Ø³Ù… Ø£Ùˆ Ø§Ù„Ø¨Ø±ÙŠØ¯ Ù„Ø§Ø­Ù‚Ø§Ù‹
            BEGIN
                DELETE FROM auth.identities WHERE user_id = v_emp.id;
                DELETE FROM auth.users WHERE id = v_emp.id;
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;

            RAISE NOTICE 'Reset: Cleaned employee user: % (ID: %, Email: %)', v_emp.full_name, v_emp.id, v_emp.email;
        END LOOP;
    END IF;

    -- 3. ØªØµÙÙŠØ± Ø£ÙŠ Ø¨ÙŠØ§Ù†Ø§Øª ÙÙŠ Ø¬Ø¯ÙˆÙ„ employees Ø§Ù„Ù…Ø³ØªÙ‚Ù„ Ø¥Ù† ÙˆØ¬Ø¯
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'employees') THEN
        EXECUTE 'DELETE FROM public.employees';
    END IF;

END $$;


-- ============================================================================
-- Ø§Ù„Ù…Ø±Ø­Ù„Ø© 3.5: Ø¥Ø¹Ø§Ø¯Ø© Ø¶Ø¨Ø· ØªØ³Ù„Ø³Ù„Ø§Øª Ø§Ù„Ù€ IDENTITY Ø¨Ø¹Ø¯ Ø§Ù„Ø­Ø°Ù
-- ============================================================================
-- ÙŠÙ…Ù†Ø¹ Ø£Ø®Ø·Ø§Ø¡ "duplicate key value violates unique constraint *_pkey"
-- Ù„Ø£Ù† DELETE Ù„Ø§ ÙŠØ¹ÙŠØ¯ Ø¶Ø¨Ø· ØªØ³Ù„Ø³Ù„Ø§Øª IDENTITY ØªÙ„Ù‚Ø§Ø¦ÙŠØ§Ù‹.
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT pg_get_serial_sequence('public.' || t.relname, a.attname) AS seq_name,
           'public.' || quote_ident(t.relname) AS table_name
    FROM pg_class t
    JOIN pg_attribute a ON a.attrelid = t.oid
    WHERE t.relkind = 'r'
      AND a.attnum > 0
      AND NOT a.attisdropped
      AND pg_get_serial_sequence('public.' || t.relname, a.attname) IS NOT NULL
      AND t.relnamespace = (SELECT oid FROM pg_namespace WHERE nspname = 'public')
  LOOP
    BEGIN
      EXECUTE format('SELECT setval(%L, COALESCE((SELECT MAX(id) FROM %s), 0) + 1, false)', r.seq_name, r.table_name);
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END LOOP;
END $$;

