-- Ø§Ù„Ù…Ø±Ø­Ù„Ø© 5: ØºØ±Ø³ ÙˆØ¶Ù…Ø§Ù† ÙˆØ¬ÙˆØ¯ Ø§Ù„Ø¯Ù„ÙŠÙ„ Ø§Ù„Ù…Ø­Ø§Ø³Ø¨ÙŠ Ø§Ù„Ù‚ÙŠØ§Ø³ÙŠ Ø§Ù„Ù…ÙˆØ­Ø¯ (Chart of Accounts)
-- ============================================================================
-- Ù…Ù„Ø§Ø­Ø¸Ø© Ù…Ù‡Ù…Ø©: account_code ÙÙŠÙ‡ UNIQUE constraint Ø¹Ø§Ù„Ù…ÙŠ (Ù…Ø´ per-company)
-- Ù„Ø°Ù„Ùƒ Ù†Ø¶ÙŠÙ Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª Ù…Ø±Ø© ÙˆØ§Ø­Ø¯Ø© ÙÙ‚Ø· ÙˆÙ†Ø±Ø¨Ø·Ù‡Ø§ Ø¨Ø£ÙˆÙ„ Ø´Ø±ÙƒØ©
DO $$
DECLARE
    v_has_company BOOLEAN;
    v_acct_col_type TEXT;
    v_first_company_id TEXT;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'accounts' AND column_name = 'company_id'
    ) INTO v_has_company;

    IF v_has_company THEN
        SELECT udt_name INTO v_acct_col_type
        FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'accounts' AND column_name = 'company_id';

        -- Ø§Ù„ØªØ£ÙƒØ¯ Ù…Ù† ÙˆØ¬ÙˆØ¯ Ø´Ø±ÙƒØ© ÙˆØ§Ø­Ø¯Ø© Ø¹Ù„Ù‰ Ø§Ù„Ø£Ù‚Ù„
        IF NOT EXISTS (SELECT 1 FROM public.sys_companies WHERE deleted_at IS NULL) THEN
            IF v_acct_col_type = 'uuid' THEN
                BEGIN
                    INSERT INTO public.sys_companies (id, name, is_active, created_at, updated_at)
                    VALUES ('a0000000-0000-0000-0000-000000000001'::uuid, 'Ø§Ù„Ø´Ø±ÙƒØ© Ø§Ù„Ø§ÙØªØ±Ø§Ø¶ÙŠØ©', true, now(), now())
                    ON CONFLICT (id) DO NOTHING;
                EXCEPTION WHEN OTHERS THEN
                    NULL;
                END;
            ELSE
                BEGIN
                    INSERT INTO public.sys_companies (id, name, is_active, created_at, updated_at)
                    VALUES ('comp-main-001', 'Ø§Ù„Ø´Ø±ÙƒØ© Ø§Ù„Ø§ÙØªØ±Ø§Ø¶ÙŠØ©', true, now(), now())
                    ON CONFLICT (id) DO NOTHING;
                EXCEPTION WHEN OTHERS THEN
                    NULL;
                END;
            END IF;
        END IF;

        -- Ø§Ù„Ø­ØµÙˆÙ„ Ø¹Ù„Ù‰ Ø£ÙˆÙ„ Ø´Ø±ÙƒØ©
        SELECT id::text INTO v_first_company_id FROM public.sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
    END IF;

    -- Ø£Ø±Ø´ÙØ© ÙˆØ§Ø³ØªØ¨Ø¹Ø§Ø¯ Ø£ÙŠ Ø­Ø³Ø§Ø¨Ø§Øª Ø£ØµÙˆÙ„ Ù‚Ø¯ÙŠÙ…Ø© Ø£Ùˆ Ø²Ø§Ø¦Ø¯Ø© Ø®Ø§Ø±Ø¬ Ø´Ø¬Ø±Ø© Ø§Ù„Ù€ 40 Ø­Ø³Ø§Ø¨Ø§Ù‹ Ø§Ù„Ù…Ø¹ÙŠØ§Ø±ÙŠØ©
    UPDATE public.accounts
    SET deleted_at = NOW(), is_active = false
    WHERE (account_code LIKE '1%' OR code LIKE '1%')
      AND COALESCE(account_code, code) NOT IN (
        '1', '11', '12',
        '111', '121', '122', '123', '124', '125', '126',
        '1111', '1211', '1212', '1221', '1231', '1241', '1251', '1261',
        '11111', '11112', '11113', '11114', '11115', '11116',
        '12111', '12112', '12113', '12114', '12121',
        '12211', '12212', '12213', '12214',
        '12311', '12312', '12313', '12314',
        '12411', '12412', '12413', '12414',
        '12511', '12512',
        '12611', '12612', '12613', '12614', '12615', '12616'
      );

    -- Ø£Ø±Ø´ÙØ© ÙˆØ§Ø³ØªØ¨Ø¹Ø§Ø¯ Ø£ÙŠ Ø­Ø³Ø§Ø¨Ø§Øª Ø®ØµÙˆÙ… Ù‚Ø¯ÙŠÙ…Ø© Ø£Ùˆ Ø²Ø§Ø¦Ø¯Ø© Ø®Ø§Ø±Ø¬ Ø´Ø¬Ø±Ø© Ø§Ù„Ù€ 51 Ø­Ø³Ø§Ø¨Ø§Ù‹ Ø§Ù„Ù…Ø¹ÙŠØ§Ø±ÙŠØ©
    UPDATE public.accounts
    SET deleted_at = NOW(), is_active = false
    WHERE (account_code LIKE '2%' OR code LIKE '2%')
      AND COALESCE(account_code, code) NOT IN (
        '2', '21', '22', '23',
        '211', '212', '213', '221', '231', '232', '233', '234', '235',
        '2111', '2112', '2121', '2122', '2131', '2211', '2212', '2311', '2321', '2331', '2341', '2342', '2351',
        '21111', '21112', '21113', '21114', '21115', '21116', '21117', '21118', '21121',
        '21211', '21212', '21213', '21214', '21215', '21216',
        '21221', '21222',
        '21311', '21312',
        '22111',
        '22121', '22122', '22123', '22124', '22125', '22126',
        '23111', '23112',
        '23211', '23212', '23213',
        '23311',
        '23411',
        '23421',
