    -- Ø®Ø·ÙˆØ© ÙˆÙ‚Ø§Ø¦ÙŠØ© ØªØ£ÙƒÙŠØ¯ÙŠØ©: ØªÙ†Ø¸ÙŠÙ Ø£Ùˆ Ø±Ø¨Ø· Ø£ÙŠ Ø­Ø³Ø§Ø¨ ÙŠØªÙŠÙ… Ø®Ø§Ø±Ø¬ Ø§Ù„Ø¬Ø°ÙˆØ± Ø§Ù„Ù‚ÙŠØ§Ø³ÙŠØ© Ù‚Ø¨Ù„ Ø§Ù„ÙØ­Øµ
    UPDATE public.accounts a
    SET parent_id = p.id
    FROM public.accounts p
    WHERE a.parent_id IS NULL 
      AND a.account_code NOT IN ('1', '2', '3', '4', '9')
      AND p.account_code = (
          CASE 
              WHEN a.account_code ~ '^2321[0-9]+' THEN '2321'
              WHEN a.account_code ~ '^2315[0-9]+' THEN '2321'
              WHEN a.account_code ~ '^1251[0-9]+' THEN '1251'
              WHEN a.account_code ~ '^1221[0-9]+' THEN '1221'
              WHEN a.account_code ~ '^2111[0-9]+' THEN '2111'
              WHEN a.account_code ~ '^2112[0-9]+' THEN '2112'
              WHEN a.account_code = '1000' THEN '1'
              WHEN a.account_code = '2000' THEN '2'
              WHEN a.account_code = '3000' THEN '3'
              WHEN a.account_code = '4000' THEN '4'
              WHEN a.account_code IN ('5', '5000') THEN '32'
              WHEN a.account_code LIKE '5%' THEN '321'
              WHEN LENGTH(a.account_code) >= 5    THEN SUBSTRING(a.account_code FROM 1 FOR 4)
              WHEN LENGTH(a.account_code) = 4     THEN SUBSTRING(a.account_code FROM 1 FOR 3)
              WHEN LENGTH(a.account_code) = 3     THEN SUBSTRING(a.account_code FROM 1 FOR 2)
              WHEN LENGTH(a.account_code) = 2     THEN SUBSTRING(a.account_code FROM 1 FOR 1)
              ELSE NULL
          END
      );

    DELETE FROM public.accounts
    WHERE parent_id IS NULL AND account_code NOT IN ('1', '2', '3', '4', '9');

    -- 6. Ø¥Ø¹Ø§Ø¯Ø© Ø¨Ù†Ø§Ø¡ Ù…Ø³Ø§Ø±Ø§Øª Ø§Ù„Ø£ÙƒÙˆØ§Ø¯ ÙˆØ§Ù„Ù…Ø¹Ø±ÙØ§Øª (path_codes & path_ids) Ø¨Ø¯Ù‚Ø©
    WITH RECURSIVE account_tree AS (
        SELECT id, account_code, 1 AS depth, account_code::text AS path_c, id::text AS path_i
        FROM public.accounts
        WHERE parent_id IS NULL
        UNION ALL
        SELECT a.id, a.account_code, t.depth + 1, (t.path_c || '/' || a.account_code), (t.path_i || '/' || a.id::text)
        FROM public.accounts a
        JOIN account_tree t ON a.parent_id = t.id
    )
    UPDATE public.accounts a
    SET path_codes = t.path_c,
        path_ids = t.path_i,
        level = t.depth
    FROM account_tree t
    WHERE a.id = t.id;

    -- Ø¶Ø¨Ø· leaf / posting Ø¯ÙŠÙ†Ø§Ù…ÙŠÙƒÙŠØ§Ù‹
    UPDATE public.accounts a
    SET is_leaf = NOT EXISTS (SELECT 1 FROM public.accounts c WHERE c.parent_id = a.id),
        allow_posting = NOT EXISTS (SELECT 1 FROM public.accounts c WHERE c.parent_id = a.id);
END $$;

