) RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_id BIGINT;
    v_target_code TEXT := p_account_code;
BEGIN
    IF v_target_code IS NULL OR v_target_code = '' THEN
        RETURN NULL;
    END IF;

    -- 1. Ù…Ø·Ø§Ø¨Ù‚Ø© Ù…Ø¨Ø§Ø´Ø±Ø© Ø¨Ø§Ù„ÙƒÙˆØ¯ ÙˆØ§Ù„Ø´Ø±ÙƒØ©
    SELECT id INTO v_id FROM public.accounts WHERE account_code = v_target_code AND company_id = p_company_id LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;

    -- 2. Ù…Ø·Ø§Ø¨Ù‚Ø© Ø¹Ø§Ù…Ø© Ø¨Ø§Ù„ÙƒÙˆØ¯
    SELECT id INTO v_id FROM public.accounts WHERE account_code = v_target_code LIMIT 1;
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;

