-- â”€â”€ Ø¯Ø§Ù„Ø© Ø­Ù„ Ø­Ø³Ø§Ø¨ Ø§Ù„Ø£Ø±ØµØ¯Ø© Ø§Ù„Ø§ÙØªØªØ§Ø­ÙŠØ© Ù„Ø­Ù‚ÙˆÙ‚ Ø§Ù„Ù…Ù„ÙƒÙŠØ© â”€â”€
CREATE OR REPLACE FUNCTION public.resolve_opening_balance_equity_account(
    p_currency TEXT,
    p_company_id UUID DEFAULT NULL
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_acct BIGINT;
BEGIN
    -- 1. Ø§Ù„Ù…Ø­Ø§ÙˆÙ„Ø© Ø¨Ø­Ø³Ø§Ø¨ ÙØ±ÙˆÙ‚ Ø§Ù„Ø£Ø±ØµØ¯Ø© Ø§Ù„Ø§ÙØªØªØ§Ø­ÙŠØ© Ø§Ù„Ù…Ø®ØµØµ (23421) Ø£ÙˆÙ„Ø§Ù‹
    SELECT id INTO v_acct
    FROM public.accounts
    WHERE account_code = '23421'
      AND (p_company_id IS NULL OR company_id = p_company_id OR company_id IS NULL OR company_id = 'a0000000-0000-0000-0000-000000000001'::uuid)
    ORDER BY (company_id IS NOT NULL AND company_id = p_company_id) DESC, id ASC
    LIMIT 1;

    -- 2. Ø§Ø­ØªÙŠØ§Ø·ÙŠ ÙÙŠ Ø­Ø§Ù„ Ø¹Ø¯Ù… ÙˆØ¬ÙˆØ¯Ù‡: Ø§Ù„Ø£Ø±Ø¨Ø§Ø­ ÙˆØ§Ù„Ø®Ø³Ø§Ø¦Ø± Ø§Ù„Ù…Ø±Ø­Ù„Ø© (23411) Ø£Ùˆ Ø§Ù„Ø§Ø­ØªÙŠØ§Ø·ÙŠ Ø§Ù„Ù‚Ø§Ù†ÙˆÙ†ÙŠ (23311)
    IF v_acct IS NULL THEN
        SELECT id INTO v_acct
        FROM public.accounts
        WHERE account_code IN ('23411', '23311', '23111', '2341', '2331', '2311')
          AND (p_company_id IS NULL OR company_id = p_company_id OR company_id IS NULL OR company_id = 'a0000000-0000-0000-0000-000000000001'::uuid)
        ORDER BY (company_id IS NOT NULL AND company_id = p_company_id) DESC, 
                 CASE account_code WHEN '23411' THEN 1 WHEN '23311' THEN 2 WHEN '23111' THEN 3 ELSE 4 END
        LIMIT 1;
    END IF;

    IF v_acct IS NULL THEN
        -- Ø§Ø­ØªÙŠØ§Ø·ÙŠ: Ø£ÙŠ Ø­Ø³Ø§Ø¨ Ø­Ù‚ÙˆÙ‚ Ù…Ù„ÙƒÙŠØ© Ù†Ø´Ø· ÙˆÙŠÙ‚Ø¨Ù„ Ø§Ù„ØªØ±Ø­ÙŠÙ„
        SELECT id INTO v_acct
        FROM public.accounts
        WHERE account_type = 'equity' AND (allow_posting = true OR is_leaf = true)
          AND (p_company_id IS NULL OR company_id = p_company_id OR company_id IS NULL OR company_id = 'a0000000-0000-0000-0000-000000000001'::uuid)
        ORDER BY (company_id IS NOT NULL AND company_id = p_company_id) DESC, id ASC
        LIMIT 1;
    END IF;

    -- 4. Ø§Ø­ØªÙŠØ§Ø·ÙŠ Ù…Ø·Ù„Ù‚: Ø­Ø³Ø§Ø¨ 23421 Ø¯ÙˆÙ† ØªÙ‚ÙŠÙŠØ¯ Ø¹Ù„Ù‰ Ø§Ù„Ø´Ø±ÙƒØ©
    IF v_acct IS NULL THEN
        SELECT id INTO v_acct
        FROM public.accounts
        WHERE account_code IN ('23421', '2342', '2331', '3001')
        ORDER BY (account_code = '23421') DESC, id ASC
        LIMIT 1;
    END IF;

    RETURN v_acct;
END;
$$;

CREATE OR REPLACE FUNCTION public.resolve_opening_balance_equity_account(
    p_currency TEXT,
    p_company_id TEXT
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    RETURN public.resolve_opening_balance_equity_account(p_currency, p_company_id::UUID);
END;
$$;


