-- â”€â”€ 1. Ø¯Ø§Ù„Ø© Ø§Ù„ØªØ®ØµÙŠØµ Ø§Ù„ØªÙ„Ù‚Ø§Ø¦ÙŠ Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„Ø¹Ù‡Ø¯Ø© ÙÙŠ Ø´Ø¬Ø±Ø© Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª (Level 5 Posting Account) â”€â”€
CREATE OR REPLACE FUNCTION public.ensure_custody_account(
    p_treasury_id BIGINT,
    p_company_id UUID DEFAULT NULL
) RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_treasury_record RECORD;
    v_company_id UUID := p_company_id;
    v_user_full_name TEXT;
    v_raw_name TEXT;
    v_clean_name TEXT;
    v_arabic_name TEXT;
    v_english_name TEXT;
    v_parent_code TEXT := '12612';
    v_parent_id BIGINT;
    v_existing_acct_id BIGINT;
    v_new_code TEXT;
    v_new_acct_id BIGINT;
    v_currency TEXT;
BEGIN
    -- 1. Fetch treasury info
    SELECT id, name, type, employee_id, user_id, notes, company_id, account_id
    INTO v_treasury_record
    FROM public.treasuries
    WHERE id = p_treasury_id;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    -- Determine company
    IF v_company_id IS NULL THEN
        v_company_id := v_treasury_record.company_id;
    END IF;
    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM public.sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
    END IF;

    -- Determine parent code: 12613 for permanent custody, 12612 for temporary custody
    IF (COALESCE(v_treasury_record.notes, '') ILIKE '%Ù…Ø³ØªØ¯ÙŠÙ…%' 
        OR COALESCE(v_treasury_record.name, '') ILIKE '%Ù…Ø³ØªØ¯ÙŠÙ…%' 
        OR COALESCE(v_treasury_record.notes, '') ILIKE '%permanent%') THEN
        v_parent_code := '12613';
    ELSE
        v_parent_code := '12612';
    END IF;

    -- 2. Resolve employee name
    IF v_treasury_record.employee_id IS NOT NULL THEN
        SELECT full_name INTO v_user_full_name FROM public.users WHERE id = v_treasury_record.employee_id;
    END IF;
    IF (v_user_full_name IS NULL OR TRIM(v_user_full_name) = '') AND v_treasury_record.user_id IS NOT NULL THEN
        SELECT full_name INTO v_user_full_name FROM public.users WHERE id = v_treasury_record.user_id;
    END IF;

    v_raw_name := COALESCE(NULLIF(TRIM(v_user_full_name), ''), NULLIF(TRIM(v_treasury_record.name), ''), 'Ù…ÙˆØ¸Ù');

    -- Clean up prefix words (Ø®Ø²Ù†Ø©, Ø®Ø²Ù†Ù‡, Ø¹Ù‡Ø¯Ø©, Ø¹Ù‡Ø¯Ù‡, Ø®Ø²ÙŠÙ†Ø©, Ø®Ø²ÙŠÙ†Ù‡)
    v_clean_name := regexp_replace(v_raw_name, '^(Ø®Ø²Ù†Ø©|Ø®Ø²Ù†Ù‡|Ø®Ø²ÙŠÙ†Ø©|Ø®Ø²ÙŠÙ†Ù‡|Ø¹Ù‡Ø¯Ø©|Ø¹Ù‡Ø¯Ù‡)\s*[-:]*\s*', '', 'i');
    v_clean_name := TRIM(COALESCE(NULLIF(v_clean_name, ''), v_raw_name));

    v_arabic_name := 'Ø¹Ù‡Ø¯Ø© - ' || v_clean_name;
    v_english_name := 'Custody - ' || v_clean_name;

    -- 3. Check parent account in Chart of Accounts (12612 or 12613)
    SELECT id INTO v_parent_id
    FROM public.accounts
    WHERE (account_code = v_parent_code OR code = v_parent_code)
    ORDER BY (company_id = v_company_id) DESC, id ASC
    LIMIT 1;

    -- If parent doesn't exist, create it under 1261
    IF v_parent_id IS NULL THEN
        DECLARE
            v_grandparent_id BIGINT;
        BEGIN
            SELECT id INTO v_grandparent_id
            FROM public.accounts
            WHERE (account_code = '1261' OR code = '1261')
            ORDER BY (company_id = v_company_id) DESC, id ASC
            LIMIT 1;

            INSERT INTO public.accounts (
                account_code, name, account_name, account_type,
                company_id, parent_id, level, is_leaf, allow_posting, is_system, is_active, sort_order
            ) VALUES (
                v_parent_code,
                CASE v_parent_code WHEN '12613' THEN 'Permanent Cash Custody' ELSE 'Temporary Cash Custody' END,
                CASE v_parent_code WHEN '12613' THEN 'Ø¹Ù‡Ø¯ Ù†Ù‚Ø¯ÙŠÙ‡ Ù…Ø³ØªØ¯ÙŠÙ…Ù‡' ELSE 'Ø¹Ù‡Ø¯ Ù†Ù‚Ø¯ÙŠÙ‡ Ù…Ø¤Ù‚ØªÙ‡' END,
                'asset', v_company_id, v_grandparent_id, 4, false, false, true, true, v_parent_code::INTEGER
            )
            RETURNING id INTO v_parent_id;
        END;
    ELSE
        -- Ensure parent is configured as a non-leaf category folder
        UPDATE public.accounts
        SET is_leaf = false, allow_posting = false
        WHERE id = v_parent_id AND (is_leaf = true OR allow_posting = true);
    END IF;

    -- 4. Check if treasury already has a valid Level-5 custody account
    IF v_treasury_record.account_id IS NOT NULL THEN
        SELECT id INTO v_existing_acct_id
        FROM public.accounts
        WHERE id = v_treasury_record.account_id
          AND account_code ~ ('^' || v_parent_code || '[0-9]+$')
          AND is_active = true;
    END IF;

    -- Check by name match if not found
    IF v_existing_acct_id IS NULL THEN
        SELECT id INTO v_existing_acct_id
        FROM public.accounts
        WHERE (account_name = v_arabic_name 
            OR name = v_english_name 
            OR account_name = 'Ø¹Ù‡Ø¯Ø© ' || v_clean_name
            OR account_name = v_raw_name)
          AND account_code ~ ('^' || v_parent_code || '[0-9]+$')
          AND is_active = true
        ORDER BY (company_id = v_company_id) DESC, id ASC
        LIMIT 1;
    END IF;

    -- 5. If existing Level-5 account found, link and return
    IF v_existing_acct_id IS NOT NULL THEN
        UPDATE public.treasuries 
        SET account_id = v_existing_acct_id 
        WHERE id = p_treasury_id AND (account_id IS NULL OR account_id != v_existing_acct_id);

        UPDATE public.treasury_balances 
        SET account_id = v_existing_acct_id 
        WHERE treasury_id = p_treasury_id AND (account_id IS NULL OR account_id != v_existing_acct_id);

        RETURN v_existing_acct_id;
    END IF;

    -- 6. Generate next unique Level-5 account code
    v_new_code := public.get_next_entity_account_code(
        CASE v_parent_code WHEN '12613' THEN 'permanent_custody' ELSE 'custody' END,
        v_company_id
    );

    -- 7. Provision the dedicated Level-5 account (code is a generated column in accounts)
    INSERT INTO public.accounts (
        account_code,
        name,
        account_name,
        account_type,
        company_id,
        parent_id,
        level,
        is_leaf,
        allow_posting,
        is_system,
        is_active,
        sort_order
    ) VALUES (
        v_new_code,
        v_english_name,
        v_arabic_name,
        'asset',
        v_company_id,
        v_parent_id,
        5,
        true,
        true,
        false,
        true,
        v_new_code::BIGINT
    )
    RETURNING id INTO v_new_acct_id;

    -- 8. Bind to treasury and its balances
    UPDATE public.treasuries 
    SET account_id = v_new_acct_id 
    WHERE id = p_treasury_id;

    FOREACH v_currency IN ARRAY ARRAY['EGP', 'USD', 'EUR', 'GBP']
    LOOP
        INSERT INTO public.treasury_balances (treasury_id, currency, balance, account_id)
        VALUES (p_treasury_id, v_currency, 0, v_new_acct_id)
        ON CONFLICT (treasury_id, currency) DO UPDATE
        SET account_id = v_new_acct_id;
    END LOOP;

    RETURN v_new_acct_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.ensure_custody_account(BIGINT, UUID) TO authenticated, anon, service_role;

-- ØªØ±ÙŠØ¬Ø± ØªÙ„Ù‚Ø§Ø¦ÙŠ Ù„Ø¥Ù†Ø´Ø§Ø¡ Ø­Ø³Ø§Ø¨ Ø§Ù„Ø¹Ù‡Ø¯Ø© ÙÙŠ Ø´Ø¬Ø±Ø© Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª Ø¹Ù†Ø¯ Ø¥Ø¶Ø§ÙØ© Ø£Ùˆ ØªØ¹Ø¯ÙŠÙ„ Ø®Ø²Ù†Ø© Ù…ÙˆØ¸Ù
CREATE OR REPLACE FUNCTION public.trg_fn_ensure_custody_account()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF (NEW.type = 'employee' OR NEW.type = 'custody') THEN
        PERFORM public.ensure_custody_account(NEW.id, NEW.company_id);
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_ensure_custody_account ON public.treasuries;
CREATE TRIGGER trg_ensure_custody_account
AFTER INSERT OR UPDATE OF type, name, employee_id
ON public.treasuries
FOR EACH ROW
EXECUTE FUNCTION public.trg_fn_ensure_custody_account();

-- â”€â”€ 2. Ø¯Ø§Ù„Ø© Ù…Ø±ÙƒØ²ÙŠØ© Ù„Ø­Ù„ Ø­Ø³Ø§Ø¨Ø§Øª Ø§Ù„Ø®Ø²ÙŠÙ†Ø© ÙÙŠ Ø§Ù„Ø£Ø³ØªØ§Ø° Ø§Ù„Ø¹Ø§Ù… Ù„ÙƒØ§ÙØ© Ø§Ù„Ø¹Ù…Ù„ÙŠØ§Øª â”€â”€
CREATE OR REPLACE FUNCTION public.resolve_treasury_account(
    p_treasury_id BIGINT,
    p_currency TEXT,
    p_company_id UUID DEFAULT NULL
) RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_account_id BIGINT;
    v_code TEXT;
    v_real_company_id UUID;
    v_treasury_type TEXT;
    v_treasury_name TEXT;
    v_user_id UUID;
BEGIN
    -- Resolve company_id if NULL
    v_real_company_id := p_company_id;
    IF v_real_company_id IS NULL THEN
        SELECT company_id INTO v_real_company_id FROM public.treasuries WHERE id = p_treasury_id;
    END IF;
    IF v_real_company_id IS NULL THEN
        SELECT id INTO v_real_company_id FROM public.sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
    END IF;

    -- Get treasury info
    SELECT type, name, account_id, user_id INTO v_treasury_type, v_treasury_name, v_account_id, v_user_id
    FROM public.treasuries WHERE id = p_treasury_id;

    -- 1) If this is an Employee Custody treasury (type = 'employee' or 'custody'):
    -- Must ALWAYS use a dedicated Level-5 account under 12612 / 12613
    IF v_treasury_type = 'employee' OR v_treasury_type = 'custody' THEN
        -- If already linked to a dedicated Level-5 account under 12612 or 12613, return it
        IF v_account_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM public.accounts a
            WHERE a.id = v_account_id 
              AND a.account_code ~ '^1261[23][0-9]+$' 
              AND a.is_leaf = true 
              AND a.is_active = true
        ) THEN
            RETURN v_account_id;
        END IF;

        -- Otherwise, dynamically ensure and link the dedicated Level-5 account
        v_account_id := public.ensure_custody_account(p_treasury_id, v_real_company_id);
        IF v_account_id IS NOT NULL THEN
            RETURN v_account_id;
        END IF;
    END IF;

    -- 2) For main treasuries: if explicit account_id set and active
    IF v_account_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.accounts WHERE id = v_account_id AND is_active = true) THEN
        RETURN v_account_id;
    END IF;

    -- 3) Try treasury_balances.account_id
    SELECT tb.account_id INTO v_account_id
    FROM public.treasury_balances tb
    WHERE tb.treasury_id = p_treasury_id AND tb.currency = p_currency AND tb.account_id IS NOT NULL
      AND EXISTS (SELECT 1 FROM public.accounts a WHERE a.id = tb.account_id AND a.is_active = true)
    LIMIT 1;
    IF v_account_id IS NOT NULL THEN
        RETURN v_account_id;
    END IF;

    -- 4) Main Treasury currency-based GL accounts (Primary: 12211..12214, Fallback: 12121..12124)
    v_code := CASE p_currency
        WHEN 'EGP' THEN '12211'
        WHEN 'USD' THEN '12212'
        WHEN 'EUR' THEN '12213'
        WHEN 'GBP' THEN '12214'
        ELSE '12211'
    END;
    
    SELECT id INTO v_account_id FROM public.accounts WHERE (account_code = v_code OR code = v_code) AND is_active = true ORDER BY (company_id = v_real_company_id) DESC, id ASC LIMIT 1;
    IF v_account_id IS NOT NULL THEN
        UPDATE public.treasuries SET account_id = v_account_id WHERE id = p_treasury_id AND account_id IS NULL;
        UPDATE public.treasury_balances SET account_id = v_account_id WHERE treasury_id = p_treasury_id AND currency = p_currency AND (account_id IS NULL OR account_id != v_account_id);
        RETURN v_account_id;
    END IF;

    v_code := CASE p_currency
        WHEN 'EGP' THEN '12121'
        WHEN 'USD' THEN '12122'
        WHEN 'EUR' THEN '12123'
        WHEN 'GBP' THEN '12124'
        ELSE '12121'
    END;
    
    SELECT id INTO v_account_id FROM public.accounts WHERE (account_code = v_code OR code = v_code) AND is_active = true LIMIT 1;
    IF v_account_id IS NOT NULL THEN
        RETURN v_account_id;
    END IF;

    v_code := CASE p_currency
        WHEN 'EGP' THEN '11101'
        WHEN 'USD' THEN '11102'
        WHEN 'EUR' THEN '11103'
        WHEN 'GBP' THEN '11104'
        ELSE '11101'
    END;

    SELECT id INTO v_account_id FROM public.accounts WHERE (account_code = v_code OR code = v_code) AND is_active = true LIMIT 1;
    IF v_account_id IS NOT NULL THEN
        RETURN v_account_id;
    END IF;

    -- 5) Fallback to any 1212% or 111% or asset account
    SELECT id INTO v_account_id
    FROM public.accounts
    WHERE (account_code LIKE '1212%' OR account_code LIKE '111%' OR code LIKE '1212%' OR code LIKE '111%') AND is_active = true
    ORDER BY (company_id = v_real_company_id) DESC, account_code LIMIT 1;

    IF v_account_id IS NOT NULL THEN
        RETURN v_account_id;
    END IF;

    SELECT id INTO v_account_id
    FROM public.accounts
    WHERE account_type = 'asset' AND is_leaf = true AND is_active = true
    ORDER BY (company_id = v_real_company_id) DESC, account_code LIMIT 1;

    IF v_account_id IS NOT NULL THEN
        RETURN v_account_id;
    END IF;

    RAISE EXCEPTION 'Could not resolve any treasury GL account for treasury % currency %', p_treasury_id, p_currency;
END;
$$;

GRANT EXECUTE ON FUNCTION public.resolve_treasury_account(BIGINT, TEXT, UUID) TO authenticated, anon, service_role;

-- â”€â”€ 3. Ø¯Ø§Ù„Ø© Ø¥Ù†Ø´Ø§Ø¡ Ø§Ù„Ø®Ø²Ø§Ø¦Ù† / Ø§Ù„Ø¹Ù‡Ø¯ (create_treasury) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
DROP FUNCTION IF EXISTS public.create_treasury(text, text, uuid, text);
DROP FUNCTION IF EXISTS public.create_treasury(text, text, uuid, text, uuid);

CREATE OR REPLACE FUNCTION public.create_treasury(
    p_name TEXT,
    p_type TEXT,
    p_employee_id UUID DEFAULT NULL,
    p_notes TEXT DEFAULT NULL,
    p_company_id UUID DEFAULT NULL
) RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_new_id BIGINT;
    v_account_id BIGINT;
    v_currency TEXT;
    v_company_id UUID := p_company_id;
BEGIN
    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
    END IF;

    INSERT INTO public.treasuries (name, type, employee_id, user_id, notes, company_id, approval_status, is_active)
    VALUES (p_name, p_type, p_employee_id, p_employee_id, p_notes, v_company_id, 'approved', true)
    RETURNING id INTO v_new_id;

    IF p_type = 'main' THEN
        FOREACH v_currency IN ARRAY ARRAY['EGP','USD','EUR','GBP']
        LOOP
            SELECT id INTO v_account_id FROM accounts 
            WHERE (account_code = CASE v_currency
                WHEN 'EGP' THEN '12211'
                WHEN 'USD' THEN '12212'
                WHEN 'EUR' THEN '12213'
                WHEN 'GBP' THEN '12214'
            END OR code = CASE v_currency
                WHEN 'EGP' THEN '12211'
                WHEN 'USD' THEN '12212'
                WHEN 'EUR' THEN '12213'
                WHEN 'GBP' THEN '12214'
            END)
            AND deleted_at IS NULL
            LIMIT 1;

            INSERT INTO treasury_balances (treasury_id, currency, balance, account_id)
            VALUES (v_new_id, v_currency, 0, v_account_id)
            ON CONFLICT (treasury_id, currency) DO UPDATE
            SET account_id = COALESCE(EXCLUDED.account_id, treasury_balances.account_id);
        END LOOP;
    ELSE
        -- Employee Custody Treasury -> Automatically provision dedicated Level-5 account
        v_account_id := public.ensure_custody_account(v_new_id, v_company_id);

        FOREACH v_currency IN ARRAY ARRAY['EGP','USD','EUR','GBP']
        LOOP
            INSERT INTO treasury_balances (treasury_id, currency, balance, account_id)
            VALUES (v_new_id, v_currency, 0, v_account_id)
            ON CONFLICT (treasury_id, currency) DO UPDATE
            SET account_id = COALESCE(EXCLUDED.account_id, treasury_balances.account_id);
        END LOOP;
    END IF;

    RETURN v_new_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_treasury(TEXT, TEXT, UUID, TEXT, UUID) TO authenticated, anon, service_role;

