CREATE OR REPLACE FUNCTION public.fn_get_exchange_rate(p_currency TEXT)
RETURNS NUMERIC
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_rate NUMERIC;
BEGIN
    IF p_currency IS NULL OR UPPER(TRIM(p_currency)) IN ('EGP', '') THEN
        RETURN 1.0;
    END IF;

    BEGIN
        SELECT rate_to_egp INTO v_rate
        FROM public.exchange_rates
        WHERE UPPER(currency_code) = UPPER(TRIM(p_currency))
        ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
        LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
        v_rate := NULL;
    END;

    IF v_rate IS NOT NULL AND v_rate > 0 THEN
        RETURN v_rate;
    END IF;

    CASE UPPER(TRIM(p_currency))
        WHEN 'USD' THEN RETURN 50.0;
        WHEN 'EUR' THEN RETURN 55.0;
        WHEN 'GBP' THEN RETURN 65.0;
        WHEN 'SAR' THEN RETURN 13.3;
        WHEN 'AED' THEN RETURN 13.6;
        ELSE RETURN 1.0;
    END CASE;
END;
$$;

GRANT EXECUTE ON FUNCTION public.fn_get_exchange_rate(TEXT) TO authenticated, service_role, anon;


