          ('ØªØ­Ù„ÙŠÙ„ Ù‡ÙŠØ¦Ù‡',         'direct', 'packing', 'deduction', true),
          ('Ø³Ø­Ø¨ Ø¹ÙŠÙ†Ù‡ Ø¹Ø±Ø¨ÙŠ',      'direct', 'packing', 'deduction', true),
          ('ØªØ¹Ø¯ÙŠÙ„ ÙˆØ¬Ø§Øª',         'direct', 'packing', 'deduction', true),
