-- 1. Ø¯Ø§Ù„Ø© ØªÙˆÙ„ÙŠØ¯ ÙƒÙˆØ¯ Ø§Ù„Ø¹Ù…ÙŠÙ„ Ø§Ù„ØªÙ„Ù‚Ø§Ø¦ÙŠ
CREATE OR REPLACE FUNCTION public.generate_next_customer_code()
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    next_id int;
BEGIN
    SELECT COALESCE(MAX(
        CASE 
            WHEN code ~ '^[0-9]+$' THEN code::int
            WHEN code ~ '^CUST-[0-9]+$' THEN regexp_replace(code, '^CUST-', '')::int
            ELSE 0 
        END
    ), 0) + 1 INTO next_id FROM public.customers;
    RETURN LPAD(next_id::text, 4, '0');
END;
$$;

-- 2. Ø¯Ø§Ù„Ø© ØªÙˆÙ„ÙŠØ¯ ÙƒÙˆØ¯ Ø§Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„ÙØ±Ø¹ÙŠ Ø§Ù„Ù…ÙˆØ­Ø¯ (Ù…ØªÙˆØ§ÙÙ‚Ø© Ù…Ø¹ multi-tenant)
CREATE OR REPLACE FUNCTION public.get_next_entity_account_code(
  p_entity_type TEXT,
  p_company_id UUID DEFAULT NULL
) RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_pattern TEXT;
  v_start   INTEGER;
  v_next    INTEGER;
  v_code    TEXT;
BEGIN
  CASE p_entity_type
    WHEN 'customer'                                  THEN v_pattern := '^1251[0-9]+$'; v_start := 125100;
    WHEN 'supplier', 'crop_supplier', 'crop',
         'shipping_company', 'clearing_agent',
         'packaging_supplier', 'packaging', 'station',
         'shared_supplier', 'shared',
         'transport_supplier', 'transport'           THEN v_pattern := '^2111[0-9]+$'; v_start := 211100;
    WHEN 'notes_payable', 'note_payable'             THEN v_pattern := '^2112[0-9]+$'; v_start := 211200;
    WHEN 'shareholder'                               THEN v_pattern := '^2321[0-9]+$'; v_start := 232100;
    WHEN 'custody', 'employee_custody', 'temporary_custody' THEN v_pattern := '^12612[0-9]+$'; v_start := 1261200;
    WHEN 'permanent_custody'                         THEN v_pattern := '^12613[0-9]+$'; v_start := 1261300;
    ELSE RAISE EXCEPTION 'Unknown entity type: %', p_entity_type;
  END CASE;

  -- Ø§Ù„Ø¨Ø­Ø« Ø¹Ù† Ø£Ø¹Ù„Ù‰ ÙƒÙˆØ¯ Ø­Ø³Ø§Ø¨ Ø­Ø§Ù„ÙŠ Ù„Ù‡Ø°Ø§ Ø§Ù„Ù†Ù…Ø· Ø¹Ø¨Ø± ÙƒÙ„ Ø§Ù„Ø´Ø±ÙƒØ§Øª
  LOOP
    SELECT COALESCE(MAX(account_code::bigint), v_start) + 1 INTO v_next
    FROM public.accounts
    WHERE account_code ~ v_pattern;

    IF v_next <= v_start THEN
      v_next := v_start + 1;
    END IF;

    v_code := v_next::TEXT;

    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.accounts WHERE account_code = v_code
    );

    v_start := v_next;
  END LOOP;

  RETURN v_code;
END;
$$;

-- Overload Ù„Ù„Ø¯ÙˆØ§Ù„ Ø§Ù„Ù‚Ø¯ÙŠÙ…Ø© Ø§Ù„ØªÙŠ Ù‚Ø¯ ØªÙ…Ø±Ø± p_company_id ÙƒÙ†Øµ
CREATE OR REPLACE FUNCTION public.get_next_entity_account_code(
  p_entity_type TEXT,
  p_company_id TEXT
) RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  RETURN public.get_next_entity_account_code(p_entity_type, p_company_id::UUID);
END;
$$;

-- 3. ØªØ±ÙŠØ¬Ø± Ø±Ø¨Ø· Ø­Ø³Ø§Ø¨ Ø§Ù„Ø¹Ù…ÙŠÙ„ ØªÙ„Ù‚Ø§Ø¦ÙŠØ§Ù‹ Ø¨Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª Ø§Ù„Ù…Ø§Ø³ØªØ± Ø§Ù„Ù…ÙˆØ­Ø¯Ø© (12511 Ù„Ù„ØªØµØ¯ÙŠØ± / 12512 Ù„Ù„Ù…Ø­Ù„ÙŠ)
CREATE OR REPLACE FUNCTION public.create_customer_account()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_target_account_code TEXT;
  v_target_account_id   BIGINT;
  v_raw_type            TEXT;
BEGIN
  -- 1) Ø¥Ø°Ø§ ÙƒØ§Ù† Ø§Ù„Ø¹Ù…ÙŠÙ„ Ù…Ø±ØªØ¨Ø·Ø§Ù‹ Ø¨Ø­Ø³Ø§Ø¨ Ù…Ø³Ø¨Ù‚Ø§Ù‹ Ù„Ø§ ÙŠØªÙ… Ø¹Ù…Ù„ Ø£ÙŠ ØªØ¹Ø¯ÙŠÙ„
  IF NEW.account_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- 2) ØªØ­Ø¯ÙŠØ¯ Ù†ÙˆØ¹ Ø§Ù„Ø¹Ù…ÙŠÙ„ (ØªØµØ¯ÙŠØ± Ø£Ùˆ Ù…Ø­Ù„ÙŠ)
  v_raw_type := LOWER(COALESCE(
    NEW.company_type,
    CASE WHEN (to_jsonb(NEW) ? 'customer_type') THEN to_jsonb(NEW)->>'customer_type' ELSE NULL END,
    'export'
  ));

  -- Ø§Ù„Ø±Ø¨Ø· Ø§Ù„Ù…Ø¨Ø§Ø´Ø± Ø¨Ø§Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„Ù…Ø§Ø³ØªØ± 12512 Ù„Ù„Ù…Ø­Ù„ÙŠ Ø£Ùˆ 12511 Ù„Ù„ØªØµØ¯ÙŠØ±
  IF v_raw_type IN ('local', 'Ù…Ø­Ù„ÙŠ', 'local_customer', 'Ø¹Ù…Ù„Ø§Ø¡ Ù…Ø­Ù„ÙŠ') THEN
    v_target_account_code := '12512';
  ELSE
    v_target_account_code := '12511';
  END IF;

  -- 3) Ø§Ù„Ø¨Ø­Ø« Ø¹Ù† Ø§Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„Ù…Ø§Ø³ØªØ± Ø§Ù„Ù…Ù†Ø§Ø³Ø¨ ÙÙŠ Ø§Ù„Ø´Ø±ÙƒØ© Ø£Ùˆ Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª Ø§Ù„Ø¹Ø§Ù…Ø©
  SELECT id INTO v_target_account_id
  FROM public.accounts
  WHERE account_code = v_target_account_code
    AND (company_id = NEW.company_id OR company_id = 'a0000000-0000-0000-0000-000000000001'::uuid OR company_id IS NULL)
  ORDER BY (company_id = NEW.company_id) DESC NULLS LAST
  LIMIT 1;

  IF v_target_account_id IS NULL THEN
    SELECT id INTO v_target_account_id
    FROM public.accounts
    WHERE account_code = v_target_account_code
    LIMIT 1;
  END IF;

  -- Ø§Ø­ØªÙŠØ§Ø·ÙŠ ÙÙŠ Ø­Ø§Ù„ Ø¹Ø¯Ù… ÙˆØ¬ÙˆØ¯ Ø§Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„Ø®Ø§Øµ
  IF v_target_account_id IS NULL THEN
    SELECT id INTO v_target_account_id
    FROM public.accounts
    WHERE account_code = '1251'
    LIMIT 1;
  END IF;

  -- 4) ØªØ­Ø¯ÙŠØ« Ø³Ø¬Ù„ Ø§Ù„Ø¹Ù…ÙŠÙ„ Ù…Ø¨Ø§Ø´Ø±Ø© Ø¨Ø§Ù„Ù€ account_id Ø¯ÙˆÙ† Ø¥Ù†Ø´Ø§Ø¡ Ø£ÙŠ Ø­Ø³Ø§Ø¨Ø§Øª ÙØ±Ø¹ÙŠØ© Ø¹Ø´ÙˆØ§Ø¦ÙŠØ© ÙÙŠ Ø´Ø¬Ø±Ø© Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª
  IF v_target_account_id IS NOT NULL THEN
    UPDATE public.customers
    SET account_id = v_target_account_id
    WHERE id = NEW.id;

    NEW.account_id := v_target_account_id;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_create_customer_account ON public.customers;
CREATE TRIGGER trg_create_customer_account
