FOR EACH ROW
EXECUTE FUNCTION public.create_customer_account();

-- 4. ØªØ±ÙŠØ¬Ø± Ø±Ø¨Ø· Ø­Ø³Ø§Ø¨ Ø§Ù„Ù…ÙˆØ±Ø¯ ØªÙ„Ù‚Ø§Ø¦ÙŠØ§Ù‹ Ø¨Ø§Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„Ù…Ø§Ø³ØªØ± (Ø§Ù„Ù…Ø³ØªÙˆÙ‰ Ø§Ù„Ø®Ø§Ù…Ø³)
CREATE OR REPLACE FUNCTION public.create_supplier_account()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_raw_type TEXT;
  v_target_account_code TEXT;
  v_target_account_id BIGINT;
BEGIN
  IF NEW.account_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  v_raw_type := LOWER(TRIM(COALESCE(NEW.supplier_type, 'crop')));

  -- ØªØ­Ø¯ÙŠØ¯ ÙƒÙˆØ¯ Ø§Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„Ø±Ø¦ÙŠØ³ÙŠ Ø§Ù„Ù…Ø³ØªÙˆÙ‰ Ø§Ù„Ø®Ø§Ù…Ø³ Ø¨Ù†Ø§Ø¡Ù‹ Ø¹Ù„Ù‰ ÙØ¦Ø© Ø§Ù„Ù…ÙˆØ±Ø¯:
  -- Ù…ÙˆØ±Ø¯ÙŠ Ø§Ù„Ù†Ù‚Ù„ ÙˆØ§Ù„Ø³ÙŠØ§Ø±Ø§Øª -> 21111
  -- Ù…ÙˆØ±Ø¯ÙŠ Ù…ÙˆØ§Ø¯ Ø§Ù„ØªØ¹Ø¨Ø¦Ø© -> 21112
  -- Ù…ÙˆØ±Ø¯ÙŠ Ù…Ø´ØªØ±ÙŠØ§Øª Ù…Ø­Ø§ØµÙŠÙ„ -> 21113
  -- Ù…ÙˆØ±Ø¯ÙŠÙ† Ù…Ø´ØªØ±ÙƒÙŠÙ† -> 21114
  -- Ø´Ø±ÙƒØ§Øª Ø§Ù„Ø´Ø­Ù† -> 21115
  -- ØªØ­Ø¯ÙŠØ¯ ÙƒÙˆØ¯ Ø§Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„Ø±Ø¦ÙŠØ³ÙŠ Ø§Ù„Ù…Ø³ØªÙˆÙ‰ Ø§Ù„Ø®Ø§Ù…Ø³ Ø¨Ù†Ø§Ø¡Ù‹ Ø¹Ù„Ù‰ ÙØ¦Ø© Ø§Ù„Ù…ÙˆØ±Ø¯:
  -- 'transport' -> 21111 (Ù…ÙˆØ±Ø¯ÙŠ Ø§Ù„Ù†Ù‚Ù„ ÙˆØ§Ù„Ø³ÙŠØ§Ø±Ø§Øª)
  -- 'packaging' / 'sticker' -> 21112 (Ù…ÙˆØ±Ø¯ÙŠ Ù…ÙˆØ§Ø¯ Ø§Ù„ØªØ¹Ø¨Ø¦Ø©)
  -- 'crop' -> 21113 (Ù…ÙˆØ±Ø¯ÙŠ Ù…Ø´ØªØ±ÙŠØ§Øª Ù…Ø­Ø§ØµÙŠÙ„)
  -- 'shared' -> 21114 (Ù…ÙˆØ±Ø¯ÙŠÙ† Ù…Ø´ØªØ±ÙƒÙŠÙ†)
  -- 'shipping' -> 21115 (Ø´Ø±ÙƒØ§Øª Ø§Ù„Ø´Ø­Ù†)
  -- 'clearing' -> 21116 (Ù…Ø®Ù„ØµÙŠ Ø§Ù„Ø¬Ù…Ø§Ø±Ùƒ)
  -- 'station' -> 21117 (Ù…ÙˆØ±Ø¯ÙŠ Ø§Ù„Ù…Ø­Ø·Ø§Øª)
  -- 'deduction' -> 21118 (Ù…ÙˆØ±Ø¯ÙŠ Ø§Ù„ØªØ®ØµÙŠÙ…Ø§Øª)
  IF v_raw_type IN ('transport', 'transporter', 'Ù…ÙˆØ±Ø¯ Ù†Ù‚Ù„', 'Ù†Ù‚Ù„', 'Ø³ÙŠØ§Ø±Ø§Øª') 
     OR (NEW.code)::text LIKE '6%' THEN
    v_target_account_code := '21111';
  ELSIF v_raw_type IN ('station', 'stations', 'Ù…ÙˆØ±Ø¯ Ù…Ø­Ø·Ø©', 'Ù…ÙˆØ±Ø¯ÙŠ Ø§Ù„Ù…Ø­Ø·Ø§Øª', 'Ù…Ø­Ø·Ø©', 'Ù…Ø­Ø·Ø§Øª')
     OR (NEW.code)::text LIKE '85%' OR (NEW.code)::text LIKE '86%' OR (NEW.code)::text LIKE '87%' OR (NEW.code)::text LIKE '88%' OR (NEW.code)::text LIKE '89%' THEN
    v_target_account_code := '21117';
  ELSIF v_raw_type IN ('deduction', 'deductions', 'Ù…ÙˆØ±Ø¯ ØªØ®ØµÙŠÙ…', 'Ù…ÙˆØ±Ø¯ÙŠ Ø§Ù„ØªØ®ØµÙŠÙ…Ø§Øª', 'ØªØ®ØµÙŠÙ…', 'ØªØ®ØµÙŠÙ…Ø§Øª')
     OR (NEW.code)::text LIKE '4%' THEN
    v_target_account_code := '21118';
  ELSIF v_raw_type IN ('packaging', 'packing', 'sticker', 'ØªØ¹Ø¨Ø¦Ø©', 'Ù…ÙˆØ§Ø¯ ØªØ¹Ø¨Ø¦Ø©', 'Ø§Ø³ØªÙŠÙƒØ±')
     OR (NEW.code)::text LIKE '70%' OR (NEW.code)::text LIKE '71%' OR (NEW.code)::text LIKE '72%' OR (NEW.code)::text LIKE '73%' OR (NEW.code)::text LIKE '74%' THEN
    v_target_account_code := '21112';
  ELSIF v_raw_type IN ('shared', 'Ù…Ø´ØªØ±Ùƒ', 'Ù…Ø´ØªØ±ÙƒÙŠÙ†')
     OR (NEW.code)::text LIKE '75%' OR (NEW.code)::text LIKE '76%' OR (NEW.code)::text LIKE '77%' OR (NEW.code)::text LIKE '78%' OR (NEW.code)::text LIKE '79%' THEN
    v_target_account_code := '21114';
  ELSIF v_raw_type IN ('shipping', 'shipping_company', 'Ø´Ø­Ù†', 'Ø´Ø±ÙƒØ§Øª Ø§Ù„Ø´Ø­Ù†')
     OR (NEW.code)::text LIKE '9%' THEN
    v_target_account_code := '21115';
  ELSIF v_raw_type IN ('clearing', 'clearance', 'customs', 'Ø¬Ù…Ø§Ø±Ùƒ', 'ØªØ®Ù„ÙŠØµ') THEN
    v_target_account_code := '21116';
  ELSE
    -- Ø§Ù„Ø§ÙØªØ±Ø§Ø¶ÙŠ: Ù…ÙˆØ±Ø¯ÙŠ Ù…Ø´ØªØ±ÙŠØ§Øª Ù…Ø­Ø§ØµÙŠÙ„
    v_target_account_code := '21113';
  END IF;

  SELECT id INTO v_target_account_id
  FROM public.accounts
  WHERE account_code = v_target_account_code
    AND (company_id = NEW.company_id OR company_id = 'a0000000-0000-0000-0000-000000000001'::uuid OR company_id IS NULL)
  ORDER BY (company_id = NEW.company_id) DESC NULLS LAST
  LIMIT 1;

  IF v_target_account_id IS NULL THEN
    SELECT id INTO v_target_account_id
    FROM public.accounts
    WHERE account_code = v_target_account_code
    LIMIT 1;
  END IF;

  IF v_target_account_id IS NULL THEN
    SELECT id INTO v_target_account_id
    FROM public.accounts
    WHERE account_code = '2111'
    LIMIT 1;
  END IF;

  IF v_target_account_id IS NOT NULL THEN
    NEW.account_id := v_target_account_id;
  END IF;

  RETURN NEW;
END;
$$;

