-- 7. ØªØ±ÙŠØ¬Ø± Ø¥Ù†Ø´Ø§Ø¡ Ø­Ø³Ø§Ø¨ Ø§Ù„Ù…Ø³Ø§Ù‡Ù… ØªÙ„Ù‚Ø§Ø¦ÙŠØ§Ù‹
CREATE OR REPLACE FUNCTION public.create_shareholder_account()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_new_account_id BIGINT;
  v_parent_id BIGINT;
  v_code TEXT;
BEGIN
  IF NEW.account_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Ø§Ù„ØªØ­Ù‚Ù‚ Ø£ÙˆÙ„Ø§Ù‹ Ø¥Ø°Ø§ ÙƒØ§Ù† Ø§Ù„Ù…Ø³Ø§Ù‡Ù… ÙŠØ·Ø§Ø¨Ù‚ Ø£Ø­Ø¯ Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª Ø§Ù„Ù…Ø¹ØªÙ…Ø¯Ø© Ø§Ù„Ø«Ù„Ø§Ø«Ø© (23211, 23212, 23213)
  SELECT id INTO v_new_account_id
  FROM public.accounts
  WHERE (
    (NEW.name LIKE '%Ø¹Ù…Ø§Ø¯%' AND account_code = '23211')
    OR (NEW.name LIKE '%Ø¹Ø¨Ø¯Ø§Ù„Ø¨Ø§Ø·Ù†%' AND account_code = '23212')
    OR ((NEW.name LIKE '%Ø¥Ø³Ù„Ø§Ù…%' OR NEW.name LIKE '%Ø§Ø³Ù„Ø§Ù…%') AND account_code = '23213')
  )
  ORDER BY id ASC
  LIMIT 1;

  IF v_new_account_id IS NOT NULL THEN
    UPDATE public.shareholders
    SET account_id = v_new_account_id
    WHERE id = NEW.id;
    NEW.account_id := v_new_account_id;
    RETURN NEW;
  END IF;

  SELECT id INTO v_parent_id
  FROM public.accounts
  WHERE account_code = '2321' AND (company_id = NEW.company_id OR company_id IS NULL)
  ORDER BY (company_id = NEW.company_id) DESC NULLS LAST
  LIMIT 1;
  IF v_parent_id IS NULL THEN
    SELECT id INTO v_parent_id FROM public.accounts WHERE account_code = '2321' LIMIT 1;
  END IF;
  IF v_parent_id IS NULL THEN
    SELECT id INTO v_parent_id FROM public.accounts WHERE account_code = '232' LIMIT 1;
  END IF;

  v_code := public.get_next_entity_account_code('shareholder', NEW.company_id);

  INSERT INTO public.accounts (
    account_code, name, account_name, account_type, sort_order,
    company_id, parent_id, level, is_leaf, allow_posting, is_system, is_active
  )
  VALUES (
    v_code,
    'Shareholder - ' || COALESCE(NEW.name, ''),
    'Ù…Ø³Ø§Ù‡Ù… - ' || COALESCE(NEW.name, ''),
    'equity',
    COALESCE(v_code::bigint, 232199),
    NEW.company_id,
    v_parent_id,
    5,
    true,
    true,
    false,
    true
  )
  ON CONFLICT (account_code) DO UPDATE
  SET is_active = true,
      name = EXCLUDED.name,
      account_name = EXCLUDED.account_name,
      parent_id = COALESCE(EXCLUDED.parent_id, public.accounts.parent_id),
      level = COALESCE(EXCLUDED.level, public.accounts.level),
      company_id = COALESCE(EXCLUDED.company_id, public.accounts.company_id)
  RETURNING id INTO v_new_account_id;

  UPDATE public.shareholders
  SET account_id = v_new_account_id
  WHERE id = NEW.id;

  NEW.account_id := v_new_account_id;
  RETURN NEW;
END;
$$;

