EXECUTE FUNCTION public.create_shareholder_account();

-- 8. ØªØ±ÙŠØ¬Ø± Ù…Ø²Ø§Ù…Ù†Ø© ØªØ¹Ø¯ÙŠÙ„ Ø§Ø³Ù… Ø§Ù„ÙƒÙŠØ§Ù† Ù…Ø¹ Ø´Ø¬Ø±Ø© Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª
CREATE OR REPLACE FUNCTION public.sync_entity_name_to_account()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_prefix TEXT;
  v_account_code TEXT;
BEGIN
  IF NEW.account_id IS NOT NULL AND (OLD.name IS DISTINCT FROM NEW.name) THEN
    -- Never rename shared Level-5 master control accounts or higher level accounts
    SELECT account_code INTO v_account_code
    FROM public.accounts
    WHERE id = NEW.account_id;

    IF v_account_code IS NULL OR v_account_code IN (
      '12511', '12512',
      '21111', '21112', '21113', '21114', '21115', '21116', '21121',
      '1251', '2111', '2112'
    ) OR LENGTH(v_account_code) <= 5 THEN
      RETURN NEW;
    END IF;

    CASE TG_TABLE_NAME
      WHEN 'customers'          THEN v_prefix := 'Ø¹Ù…ÙŠÙ„ - ';
      WHEN 'suppliers'          THEN v_prefix := 'Ù…ÙˆØ±Ø¯ - ';
      WHEN 'shipping_companies' THEN v_prefix := 'Ø´Ø±ÙƒØ© Ø´Ø­Ù† - ';
      WHEN 'clearing_agents'    THEN v_prefix := 'Ù…Ø®Ù„Øµ Ø¬Ù…Ø±ÙƒÙŠ - ';
      WHEN 'transport_suppliers' THEN v_prefix := 'Ù…ÙˆØ±Ø¯ Ù†Ù‚Ù„ - ';
      WHEN 'shareholders'       THEN v_prefix := 'Ø¬Ø§Ø±ÙŠ / ';
      WHEN 'treasuries'         THEN v_prefix := 'Ø¹Ù‡Ø¯Ø© - ';
      ELSE v_prefix := '';
    END CASE;

    UPDATE public.accounts
    SET name = v_prefix || COALESCE(NEW.name, ''),
        account_name = v_prefix || COALESCE(NEW.name, ''),
        updated_at = NOW()
    WHERE id = NEW.account_id;
  END IF;

  RETURN NEW;
END;
$$;

