-- 9. ØªØ±ÙŠØ¬Ø± Ø­Ø°Ù Ø­Ø³Ø§Ø¨ Ø§Ù„ÙƒÙŠØ§Ù† Ø¹Ù†Ø¯ Ø­Ø°Ù Ø§Ù„ÙƒÙŠØ§Ù† Ù†Ù‡Ø§Ø¦ÙŠØ§Ù‹
CREATE OR REPLACE FUNCTION public.delete_entity_linked_account()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_account_code TEXT;
BEGIN
  IF OLD.account_id IS NOT NULL THEN
    SELECT account_code INTO v_account_code
    FROM public.accounts 
    WHERE id = OLD.account_id;

    -- Never delete master / standard accounts (length <= 5 or whitelisted codes)
    IF v_account_code IS NOT NULL AND LENGTH(v_account_code) > 5 AND v_account_code NOT IN (
        '1', '2', '3', '4', '9',
        '11', '12', '21', '22', '23', '31', '32', '33', '41', '42', '91',
        '1211', '1212', '1221', '1231', '1232', '1234', '1251', '12511', '12512',
        '2111', '21111', '21112', '21113', '21114', '21115', '21116', '2112', '21121',
        '3111', '3211', '3221', '4111',
        '1000', '1010', '1020', '1030', '1031', '1032', '1040',
        '11101', '11102', '11103', '11104',
        '11201', '11202', '11203', '11204',
        '2000', '2100', '2101', '2102', '2103', '2104', '2105', '2106', '2107', '2200', '2300',
        '3000', '3100', '3101', '3200', '3300',
        '4000', '41101', '4200', '4300', '4310', '4320',
        '5000', '6001', '51102', '51104', '5110', '5210', '6002', '6000', '6110', '51101', '6130', '6150', '6151', '6152'
      ) THEN
      DELETE FROM public.accounts WHERE id = OLD.account_id;
    END IF;
  END IF;
  RETURN OLD;
END;
$$;

