-- ============================================================================
-- Ø§Ù„Ù…Ø±Ø­Ù„Ø© 9: ØªØµÙÙŠØ± Ø§Ù„Ø£Ø±ØµØ¯Ø© ÙˆØ§Ù„Ù€ Sequences
-- ============================================================================

-- ØªØµÙÙŠØ± Ø£Ø±ØµØ¯Ø© Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª
UPDATE public.accounts SET balance = 0, updated_at = NOW();

-- Ø­Ø°Ù Ø³Ø¬Ù„Ø§Øª Ø§Ù„Ø£ÙƒÙˆØ§Ø¯ Ø§Ù„Ù…Ø­Ø°ÙˆÙØ© Ø§Ù„Ø³Ø§Ø¨Ù‚Ø© Ø¥Ù† ÙˆØ¬Ø¯Øª
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'deleted_account_codes') THEN
        DELETE FROM public.deleted_account_codes;
    END IF;
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'deleted_entity_codes') THEN
        DELETE FROM public.deleted_entity_codes;
    END IF;
END $$;

-- ØªØµÙÙŠØ± Sequences ÙÙŠ PostgreSQL ÙˆÙ…Ø²Ø§Ù…Ù†ØªÙ‡Ø§ Ø¯ÙŠÙ†Ø§Ù…ÙŠÙƒÙŠØ§Ù‹ Ø¨Ø¯Ù‚Ø©
DO $$
DECLARE
    r RECORD;
    v_seq TEXT;
    v_max_id BIGINT;
BEGIN
    -- 1. ØªØµÙÙŠØ± Ø£ÙŠ sequences Ø¹Ø§Ù…Ø© ØºÙŠØ± Ù…Ø±ØªØ¨Ø·Ø© Ù…Ø¨Ø§Ø´Ø±Ø© Ø¨Ø£Ø¹Ù…Ø¯Ø©
    FOR r IN (
        SELECT s.sequence_name
        FROM information_schema.sequences s
        WHERE s.sequence_schema = 'public'
          AND s.sequence_name NOT LIKE '%accounts%'
          AND s.sequence_name NOT LIKE '%expense%'
          AND s.sequence_name NOT IN ('journal_entries_id_seq', 'account_ledger_entries_id_seq')
    ) LOOP
        BEGIN
            EXECUTE 'ALTER SEQUENCE public.' || quote_ident(r.sequence_name) || ' RESTART WITH 1;';
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END LOOP;

    -- 2. Ù…Ø²Ø§Ù…Ù†Ø© ÙƒÙ„ sequence Ù…Ø±Ø¨ÙˆØ· Ø¨Ø¹Ù…ÙˆØ¯ Ø¬Ø¯ÙˆÙ„ Ø¨Ø¯Ù‚Ø© Ù…Ø¹ Ø£Ø¹Ù„Ù‰ ID Ù…ÙˆØ¬ÙˆØ¯ + 1
    FOR r IN (
        SELECT table_name
        FROM information_schema.columns
        WHERE table_schema = 'public' AND column_name = 'id' AND data_type IN ('integer', 'bigint', 'smallint')
    ) LOOP
        BEGIN
            v_seq := pg_get_serial_sequence('public.' || quote_ident(r.table_name), 'id');
            IF v_seq IS NOT NULL THEN
                EXECUTE format('SELECT COALESCE(MAX(id), 0) + 1 FROM public.%I', r.table_name) INTO v_max_id;
                EXECUTE format('ALTER SEQUENCE %s RESTART WITH %s', v_seq, v_max_id);
            END IF;
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END LOOP;

    -- ØªØµÙÙŠØ± Ø¹Ø¯Ø§Ø¯Ø§Øª Ø§Ù„Ù…Ø³ØªÙ†Ø¯Ø§Øª ÙˆØ§Ù„ÙÙˆØ§ØªÙŠØ± (OB, INV, PUR, Ø§Ù„Ø®)
    BEGIN
        EXECUTE 'UPDATE public.invoice_numbering SET next_number = 1;';
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    
    BEGIN
        EXECUTE 'UPDATE public.sys_document_types SET next_number = 1;';
    EXCEPTION WHEN OTHERS THEN NULL;
    END;

    BEGIN
        EXECUTE 'DELETE FROM public.sys_sequences;';
    EXCEPTION WHEN OTHERS THEN
        EXECUTE 'UPDATE public.sys_sequences SET current_value = 0;';
    END;
END $$;

-- ============================================================================
-- Ø§Ù„Ù…Ø±Ø­Ù„Ø© 10: Ø§Ù„ÙØ­Øµ ÙˆØ§Ù„ØªØ­Ù‚Ù‚ Ø§Ù„Ø´Ø§Ù…Ù„ Ø§Ù„Ù†Ù‡Ø§Ø¦ÙŠ (Comprehensive Verification)
-- ============================================================================

DO $$
DECLARE
  v_tbl TEXT;
  v_count INT;
  v_missing_core TEXT[] := '{}';
  v_core_code TEXT;
  v_company_count INT := 0;
  v_main_treasury INT := 0;
  v_treasury_currencies INT := 0;
  v_treasury_links_ok INT := 0;
  v_bank_accounts INT := 0;
  v_warehouses INT := 0;
  v_total_accounts INT := 0;
BEGIN
  -- Ø¹Ø¯Ø¯ Ø§Ù„Ø´Ø±ÙƒØ§Øª ÙÙŠ Ø§Ù„Ù†Ø¸Ø§Ù… (Ù„Ù„ØªØ­Ù‚Ù‚ Ø¨Ù†Ø³Ø¨Ø©)
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'sys_companies') THEN
    SELECT COUNT(*) INTO v_company_count FROM public.sys_companies WHERE deleted_at IS NULL;
  END IF;
  IF v_company_count < 1 THEN v_company_count := 1; END IF;

  -- Ø§Ù„ØªØ­Ù‚Ù‚ Ù…Ù† Ø®Ù„Ùˆ Ø§Ù„Ù…Ø¹Ø§Ù…Ù„Ø§Øª Ø§Ù„ØªØ´ØºÙŠÙ„ÙŠØ© ÙˆØ§Ù„Ù…Ø®Ø§Ø²Ù† Ø§Ù„ÙØ±Ø¹ÙŠØ©
  FOREACH v_tbl IN ARRAY ARRAY[
    'journal_entries', 'account_ledger_entries', 'customers', 'suppliers', 
    'purchase_invoices', 'export_shipments', 'stock_batches', 
    'treasury_transactions', 'bank_account_transactions',
    'packing_orders', 'lot_receipts', 'crop_purchases', 'purchases', 'lots', 'invoices', 'transactions',
    'cost_center_transactions', 'stations'
  ] LOOP
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = v_tbl) THEN
      EXECUTE 'SELECT COUNT(*) FROM public.' || quote_ident(v_tbl) INTO v_count;
      IF v_count > 0 THEN
        RAISE EXCEPTION 'Verification Failed: Table % has % rows, expected 0.', v_tbl, v_count;
      END IF;
    END IF;
  END LOOP;

  -- Ø§Ù„ØªØ­Ù‚Ù‚ Ù…Ù† Ø®Ù„Ùˆ Ø£ØµÙ†Ø§Ù Ø§Ù„ÙØ§ÙƒÙ‡Ø© ÙˆÙ…Ø±Ø§ÙƒØ² ØªÙƒÙ„ÙØªÙ‡Ø§ Ù„Ù„Ø¨Ø¯Ø¡ Ù…Ù† Ø¬Ø¯ÙŠØ¯
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'fruit_types') THEN
    EXECUTE 'SELECT COUNT(*) FROM public.fruit_types' INTO v_count;
    IF v_count > 0 THEN
      RAISE EXCEPTION 'Verification Failed: Table fruit_types has % rows, expected 0.', v_count;
    END IF;
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'cost_centers') THEN
    EXECUTE 'SELECT COUNT(*) FROM public.cost_centers WHERE cost_center_type = ''variety'' OR entity_type = ''fruit_type''' INTO v_count;
    IF v_count > 0 THEN
      RAISE EXCEPTION 'Verification Failed: Table cost_centers has % variety rows, expected 0.', v_count;
    END IF;
  END IF;

  -- Ø§Ù„ØªØ­Ù‚Ù‚ Ù…Ù† Ø§Ù„Ø³Ù†Ø© Ø§Ù„Ù…Ø§Ù„ÙŠØ© ÙˆØ§Ù„Ø¹Ø¯Ø§Ø¯Ø§Øª
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'fiscal_years') THEN
    SELECT COUNT(*) INTO v_count FROM public.fiscal_years WHERE is_current = true;
    IF v_count != 1 THEN
      RAISE EXCEPTION 'Verification Failed: Expected exactly 1 active fiscal year, but found %.', v_count;
    END IF;
  END IF;

  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'sys_sequences') THEN
    DELETE FROM public.sys_sequences;
    SELECT COUNT(*) INTO v_count FROM public.sys_sequences WHERE current_value > 0;
    IF v_count > 0 THEN
      RAISE EXCEPTION 'Verification Failed: Expected sys_sequences active counters to be 0, but found % rows.', v_count;
    END IF;
  END IF;

  -- Ø§Ù„ØªØ­Ù‚Ù‚ Ù…Ù† Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª Ø§Ù„Ù‚ÙŠØ§Ø³ÙŠØ© Ø§Ù„Ø£Ø³Ø§Ø³ÙŠØ© (Ø¨Ù…Ø§ ÙÙŠÙ‡Ø§ Ø­Ø³Ø§Ø¨ Ø¬Ø§Ø±ÙŠ Ø§Ù„Ù…Ø³Ø§Ù‡Ù…ÙŠÙ† ÙˆØ§Ù„Ø´Ø±ÙƒØ§Øª Ø§Ù„ÙˆØ³ÙŠØ·Ø©)
  FOREACH v_core_code IN ARRAY ARRAY[
    '1', '2', '3', '4', '9',
    '11', '12', '21', '22', '23', '31', '32', '33', '41', '42', '91',
    '121', '122', '211', '231', '232', '311', '321', '322', '411', '911', '912',
    '1211', '1212', '12121', '1221', '1231', '1232', '1234', '2111', '2112', '2321',
    '3111', '3211', '3221', '4111', '9111', '9112', '9121', '9122', '9123', '9124'
  ] LOOP
    IF NOT EXISTS (SELECT 1 FROM public.accounts WHERE account_code = v_core_code) THEN
      v_missing_core := array_append(v_missing_core, v_core_code);
    END IF;
  END LOOP;

  IF array_length(v_missing_core, 1) > 0 THEN
    RAISE EXCEPTION 'Verification Failed: Missing core accounts: %', v_missing_core;
  END IF;

  -- Ø®Ø·ÙˆØ© ÙˆÙ‚Ø§Ø¦ÙŠØ© ØªØ£ÙƒÙŠØ¯ÙŠØ©: ØªÙ†Ø¸ÙŠÙ Ø£Ùˆ Ø±Ø¨Ø· Ø£ÙŠ Ø­Ø³Ø§Ø¨ ÙŠØªÙŠÙ… Ø®Ø§Ø±Ø¬ Ø§Ù„Ø¬Ø°ÙˆØ± Ø§Ù„Ù‚ÙŠØ§Ø³ÙŠØ© Ù‚Ø¨Ù„ Ø§Ù„ÙØ­Øµ
  UPDATE public.accounts a
  SET parent_id = p.id
  FROM public.accounts p
  WHERE a.parent_id IS NULL 
    AND a.account_code NOT IN ('1', '2', '3', '4', '9')
    AND p.account_code = (
        CASE 
            WHEN a.account_code ~ '^2321[0-9]+' THEN '2321'
            WHEN a.account_code ~ '^2315[0-9]+' THEN '2321'
            WHEN a.account_code ~ '^1221[0-9]+' THEN '1221'
            WHEN a.account_code ~ '^2111[0-9]+' THEN '2111'
            WHEN a.account_code ~ '^2112[0-9]+' THEN '2112'
            WHEN a.account_code = '1000' THEN '1'
            WHEN a.account_code = '2000' THEN '2'
            WHEN a.account_code = '3000' THEN '3'
            WHEN a.account_code = '4000' THEN '4'
            WHEN a.account_code IN ('5', '5000') THEN '32'
            WHEN a.account_code LIKE '5%' THEN '321'
            WHEN LENGTH(a.account_code) >= 5    THEN SUBSTRING(a.account_code FROM 1 FOR 4)
            WHEN LENGTH(a.account_code) = 4     THEN SUBSTRING(a.account_code FROM 1 FOR 3)
            WHEN LENGTH(a.account_code) = 3     THEN SUBSTRING(a.account_code FROM 1 FOR 2)
            WHEN LENGTH(a.account_code) = 2     THEN SUBSTRING(a.account_code FROM 1 FOR 1)
            ELSE NULL
        END
    );

  DELETE FROM public.accounts
  WHERE parent_id IS NULL AND account_code NOT IN ('1', '2', '3', '4', '9');

  -- Ø§Ù„ØªØ­Ù‚Ù‚ Ø§Ù„ØµØ§Ø±Ù… Ù…Ù† Ø¹Ø¯Ù… ÙˆØ¬ÙˆØ¯ Ø£ÙŠ Ø­Ø³Ø§Ø¨Ø§Øª ÙŠØªÙŠÙ…Ø© Ø¨Ù„Ø§ Ø£Ø¨ Ø³ÙˆÙ‰ Ø§Ù„Ø¬Ø°ÙˆØ± Ø§Ù„Ù‚ÙŠØ§Ø³ÙŠØ© Ø§Ù„Ø®Ù…Ø³Ø© (1, 2, 3, 4, 9)
  SELECT COUNT(*) INTO v_count
  FROM public.accounts
  WHERE parent_id IS NULL AND account_code NOT IN ('1', '2', '3', '4', '9');
  IF v_count > 0 THEN
    RAISE EXCEPTION 'Verification Failed: Found % orphan root accounts with parent_id IS NULL outside of standard roots (1,2,3,4,9).', v_count;
  END IF;

  -- Ø§Ù„ØªØ­Ù‚Ù‚ Ù…Ù† ØµØ­Ø© Ø¥Ø¹Ø¯Ø§Ø¯Ø§Øª Ø­Ø³Ø§Ø¨ Ø¬Ø§Ø±ÙŠ Ø§Ù„Ù…Ø³Ø§Ù‡Ù…ÙŠÙ† 2321
  IF NOT EXISTS (
    SELECT 1 FROM public.accounts 
    WHERE account_code = '2321' 
      AND level = 4 
