      AND allow_posting = false
  ) THEN
    RAISE EXCEPTION 'Verification Failed: Account 2321 must exist at level 4 with is_leaf=false and allow_posting=false.';
  END IF;

  -- Ø§Ù„ØªØ­Ù‚Ù‚ Ù…Ù† Ø§Ù„Ø®Ø²ÙŠÙ†Ø© Ø§Ù„Ø±Ø¦ÙŠØ³ÙŠØ© ÙˆØ§Ù„Ø±Ø¨Ø· (multi-tenant: Ø¹Ø¯Ø¯ Ø§Ù„Ø´Ø±ÙƒØ§Øª Ã— Ø§Ù„Ø¹Ù…Ù„Ø§Øª)
  SELECT COUNT(*) INTO v_main_treasury FROM public.treasuries WHERE type = 'main';
  SELECT COUNT(*) INTO v_treasury_currencies FROM public.treasury_balances;
  SELECT COUNT(*) INTO v_treasury_links_ok FROM public.treasury_balances tb JOIN public.accounts a ON tb.account_id = a.id;

  IF v_main_treasury < 1 THEN
    RAISE EXCEPTION 'Verification Failed: No main treasury found (count=%)', v_main_treasury;
  END IF;
  IF v_treasury_currencies < 4 THEN
    RAISE EXCEPTION 'Verification Failed: Treasury currencies insufficient (count=%, expected >= 4)', v_treasury_currencies;
  END IF;
  IF v_treasury_links_ok < 4 THEN
    RAISE EXCEPTION 'Verification Failed: Treasury GL links insufficient (count=%, expected >= 4)', v_treasury_links_ok;
  END IF;

  -- Ø§Ù„ØªØ­Ù‚Ù‚ Ù…Ù† Ø§Ù„Ø¨Ù†ÙˆÙƒ ÙˆØ§Ù„Ù…Ø®Ø§Ø²Ù† (multi-tenant: Ø¹Ø¯Ø¯ Ø§Ù„Ø´Ø±ÙƒØ§Øª Ã— Ø§Ù„Ø£ØµÙˆÙ„)
  SELECT COUNT(*) INTO v_bank_accounts FROM public.bank_accounts;
  SELECT COUNT(*) INTO v_warehouses FROM public.warehouses;

  IF v_bank_accounts < 4 THEN
    RAISE EXCEPTION 'Verification Failed: Bank accounts insufficient (count=%, expected >= 4)', v_bank_accounts;
  END IF;
  IF v_warehouses < 3 THEN
    RAISE EXCEPTION 'Verification Failed: Warehouses insufficient (count=%, expected >= 3)', v_warehouses;
  END IF;

  SELECT COUNT(*) INTO v_total_accounts FROM public.accounts;

  RAISE NOTICE '======================================================';
  RAISE NOTICE '   ENTERPRISE HANDOVER RESET COMPLETED SUCCESSFULLY   ';
  RAISE NOTICE '======================================================';
  RAISE NOTICE '  âœ“ All Operational Transactions Reset to 0';
  RAISE NOTICE '  âœ“ Companies: %   Total Standard Accounts: %', v_company_count, v_total_accounts;
  RAISE NOTICE '  âœ“ Main Treasuries: %  with % Currencies & % GL Links', v_main_treasury, v_treasury_currencies, v_treasury_links_ok;
  RAISE NOTICE '  âœ“ Bank Accounts: %  Warehouses: %', v_bank_accounts, v_warehouses;
  RAISE NOTICE '  âœ“ Sub-Warehouses / Stations: Reset to 0 (Fresh Start for Client)';
  RAISE NOTICE '  âœ“ Auto-Creation Entity Triggers: PASS';
  RAISE NOTICE '  âœ“ Database Ready for Client Handover: 100%%';
  RAISE NOTICE '======================================================';
END $$;

-- ============================================================================
-- Ø¶Ù…Ø§Ù† ØªÙˆØ§ÙÙ‚ Ø¯Ø§Ù„Ø© Ù…Ø²Ø§Ù…Ù†Ø© Ø§Ù„Ø£Ø±ØµØ¯Ø© Ø§Ù„Ø§ÙØªØªØ§Ø­ÙŠØ© Ù…Ø¹ ÙƒØ§ÙØ© Ø§Ù„ÙƒÙŠØ§Ù†Ø§Øª (shareholders, customers, suppliers)
-- Ù‚Ø¨Ù„ Ø¥Ø¹Ø§Ø¯Ø© ØªÙØ¹ÙŠÙ„ Ø§Ù„ØªØ±ÙŠØ¬Ø±Ø² Ù„ØªØ¬Ù†Ø¨ Ø£Ø®Ø·Ø§Ø¡ 42703 Ø£Ø«Ù†Ø§Ø¡ Ø¥Ø¯Ø®Ø§Ù„ Ø§Ù„Ø¨ÙŠØ§Ù†Ø§Øª Ø§Ù„Ù…Ø±Ø¬Ø¹ÙŠØ©
-- ============================================================================
CREATE OR REPLACE FUNCTION public.sync_entity_opening_balance_gl()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_equity_account_id BIGINT;
    v_je_id BIGINT;
    v_desc TEXT;
    v_account_id BIGINT;
    v_company_id UUID;
    v_new_balance NUMERIC;
    v_direction TEXT;
    v_currency TEXT;
    v_source_id TEXT;
    v_entry_number TEXT;
    v_new_json JSONB;
    v_old_json JSONB;
    v_is_multi BOOLEAN := false;
    v_balances_map JSONB := NULL;
    r_key TEXT;
    r_item JSONB;
    r_cur TEXT;
    r_amt NUMERIC;
    r_dir TEXT;
    r_rate NUMERIC;
    r_base_amt NUMERIC;
    r_has_entries BOOLEAN := false;
    v_base_balance NUMERIC;
BEGIN
    v_new_json := to_jsonb(NEW);
    IF TG_OP = 'UPDATE' THEN
        v_old_json := to_jsonb(OLD);
    END IF;

    -- Ø§Ù„ØªØ­Ù‚Ù‚ Ù…Ù† Ø­Ø¯ÙˆØ« ØªØºÙŠÙŠØ± ÙØ¹Ù„ÙŠ ÙÙŠ Ø§Ù„Ø±ØµÙŠØ¯ Ø£Ùˆ Ø§Ù„Ø§ØªØ¬Ø§Ù‡ Ø£Ùˆ Ø®Ø±ÙŠØ·Ø© Ø§Ù„Ø¹Ù…Ù„Ø§Øª Ø¹Ù†Ø¯ Ø§Ù„Ù€ UPDATE
    IF TG_OP = 'UPDATE' THEN
        IF TG_TABLE_NAME = 'shareholders' THEN
            IF (v_new_json->>'initial_balance_egp') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_egp') 
               AND (v_new_json->>'initial_balance_usd') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_usd')
               AND (v_new_json->>'initial_balance_eur') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_eur')
               AND (v_new_json->>'initial_balance_gbp') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_gbp')
               AND (v_new_json->>'initial_balance_direction') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_direction')
               AND (v_new_json->>'initial_balance_direction_egp') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_direction_egp')
               AND (v_new_json->>'account_id') IS NOT DISTINCT FROM (v_old_json->>'account_id') THEN
                RETURN NEW;
            END IF;
        ELSIF TG_TABLE_NAME = 'suppliers' THEN
            IF (v_new_json->>'initial_balance') IS NOT DISTINCT FROM (v_old_json->>'initial_balance') 
               AND (v_new_json->>'initial_balance_direction') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_direction')
               AND (v_new_json->'initial_balances_by_currency') IS NOT DISTINCT FROM (v_old_json->'initial_balances_by_currency')
               AND (v_new_json->>'account_id') IS NOT DISTINCT FROM (v_old_json->>'account_id') THEN
                RETURN NEW;
            END IF;
        ELSE
            IF (v_new_json->>'initial_balance') IS NOT DISTINCT FROM (v_old_json->>'initial_balance') 
               AND (v_new_json->>'initial_balance_direction') IS NOT DISTINCT FROM (v_old_json->>'initial_balance_direction')
               AND (v_new_json->>'account_id') IS NOT DISTINCT FROM (v_old_json->>'account_id') THEN
                RETURN NEW;
            END IF;
        END IF;
    END IF;

    -- Ø§Ø³ØªØ®Ø±Ø§Ø¬ Ø§Ù„Ø±ØµÙŠØ¯ ÙˆØ§Ù„ÙˆØµÙ Ø¨Ø­Ø³Ø¨ Ø§Ù„Ø¬Ø¯ÙˆÙ„
    IF TG_TABLE_NAME = 'shareholders' THEN
        v_new_balance := COALESCE((v_new_json->>'initial_balance_egp')::numeric, 0);
        v_desc := 'Ø±ØµÙŠØ¯ Ø§ÙØªØªØ§Ø­ÙŠ - ' || COALESCE(v_new_json->>'name', '');
    ELSIF TG_TABLE_NAME = 'customers' THEN
        v_new_balance := COALESCE((v_new_json->>'initial_balance')::numeric, 0);
        v_desc := 'Ø±ØµÙŠØ¯ Ø§ÙØªØªØ§Ø­ÙŠ - ' || COALESCE(v_new_json->>'name', '');
    ELSIF TG_TABLE_NAME = 'clearing_agents' THEN
        v_new_balance := COALESCE((v_new_json->>'initial_balance')::numeric, 0);
        v_desc := 'Ø±ØµÙŠØ¯ Ø§ÙØªØªØ§Ø­ÙŠ - ' || COALESCE(v_new_json->>'name', '');
    ELSIF TG_TABLE_NAME = 'shipping_companies' THEN
        v_new_balance := COALESCE((v_new_json->>'initial_balance')::numeric, 0);
        v_desc := 'Ø±ØµÙŠØ¯ Ø§ÙØªØªØ§Ø­ÙŠ - ' || COALESCE(v_new_json->>'name', '');
    ELSIF TG_TABLE_NAME = 'transport_suppliers' THEN
        v_new_balance := COALESCE((v_new_json->>'initial_balance')::numeric, 0);
        v_desc := 'Ø±ØµÙŠØ¯ Ø§ÙØªØªØ§Ø­ÙŠ - ' || COALESCE(v_new_json->>'name', '');
    ELSIF TG_TABLE_NAME = 'suppliers' THEN
        v_new_balance := COALESCE((v_new_json->>'initial_balance')::numeric, 0);
        v_desc := 'Ø±ØµÙŠØ¯ Ø£ÙˆÙ„ Ø§Ù„Ù…Ø¯Ø© Ù„Ù„Ù…ÙˆØ±Ø¯: ' || COALESCE(v_new_json->>'name', '');
    ELSE
        v_new_balance := COALESCE((v_new_json->>'initial_balance')::numeric, 0);
        v_desc := 'Ø±ØµÙŠØ¯ Ø§ÙØªØªØ§Ø­ÙŠ - ' || COALESCE(v_new_json->>'name', '');
    END IF;

    IF (v_new_json->>'account_id') IS NOT NULL THEN
        v_account_id := (v_new_json->>'account_id')::bigint;
    END IF;
    IF (v_new_json->>'company_id') IS NOT NULL THEN
        v_company_id := (v_new_json->>'company_id')::uuid;
    END IF;
    
    -- Ø§Ù„Ø§ØªØ¬Ø§Ù‡ Ø§Ù„Ø§ÙØªØ±Ø§Ø¶ÙŠ
    IF TG_TABLE_NAME = 'customers' THEN
        v_direction := COALESCE(v_new_json->>'initial_balance_direction', 'DEBIT');
    ELSIF TG_TABLE_NAME = 'shareholders' THEN
        v_direction := COALESCE(v_new_json->>'initial_balance_direction_egp', v_new_json->>'initial_balance_direction', 'CREDIT');
    ELSE
        v_direction := COALESCE(v_new_json->>'initial_balance_direction', 'CREDIT');
    END IF;
    
    -- Ø§Ø³ØªØ®Ø±Ø§Ø¬ Ø§Ù„Ø¹Ù…Ù„Ø©
    v_currency := UPPER(COALESCE(v_new_json->>'currency', 'EGP'));
    IF v_currency = '' OR v_currency = 'MULTI' THEN
        v_currency := 'EGP';
    END IF;

    -- Ø­Ù„ Ø§Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„Ù…Ø§Ù„ÙŠ ÙÙŠ Ø­Ø§Ù„ Ø¹Ø¯Ù… ØªÙ…Ø±ÙŠØ± account_id
    IF v_account_id IS NULL THEN
        IF TG_TABLE_NAME = 'customers' THEN
            SELECT id INTO v_account_id FROM accounts 
            WHERE (
                (COALESCE(v_new_json->>'company_type', v_new_json->>'customer_type', 'export') IN ('local', 'Ù…Ø­Ù„ÙŠ', 'local_customer', 'Ø¹Ù…Ù„Ø§Ø¡ Ù…Ø­Ù„ÙŠ') AND account_code = '12512')
                OR (COALESCE(v_new_json->>'company_type', v_new_json->>'customer_type', 'export') NOT IN ('local', 'Ù…Ø­Ù„ÙŠ', 'local_customer', 'Ø¹Ù…Ù„Ø§Ø¡ Ù…Ø­Ù„ÙŠ') AND account_code = '12511')
                OR account_code IN ('12511', '12512', '1251')
            )
              AND (company_id = v_company_id OR company_id IS NULL) 
            ORDER BY (company_id = v_company_id) DESC, id ASC 
            LIMIT 1;
        ELSIF TG_TABLE_NAME = 'suppliers' THEN
            -- Resolve exact Level-5 account based on supplier_type, category, or code range
            IF (v_new_json->>'supplier_type' IN ('packaging', 'sticker')
                OR v_new_json->>'category' IN ('packaging', 'Ù…ÙˆØ§Ø¯ ØªØ¹Ø¨Ø¦Ø©', 'ØªØ¹Ø¨Ø¦Ø©', 'ÙƒØ±ØªÙˆÙ†', 'Ø§Ø³ØªÙŠÙƒØ±')
                OR (v_new_json->>'code')::text LIKE '70%' OR (v_new_json->>'code')::text LIKE '71%'
                OR (v_new_json->>'code')::text LIKE '72%' OR (v_new_json->>'code')::text LIKE '73%'
                OR (v_new_json->>'code')::text LIKE '74%') THEN
                SELECT id INTO v_account_id FROM accounts WHERE account_code = '21112' AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            ELSIF (v_new_json->>'supplier_type' IN ('shared')
                OR v_new_json->>'category' IN ('shared', 'Ù…Ø´ØªØ±Ùƒ', 'Ù…Ø´ØªØ±ÙƒÙŠÙ†')
                OR (v_new_json->>'code')::text LIKE '75%' OR (v_new_json->>'code')::text LIKE '76%'
                OR (v_new_json->>'code')::text LIKE '77%' OR (v_new_json->>'code')::text LIKE '78%'
                OR (v_new_json->>'code')::text LIKE '79%') THEN
                SELECT id INTO v_account_id FROM accounts WHERE account_code = '21114' AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            ELSIF (v_new_json->>'supplier_type' IN ('transport') OR (v_new_json->>'code')::text LIKE '6%') THEN
                SELECT id INTO v_account_id FROM accounts WHERE account_code = '21111' AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            ELSIF (v_new_json->>'supplier_type' IN ('shipping') OR (v_new_json->>'code')::text LIKE '9%') THEN
                SELECT id INTO v_account_id FROM accounts WHERE account_code = '21115' AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            ELSIF (v_new_json->>'supplier_type' IN ('clearing', 'customs')) THEN
                SELECT id INTO v_account_id FROM accounts WHERE account_code = '21116' AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            ELSE
                -- Default: Crop Purchase Suppliers (50000-59999)
                SELECT id INTO v_account_id FROM accounts WHERE account_code = '21113' AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            END IF;

            IF v_account_id IS NULL THEN
                SELECT id INTO v_account_id FROM accounts WHERE account_code IN ('21113', '2111', '2110') AND (company_id = v_company_id OR company_id IS NULL) ORDER BY (company_id = v_company_id) DESC, id ASC LIMIT 1;
            END IF;
        ELSIF TG_TABLE_NAME = 'clearing_agents' THEN
            SELECT id INTO v_account_id FROM accounts 
            WHERE account_code = '21116'
              AND (company_id = v_company_id OR company_id IS NULL) 
            ORDER BY (company_id = v_company_id) DESC, id ASC 
            LIMIT 1;
        ELSIF TG_TABLE_NAME = 'shipping_companies' THEN
            SELECT id INTO v_account_id FROM accounts 
            WHERE account_code = '21115'
              AND (company_id = v_company_id OR company_id IS NULL) 
            ORDER BY (company_id = v_company_id) DESC, id ASC 
            LIMIT 1;
        ELSIF TG_TABLE_NAME = 'transport_suppliers' THEN
            SELECT id INTO v_account_id FROM accounts 
            WHERE account_code = '21111'
              AND (company_id = v_company_id OR company_id IS NULL) 
            ORDER BY (company_id = v_company_id) DESC, id ASC 
            LIMIT 1;
        END IF;
    END IF;

    IF v_account_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Ù…Ø¹Ø±Ù Ù…ØµØ¯Ø± Ù…ÙˆØ­Ø¯ ÙˆØºÙŠØ± Ù‚Ø§Ø¨Ù„ Ù„Ù„ØªØ¹Ø§Ø±Ø¶ Ø¨ÙŠÙ† Ø§Ù„Ø¬Ø¯Ø§ÙˆÙ„
    v_source_id := TG_TABLE_NAME || '_' || (v_new_json->>'id');

    -- Ø§Ù„Ø¨Ø­Ø« Ø¹Ù† Ù‚ÙŠØ¯ Ù…ÙˆØ¬ÙˆØ¯ Ù…Ø³Ø¨Ù‚Ø§Ù‹ Ù„Ù‡Ø°Ø§ Ø§Ù„Ø³Ø¬Ù„
    SELECT id INTO v_je_id
    FROM journal_entries
    WHERE source_type::text = 'opening_balance' 
      AND (source_id::text = v_source_id OR source_id::text = (v_new_json->>'id'))
      AND (company_id = v_company_id OR company_id IS NULL)
    ORDER BY id DESC
    LIMIT 1;

    -- ØªÙ‡ÙŠØ¦Ø© Ù…Ø³Ø§Ø± Ø§Ù„Ø¹Ù…Ù„Ø§Øª Ø§Ù„Ù…ØªØ¹Ø¯Ø¯Ø© (Suppliers Ø£Ùˆ Shareholders)
    IF TG_TABLE_NAME = 'suppliers' THEN
        v_is_multi := COALESCE((v_new_json->>'is_multi_currency')::boolean, false);
        v_balances_map := v_new_json->'initial_balances_by_currency';
    ELSIF TG_TABLE_NAME = 'shareholders' THEN
        v_is_multi := true;
        v_balances_map := jsonb_build_object(
            'EGP', jsonb_build_object('amount', COALESCE((v_new_json->>'initial_balance_egp')::numeric, 0), 'direction', COALESCE(v_new_json->>'initial_balance_direction_egp', v_new_json->>'initial_balance_direction', 'CREDIT')),
            'USD', jsonb_build_object('amount', COALESCE((v_new_json->>'initial_balance_usd')::numeric, 0), 'direction', COALESCE(v_new_json->>'initial_balance_direction', 'CREDIT')),
            'EUR', jsonb_build_object('amount', COALESCE((v_new_json->>'initial_balance_eur')::numeric, 0), 'direction', COALESCE(v_new_json->>'initial_balance_direction', 'CREDIT')),
            'GBP', jsonb_build_object('amount', COALESCE((v_new_json->>'initial_balance_gbp')::numeric, 0), 'direction', COALESCE(v_new_json->>'initial_balance_direction', 'CREDIT'))
        );
    END IF;

    IF (TG_TABLE_NAME = 'suppliers' AND v_is_multi = true AND v_balances_map IS NOT NULL AND jsonb_typeof(v_balances_map) = 'object')
       OR (TG_TABLE_NAME = 'shareholders' AND v_balances_map IS NOT NULL) THEN
        
        -- Ø§Ù„ØªØ£ÙƒØ¯ Ù…Ù† ÙˆØ¬ÙˆØ¯ Ø¹Ù…Ù„Ø© ÙˆØ§Ø­Ø¯Ø© Ø¹Ù„Ù‰ Ø§Ù„Ø£Ù‚Ù„ Ø¨Ø±ØµÙŠØ¯ Ø£ÙƒØ¨Ø± Ù…Ù† ØµÙØ±
        FOR r_key, r_item IN SELECT * FROM jsonb_each(v_balances_map) LOOP
            IF COALESCE((r_item->>'amount')::numeric, 0) > 0 THEN
                r_has_entries := true;
            END IF;
        END LOOP;

        IF NOT r_has_entries THEN
            IF v_je_id IS NOT NULL THEN
                DELETE FROM account_ledger_entries WHERE journal_entry_id = v_je_id;
                DELETE FROM journal_entries WHERE id = v_je_id;
            END IF;
            RETURN NEW;
        END IF;

        IF v_je_id IS NOT NULL THEN
            DELETE FROM account_ledger_entries WHERE journal_entry_id = v_je_id;
            UPDATE journal_entries 
            SET description = v_desc,
                source_id = v_source_id,
                entry_date = CURRENT_DATE,
                status = 'posted'
            WHERE id = v_je_id;
        ELSE
            -- ØªÙˆÙ„ÙŠØ¯ Ø­ØªÙ…ÙŠ Ø¢Ù…Ù† Ø¨Ø¯ÙˆÙ† Ø£ÙŠ Race condition
            v_entry_number := public.fn_get_next_sequence(v_company_id, 'opening_balance', NULL, NULL);
            IF v_entry_number IS NULL OR v_entry_number = '' THEN
                RAISE EXCEPTION 'Failed to generate entry_number via fn_get_next_sequence for opening_balance (company_id: %)', v_company_id;
            END IF;

            INSERT INTO journal_entries (
                source_type, source_id, entry_date, description, created_by, company_id, entry_number, status
            ) VALUES (
                'opening_balance', v_source_id, CURRENT_DATE, v_desc, auth.uid(), v_company_id, v_entry_number, 'posted'
            ) RETURNING id INTO v_je_id;
        END IF;

        -- Ø¥Ù†Ø´Ø§Ø¡ Ø³Ø·ÙˆØ± Ø§Ù„Ø£Ø³ØªØ§Ø° Ù„ÙƒÙ„ Ø¹Ù…Ù„Ø© Ø°Ø§Øª Ø±ØµÙŠØ¯ Ù…ÙˆØ¬Ø¨ ÙÙ‚Ø·
        FOR r_key, r_item IN SELECT * FROM jsonb_each(v_balances_map) LOOP
            r_cur := UPPER(COALESCE(r_item->>'currency', r_key));
            r_amt := COALESCE((r_item->>'amount')::numeric, 0);
            r_dir := UPPER(COALESCE(r_item->>'direction', 'CREDIT'));
            
            -- Ø¬Ù„Ø¨ Ø³Ø¹Ø± Ø§Ù„ØµØ±Ù Ø¨Ø´ÙƒÙ„ Ø­ØªÙ…ÙŠ 100%
            IF r_cur = 'EGP' THEN
                r_rate := 1.0;
            ELSE
                r_rate := COALESCE((r_item->>'exchange_rate')::numeric, NULL);
                IF r_rate IS NULL OR r_rate <= 0 THEN
                    SELECT rate_to_egp INTO r_rate 
                    FROM exchange_rates 
                    WHERE currency_code = r_cur 
                    ORDER BY effective_from DESC, updated_at DESC, id DESC 
                    LIMIT 1;
                END IF;
                IF r_rate IS NULL OR r_rate <= 0 THEN r_rate := 1.0; END IF;
            END IF;

            r_base_amt := r_amt * r_rate;

            IF r_amt > 0 THEN
                -- Ø­Ù„ Ø­Ø³Ø§Ø¨ Ø­Ù‚ÙˆÙ‚ Ø§Ù„Ù…Ù„ÙƒÙŠØ© Ø§Ù„Ù…Ù‚Ø§Ø¨Ù„
                v_equity_account_id := public.resolve_opening_balance_equity_account(r_cur, v_company_id);

                IF v_equity_account_id IS NULL THEN
                    SELECT id INTO v_equity_account_id
                    FROM accounts
                    WHERE account_code::text = ANY(
                        CASE r_cur
                            WHEN 'USD' THEN ARRAY['23421', '2332', '3902', '2312', '3002']
                            WHEN 'EUR' THEN ARRAY['23421', '2333', '3903', '2313', '3003']
                            WHEN 'GBP' THEN ARRAY['23421', '2334', '3904', '2314', '3004']
                            ELSE ARRAY['23421', '2331', '3901', '2311', '3001']
                        END
                    )
                    AND (company_id = v_company_id OR company_id IS NULL)
                    ORDER BY (company_id = v_company_id) DESC, id ASC
                    LIMIT 1;
                END IF;

                IF v_equity_account_id IS NULL THEN
                    SELECT id INTO v_equity_account_id
                    FROM accounts
                    WHERE account_code::text IN ('23421', '2342', '2330', '233', '2310', '231', '3900', '3901', '3001', '3000', '3300')
                      AND (company_id = v_company_id OR company_id IS NULL)
                    ORDER BY (company_id = v_company_id) DESC, id ASC
                    LIMIT 1;
                END IF;

                IF v_equity_account_id IS NULL THEN
                    SELECT id INTO v_equity_account_id
                    FROM accounts
                    WHERE account_type = 'equity' AND (allow_posting = true OR is_leaf = true)
                      AND (company_id = v_company_id OR company_id IS NULL)
                    ORDER BY (company_id = v_company_id) DESC, id ASC
                    LIMIT 1;
                END IF;

                -- Ø¥Ø¯Ø±Ø§Ø¬ Ø³Ø·Ø±ÙŠÙ† Ù…ØªØ²Ù†ÙŠÙ† Ù„Ù„Ù‚ÙŠØ¯
                IF v_account_id IS NOT NULL AND v_equity_account_id IS NOT NULL THEN
                    IF r_dir = 'DEBIT' THEN
                        INSERT INTO account_ledger_entries (journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id)
                        VALUES (v_je_id, v_account_id, r_amt, 0, r_cur, r_base_amt, v_desc || ' (' || r_cur || ')', v_company_id);
                        INSERT INTO account_ledger_entries (journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id)
                        VALUES (v_je_id, v_equity_account_id, 0, r_amt, r_cur, r_base_amt, v_desc || ' (' || r_cur || ')', v_company_id);
                    ELSE
                        INSERT INTO account_ledger_entries (journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id)
                        VALUES (v_je_id, v_account_id, 0, r_amt, r_cur, r_base_amt, v_desc || ' (' || r_cur || ')', v_company_id);
                        INSERT INTO account_ledger_entries (journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id)
                        VALUES (v_je_id, v_equity_account_id, r_amt, 0, r_cur, r_base_amt, v_desc || ' (' || r_cur || ')', v_company_id);
                    END IF;
                END IF;
            END IF;
        END LOOP;

        RETURN NEW;
    END IF;

    -- =========================================================================
    -- Ù…Ø³Ø§Ø± Ø§Ù„Ø¹Ù…Ù„Ø© Ø§Ù„ÙØ±Ø¯ÙŠØ© Ø§Ù„Ù‚ÙŠØ§Ø³ÙŠ (Customers, Clearing, Shipping, Transport, Single-currency Suppliers)
    -- =========================================================================
    v_equity_account_id := public.resolve_opening_balance_equity_account(v_currency, v_company_id);

    IF v_equity_account_id IS NULL THEN
        SELECT id INTO v_equity_account_id
        FROM accounts
        WHERE account_code::text = ANY(
            CASE v_currency
                WHEN 'USD' THEN ARRAY['23421', '2332', '3902', '2312', '3002']
                WHEN 'EUR' THEN ARRAY['23421', '2333', '3903', '2313', '3003']
                WHEN 'GBP' THEN ARRAY['23421', '2334', '3904', '2314', '3004']
                ELSE ARRAY['23421', '2331', '3901', '2311', '3001']
            END
        )
        AND (company_id = v_company_id OR company_id IS NULL)
        ORDER BY (company_id = v_company_id) DESC, id ASC
        LIMIT 1;
    END IF;

    IF v_equity_account_id IS NULL THEN
        SELECT id INTO v_equity_account_id
        FROM accounts
        WHERE account_code::text IN ('23421', '2342', '2330', '233', '2310', '231', '3900', '3901', '3001', '3000', '3300')
          AND (company_id = v_company_id OR company_id IS NULL)
        ORDER BY (company_id = v_company_id) DESC, id ASC
        LIMIT 1;
    END IF;

    IF v_equity_account_id IS NULL THEN
        SELECT id INTO v_equity_account_id
        FROM accounts
        WHERE account_type = 'equity' AND (allow_posting = true OR is_leaf = true)
          AND (company_id = v_company_id OR company_id IS NULL)
        ORDER BY (company_id = v_company_id) DESC, id ASC
        LIMIT 1;
    END IF;
    
    IF v_equity_account_id IS NULL OR v_account_id IS NULL THEN
        RETURN NEW;
    END IF;

    IF v_je_id IS NOT NULL THEN
        DELETE FROM account_ledger_entries WHERE journal_entry_id = v_je_id;
        
        IF v_new_balance = 0 THEN
            DELETE FROM journal_entries WHERE id = v_je_id;
            RETURN NEW;
        END IF;

        UPDATE journal_entries 
        SET description = v_desc,
            source_id = v_source_id,
            entry_date = CURRENT_DATE,
            status = 'posted'
        WHERE id = v_je_id;
    ELSE
        IF v_new_balance = 0 THEN
            RETURN NEW;
        END IF;
        
        -- ØªÙˆÙ„ÙŠØ¯ Ø­ØªÙ…ÙŠ Ø¢Ù…Ù† Ø¨Ø¯ÙˆÙ† Ø£ÙŠ Race condition
        v_entry_number := public.fn_get_next_sequence(v_company_id, 'opening_balance', NULL, NULL);
        IF v_entry_number IS NULL OR v_entry_number = '' THEN
            RAISE EXCEPTION 'Failed to generate entry_number via fn_get_next_sequence for opening_balance (company_id: %)', v_company_id;
        END IF;

        INSERT INTO journal_entries (
            source_type, source_id, entry_date, description, created_by, company_id, entry_number, status
        ) VALUES (
            'opening_balance', v_source_id, CURRENT_DATE, v_desc, auth.uid(), v_company_id, v_entry_number, 'posted'
        ) RETURNING id INTO v_je_id;
    END IF;

    -- Ø­Ø³Ø§Ø¨ Ø§Ù„Ù‚ÙŠÙ…Ø© Ø¨Ø§Ù„Ø¹Ù…Ù„Ø© Ø§Ù„Ù…Ø­Ù„ÙŠØ© Ù…Ø¹ ØªØ­Ø¯ÙŠØ¯ Ø³Ø¹Ø± Ø§Ù„ØµØ±Ù Ø­ØªÙ…ÙŠØ§Ù‹
    r_rate := 1.0;
    IF v_currency IS NOT NULL AND v_currency <> 'EGP' THEN
        SELECT rate_to_egp INTO r_rate 
        FROM exchange_rates 
        WHERE currency_code = v_currency 
        ORDER BY effective_from DESC, updated_at DESC, id DESC 
        LIMIT 1;
        IF r_rate IS NULL OR r_rate <= 0 THEN r_rate := 1.0; END IF;
    END IF;
    v_base_balance := v_new_balance * r_rate;

    -- Ø¥Ù†Ø´Ø§Ø¡ Ø³Ø·ÙˆØ± Ø§Ù„Ù‚ÙŠØ¯ Ø¨Ù†Ø§Ø¡Ù‹ Ø¹Ù„Ù‰ Ø§Ù„Ø§ØªØ¬Ø§Ù‡ Ø§Ù„Ù…Ø­Ø¯Ø¯
    IF v_direction = 'DEBIT' THEN
        INSERT INTO account_ledger_entries (
            journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id
        ) VALUES (
            v_je_id, v_account_id, v_new_balance, 0, v_currency, v_base_balance, v_desc, v_company_id
        );
        INSERT INTO account_ledger_entries (
            journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id
        ) VALUES (
            v_je_id, v_equity_account_id, 0, v_new_balance, v_currency, v_base_balance, v_desc, v_company_id
        );
    ELSE
        INSERT INTO account_ledger_entries (
            journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id
        ) VALUES (
            v_je_id, v_account_id, 0, v_new_balance, v_currency, v_base_balance, v_desc, v_company_id
        );
        INSERT INTO account_ledger_entries (
            journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id
        ) VALUES (
            v_je_id, v_equity_account_id, v_new_balance, 0, v_currency, v_base_balance, v_desc, v_company_id
        );
    END IF;

    RETURN NEW;
END;
$$;

-- Ø¥Ø¹Ø§Ø¯Ø© ØªÙØ¹ÙŠÙ„ ØªØ±ÙŠØ¬Ø±Ø² Ø§Ù„Ù†Ø¸Ø§Ù… Ø¥Ù„Ù‰ Ø§Ù„ÙˆØ¶Ø¹ Ø§Ù„Ø·Ø¨ÙŠØ¹ÙŠ
SET LOCAL session_replication_role = 'origin';

-- ØªÙØ¹ÙŠÙ„ ØªØ±ÙŠØ¬Ø±Ø² Ù…Ø²Ø§Ù…Ù†Ø© Ø§Ù„Ø£Ø±ØµØ¯Ø© Ø§Ù„Ø§ÙØªØªØ§Ø­ÙŠØ© Ù…Ø¹ Ø¯ÙØªØ± Ø§Ù„Ø£Ø³ØªØ§Ø° Ø§Ù„Ø¹Ø§Ù… Ù„ÙƒØ§ÙØ© Ø§Ù„ÙƒÙŠØ§Ù†Ø§Øª
DROP TRIGGER IF EXISTS trg_supplier_opening_balance_gl ON public.suppliers;
CREATE TRIGGER trg_supplier_opening_balance_gl
AFTER INSERT OR UPDATE OF initial_balance, initial_balance_direction, initial_balances_by_currency, account_id
ON public.suppliers
FOR EACH ROW EXECUTE FUNCTION public.sync_entity_opening_balance_gl();

DROP TRIGGER IF EXISTS trg_customer_opening_balance_gl ON public.customers;
CREATE TRIGGER trg_customer_opening_balance_gl
AFTER INSERT OR UPDATE OF initial_balance, initial_balance_direction, account_id
ON public.customers
FOR EACH ROW EXECUTE FUNCTION public.sync_entity_opening_balance_gl();

-- âš ï¸ ORDER-DEPENDENT: assumes trg_create_shareholder_account (alphabetically
-- earlier) fires first on the same AFTER INSERT event and populates account_id
-- via its own UPDATE, which re-triggers this trigger. Renaming either trigger
-- breaks this chain silently.
DROP TRIGGER IF EXISTS trg_shareholder_opening_balance_gl ON public.shareholders;
CREATE TRIGGER trg_shareholder_opening_balance_gl
AFTER INSERT OR UPDATE OF initial_balance_egp, initial_balance_usd, initial_balance_eur, initial_balance_gbp, initial_balance_direction, initial_balance_direction_egp, account_id
ON public.shareholders
FOR EACH ROW EXECUTE FUNCTION public.sync_entity_opening_balance_gl();

DROP TRIGGER IF EXISTS trg_shipping_company_opening_balance_gl ON public.shipping_companies;
CREATE TRIGGER trg_shipping_company_opening_balance_gl
AFTER INSERT OR UPDATE OF initial_balance, initial_balance_direction, account_id
ON public.shipping_companies
FOR EACH ROW EXECUTE FUNCTION public.sync_entity_opening_balance_gl();

DROP TRIGGER IF EXISTS trg_clearing_agent_opening_balance_gl ON public.clearing_agents;
CREATE TRIGGER trg_clearing_agent_opening_balance_gl
AFTER INSERT OR UPDATE OF initial_balance, initial_balance_direction, account_id
ON public.clearing_agents
FOR EACH ROW EXECUTE FUNCTION public.sync_entity_opening_balance_gl();

DROP TRIGGER IF EXISTS trg_transport_supplier_opening_balance_gl ON public.transport_suppliers;
CREATE TRIGGER trg_transport_supplier_opening_balance_gl
AFTER INSERT OR UPDATE OF initial_balance, initial_balance_direction, account_id
ON public.transport_suppliers
FOR EACH ROW EXECUTE FUNCTION public.sync_entity_opening_balance_gl();

CREATE OR REPLACE FUNCTION public.rpc_apply_packing_order_item_debit_note(
    p_order_id BIGINT,
    p_item_type TEXT,
    p_item_id BIGINT DEFAULT NULL,
    p_batch_id BIGINT DEFAULT NULL,
    p_discount_amount NUMERIC DEFAULT 0,
    p_reason TEXT DEFAULT NULL,
    p_supplier_uuid UUID DEFAULT NULL,
    p_user_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_order RECORD;
    v_company_id UUID;
    v_entry_date DATE;
    v_supplier_uuid UUID := p_supplier_uuid;
    v_supplier_name TEXT;
    v_supplier_currency TEXT := 'EGP';
    v_exchange_rate NUMERIC := 1.0;
    v_foreign_discount NUMERIC;
    v_applied NUMERIC;
    v_old_total NUMERIC;
    v_new_total NUMERIC;
    v_qty NUMERIC;
    v_cost_center_id TEXT;
    v_cost_center_name TEXT;
    v_cost_center_type TEXT := 'operational';
    v_item_name TEXT := 'Ø¨Ù†Ø¯ Ø£Ù…Ø± ØªØ¹Ø¨Ø¦Ø©';
    v_category TEXT := 'Ù…ÙˆØ§Ø¯ Ø§Ù„ØªØ¹Ø¨Ø¦Ø©';
    v_source_account_id UUID;
    v_dest_account_id UUID;
    v_is_shipped BOOLEAN;
    v_notes JSONB;
    v_elem JSONB;
    v_je_id UUID;
    v_entry_num TEXT;
BEGIN
    -- 1. Validate & Lock Packing Order
    SELECT * INTO v_order FROM public.packing_orders WHERE id = p_order_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Ø£Ù…Ø± Ø§Ù„ØªØ¹Ø¨Ø¦Ø© ØºÙŠØ± Ù…ÙˆØ¬ÙˆØ¯');
    END IF;

    IF p_discount_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Ù…Ø¨Ù„Øº Ø§Ù„Ø®ØµÙ… ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† Ø£ÙƒØ¨Ø± Ù…Ù† Ø§Ù„ØµÙØ±');
    END IF;

    -- 2. Check Profit Distribution Lock
    IF EXISTS (
        SELECT 1 
        FROM public.export_shipment_items esi
        JOIN public.shareholder_profit_distributions spd ON spd.shipment_id = esi.shipment_id
        WHERE esi.packing_order_id = p_order_id
          AND spd.deleted_at IS NULL
    ) THEN
        RETURN jsonb_build_object('success', false, 'error', 'ØªÙ… ØªÙˆØ²ÙŠØ¹ Ø£Ø±Ø¨Ø§Ø­ Ø§Ù„Ø´Ø­Ù†Ø© Ø§Ù„Ù…Ø±ØªØ¨Ø·Ø© Ø¨Ù‡Ø°Ø§ Ø§Ù„Ø£Ù…Ø± Ø¹Ù„Ù‰ Ø§Ù„Ù…Ø³Ø§Ù‡Ù…ÙŠÙ† - Ù„Ø§ ÙŠÙ…ÙƒÙ† ØªØ¹Ø¯ÙŠÙ„ Ø§Ù„Ø£Ø³Ø¹Ø§Ø± Ø£Ùˆ Ø§Ù„ØªÙƒØ§Ù„ÙŠÙ');
    END IF;

    v_company_id := v_order.company_id;
    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM public.sys_companies LIMIT 1;
    END IF;

    v_entry_date := (NOW() AT TIME ZONE 'Africa/Cairo')::DATE;

    -- 3. Auto-resolve Supplier UUID if not explicitly provided
    IF v_supplier_uuid IS NULL THEN
        IF p_item_type = 'material' AND p_batch_id > 0 THEN
            SELECT supplier_id INTO v_supplier_uuid
            FROM public.station_product_batches
            WHERE id = p_batch_id;

            IF v_supplier_uuid IS NULL THEN
                SELECT pi.supplier_id INTO v_supplier_uuid
                FROM public.station_product_batches spb
                JOIN public.purchase_invoices pi ON pi.id = spb.purchase_invoice_id
                WHERE spb.id = p_batch_id;
            END IF;
        END IF;

        -- Fallback to lot supplier linked to this packing order
        IF v_supplier_uuid IS NULL AND v_order.lot_id IS NOT NULL THEN
            SELECT supplier_id INTO v_supplier_uuid
            FROM public.lot_receipts
            WHERE id = v_order.lot_id;

            IF v_supplier_uuid IS NULL THEN
                SELECT supplier_id INTO v_supplier_uuid
                FROM public.lots
                WHERE id = v_order.lot_id;
            END IF;
        END IF;

        -- Fallback to system default supplier if only one exists
        IF v_supplier_uuid IS NULL THEN
            SELECT id INTO v_supplier_uuid FROM public.suppliers LIMIT 1;
        END IF;
    END IF;

    -- 4. Load Supplier details
    IF v_supplier_uuid IS NOT NULL THEN
        SELECT name, COALESCE(currency, 'EGP')
        INTO v_supplier_name, v_supplier_currency
        FROM public.suppliers
        WHERE id = v_supplier_uuid;

        v_exchange_rate := COALESCE(public.fn_get_exchange_rate(v_supplier_currency), 1.0);
    END IF;

    IF v_supplier_name IS NULL OR v_supplier_name = '' THEN
        v_supplier_name := 'Ø§Ù„Ù…ÙˆØ±Ø¯ Ø§Ù„Ù…Ø±ØªØ¨Ø·';
    END IF;

    -- 5. Identify Accounts
    -- Source: Supplier Payable Account (2001 / 2000 / 2112)
    BEGIN
        SELECT account_id INTO v_source_account_id
        FROM public.suppliers
        WHERE id = v_supplier_uuid;
    EXCEPTION WHEN OTHERS THEN
        v_source_account_id := NULL;
    END;

    IF v_source_account_id IS NULL THEN
        v_source_account_id := public.resolve_gl_account('2001', v_company_id);
    END IF;
    IF v_source_account_id IS NULL THEN
        v_source_account_id := public.resolve_gl_account('2000', v_company_id);
    END IF;
    IF v_source_account_id IS NULL THEN
        v_source_account_id := public.resolve_gl_account('2112', v_company_id);
    END IF;
    IF v_source_account_id IS NULL THEN
        SELECT id INTO v_source_account_id FROM public.accounts WHERE account_code IN ('2112', '2001', '2000') LIMIT 1;
    END IF;
    IF v_source_account_id IS NULL THEN
        SELECT id INTO v_source_account_id FROM public.accounts WHERE account_type = 'liability' LIMIT 1;
    END IF;

    -- Destination Account: COGS (3111/5000) if shipped, Packaging Inventory (12411/1040) or Crop Inventory (12412/1030) or Finished Goods (12413/1031) if not
    SELECT EXISTS (
        SELECT 1 FROM public.export_shipment_items WHERE packing_order_id = p_order_id
    ) INTO v_is_shipped;

    IF v_is_shipped THEN
        v_dest_account_id := public.resolve_gl_account('3111', v_company_id);
        IF v_dest_account_id IS NULL THEN
            v_dest_account_id := public.resolve_gl_account('5000', v_company_id);
        END IF;
        IF v_dest_account_id IS NULL THEN
            SELECT id INTO v_dest_account_id FROM public.accounts WHERE account_code IN ('3111', '5000', '5101', '3110') LIMIT 1;
        END IF;
        IF v_dest_account_id IS NULL THEN
            SELECT id INTO v_dest_account_id FROM public.accounts WHERE account_type IN ('cost_of_goods_sold', 'expense') LIMIT 1;
        END IF;
    ELSE
        IF p_item_type = 'material' THEN
            v_dest_account_id := public.resolve_gl_account('12411', v_company_id);
            IF v_dest_account_id IS NULL THEN
                v_dest_account_id := public.resolve_gl_account('1040', v_company_id);
            END IF;
        ELSE
            v_dest_account_id := public.resolve_gl_account('12412', v_company_id);
            IF v_dest_account_id IS NULL THEN
                v_dest_account_id := public.resolve_gl_account('1030', v_company_id);
            END IF;
        END IF;

        IF v_dest_account_id IS NULL THEN
            v_dest_account_id := public.resolve_gl_account('12413', v_company_id);
        END IF;
        IF v_dest_account_id IS NULL THEN
            v_dest_account_id := public.resolve_gl_account('1031', v_company_id);
        END IF;
        IF v_dest_account_id IS NULL THEN
            SELECT id INTO v_dest_account_id FROM public.accounts WHERE account_code IN ('12413', '1031', '12411', '1040', '12412', '1030') LIMIT 1;
        END IF;
        IF v_dest_account_id IS NULL THEN
            SELECT id INTO v_dest_account_id FROM public.accounts WHERE account_type = 'asset' LIMIT 1;
        END IF;
    END IF;

    IF v_source_account_id IS NULL OR v_dest_account_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'ØªØ¹Ø°Ø± ØªØ­Ø¯ÙŠØ¯ Ø­Ø³Ø§Ø¨Ø§Øª Ø§Ù„ÙŠÙˆÙ…ÙŠØ© (Ø­Ø³Ø§Ø¨ Ø§Ù„Ù…ÙˆØ±Ø¯ Ø£Ùˆ Ø­Ø³Ø§Ø¨ Ø§Ù„Ù…Ø®Ø²ÙˆÙ†/Ø§Ù„ØªÙƒÙ„ÙØ©)');
    END IF;

    -- 6. Resolve Cost Center & Item Details
    BEGIN
        v_notes := v_order.notes::jsonb;
    EXCEPTION WHEN OTHERS THEN
        v_notes := '{}'::jsonb;
    END;

    IF p_item_type = 'material' THEN
        v_category := 'Ù…ÙˆØ§Ø¯ Ø§Ù„ØªØ¹Ø¨Ø¦Ø©';
        v_cost_center_type := 'operational';
        
        IF v_notes ? 'materials' AND jsonb_typeof(v_notes->'materials') = 'array' THEN
            FOR v_elem IN SELECT * FROM jsonb_array_elements(v_notes->'materials')
            LOOP
                IF (p_batch_id > 0 AND (v_elem->>'batch_id')::bigint = p_batch_id) OR
                   (p_item_id IS NOT NULL AND (v_elem->>'id')::bigint = p_item_id) THEN
                    v_cost_center_id := NULLIF(v_elem->>'cost_center_id', '');
                    v_cost_center_name := NULLIF(v_elem->>'cost_center_name', '');
                    v_item_name := COALESCE(NULLIF(v_elem->>'item_name', ''), NULLIF(v_elem->>'name', ''), 'Ù…ÙˆØ§Ø¯ ØªØ¹Ø¨Ø¦Ø©');
                    EXIT;
                END IF;
            END LOOP;
        END IF;

        IF v_cost_center_id IS NULL THEN
            SELECT code, COALESCE(name_ar, name)
            INTO v_cost_center_id, v_cost_center_name
            FROM public.cost_centers
            WHERE code = 'CC-PACKING' OR code = 'packing_station'
            LIMIT 1;
        END IF;

        IF v_cost_center_id IS NULL THEN
            v_cost_center_id := 'CC-PACKING';
            v_cost_center_name := 'Ù…Ø­Ø·Ø© Ø§Ù„ØªØ¹Ø¨Ø¦Ø© ÙˆØ§Ù„ØªØ¬Ù‡ÙŠØ²';
        END IF;
    ELSIF p_item_type = 'crop' THEN
        v_category := 'ØªÙƒÙ„ÙØ© Ø§Ù„Ù…Ø­Ø§ØµÙŠÙ„';
        v_cost_center_type := 'variety';
        v_item_name := COALESCE(v_order.product_name, 'Ù…Ø­ØµÙˆÙ„');

        SELECT code, COALESCE(name_ar, name)
        INTO v_cost_center_id, v_cost_center_name
        FROM public.cost_centers
        WHERE (product_id = v_order.fruit_type_id OR name_ar = v_order.product_name OR crop_name = v_order.product_name)
          AND cost_center_type = 'variety'
        LIMIT 1;

        IF v_cost_center_id IS NULL THEN
            SELECT code, COALESCE(name_ar, name)
            INTO v_cost_center_id, v_cost_center_name
            FROM public.cost_centers
            WHERE cost_center_type = 'variety'
            LIMIT 1;
        END IF;

        IF v_cost_center_id IS NULL THEN
            v_cost_center_id := 'CC-CROP';
            v_cost_center_name := 'ØªÙƒÙ„ÙØ© Ø§Ù„Ù…Ø­Ø§ØµÙŠÙ„';
        END IF;
    END IF;

    -- 7. Generate Journal Entry
    v_foreign_discount := ROUND(p_discount_amount / GREATEST(v_exchange_rate, 0.0001), 2);

    INSERT INTO public.journal_entries (
        entry_number, entry_date, description, status,
        is_auto_generated, source_type, source_id, company_id,
        created_by, created_at, updated_at
    ) VALUES (
        'PENDING',
        v_entry_date,
        'Ø¥Ø´Ø¹Ø§Ø± Ø®ØµÙ… Ù…ÙˆØ±Ø¯ Ø¹Ù„Ù‰ Ø£Ù…Ø± ØªØ¹Ø¨Ø¦Ø© Ø±Ù‚Ù… ' || p_order_id::text || ' - Ù…ÙˆØ±Ø¯: ' || COALESCE(v_supplier_name, '') || ' - ' || COALESCE(p_reason, ''),
        'posted', true, 'packing_debit_note', p_order_id::text, v_company_id,
        COALESCE(p_user_id, auth.uid()), now(), now()
    ) RETURNING id INTO v_je_id;

    v_entry_num := public.fn_get_next_sequence(v_company_id, 'packing_debit_note', NULL, NULL);
    IF v_entry_num IS NULL OR v_entry_num = '' THEN
        v_entry_num := 'DN-' || LPAD(v_je_id::text, 5, '0');
    END IF;
    UPDATE public.journal_entries SET entry_number = v_entry_num WHERE id = v_je_id;

    -- DR: Supplier account (decreases payable)
    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id, cost_center_id
    ) VALUES (
        v_je_id, v_source_account_id, v_foreign_discount, 0, v_supplier_currency, p_discount_amount,
        'Ø¥Ø´Ø¹Ø§Ø± Ø®ØµÙ… Ù…Ù† Ø§Ù„Ù…ÙˆØ±Ø¯ ' || COALESCE(v_supplier_name, '') || ' Ù„Ø£Ù…Ø± ØªØ¹Ø¨Ø¦Ø© #' || p_order_id::text,
        v_company_id, v_cost_center_id
    );

    -- CR: Inventory or COGS (reduces cost)
    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description, company_id, cost_center_id
    ) VALUES (
        v_je_id, v_dest_account_id, 0, p_discount_amount, 'EGP', p_discount_amount,
        'ØªØ®ÙÙŠØ¶ ØªÙƒÙ„ÙØ© Ø§Ù„Ø¥Ù†ØªØ§Ø¬ Ù„Ø£Ù…Ø± ØªØ¹Ø¨Ø¦Ø© #' || p_order_id::text || ' Ø¨Ø¥Ø´Ø¹Ø§Ø± Ø®ØµÙ… Ù…ÙˆØ±Ø¯ ' || COALESCE(v_supplier_name, ''),
        v_company_id, v_cost_center_id
    );

    -- 7. Update Supplier Subledger & Account Statement (ledger_entries and supplier balance)
    IF v_supplier_uuid IS NOT NULL THEN
        UPDATE public.suppliers
        SET outstanding_balance = GREATEST(0, COALESCE(outstanding_balance, 0) - p_discount_amount),
            current_balances_by_currency = jsonb_set(
                COALESCE(current_balances_by_currency, '{}'::jsonb),
                array[v_supplier_currency],
                to_jsonb(COALESCE((current_balances_by_currency->>v_supplier_currency)::numeric, 0) - v_foreign_discount)
            ),
            updated_at = now()
        WHERE id = v_supplier_uuid;

        INSERT INTO public.ledger_entries (
            entity_type,
            entity_id,
            entry_type,
            amount,
            currency,
            reference_type,
            reference_id,
            reference_text,
            description,
            created_by,
            created_at
        ) VALUES (
            'supplier',
            v_supplier_uuid::text,
            'debit',
            v_foreign_discount,
            v_supplier_currency,
            'packing_order_debit_note',
            p_order_id,
            v_entry_num,
            'Ø¥Ø´Ø¹Ø§Ø± Ø®ØµÙ… ÙˆØªØ³ÙˆÙŠØ© Ø£Ù…Ø± ØªØ¹Ø¨Ø¦Ø© #' || p_order_id::text || ' - Ù…ÙˆØ±Ø¯: ' || COALESCE(v_supplier_name, '') || ' (' || COALESCE(p_reason, '') || ')',
            COALESCE(p_user_id, auth.uid()),
            now()
        );
    END IF;

    -- 8. Sync into Cost Center Transactions (Reduces Cost Center Expenses)
    IF v_cost_center_id IS NOT NULL THEN
        INSERT INTO public.cost_center_transactions (
            cost_center_id,
            cost_center_name,
            cost_center_type,
            source_type,
            source_id,
            transaction_date,
            supplier_id,
            supplier_name,
            item_name,
            category,
            quantity,
            unit_price,
            currency,
            exchange_rate,
            total_in_currency,
            amount,
            notes,
            is_confirmed
        ) VALUES (
            v_cost_center_id,
            v_cost_center_name,
            v_cost_center_type,
            'packing_debit_note',
            'pkdn_' || p_order_id::text || '_' || v_je_id::text,
            v_entry_date,
            v_supplier_uuid::text,
            v_supplier_name,
            'Ø¥Ø´Ø¹Ø§Ø± Ø®ØµÙ… ØªØ³ÙˆÙŠØ© - ' || v_item_name,
            v_category,
            0,
            0,
            v_supplier_currency,
            v_exchange_rate,
            -v_foreign_discount,
            -p_discount_amount,
            'Ø¥Ø´Ø¹Ø§Ø± Ø®ØµÙ… ÙˆØªØ³ÙˆÙŠØ© Ø£Ù…Ø± ØªØ¹Ø¨Ø¦Ø© #' || p_order_id::text || ' - Ù…ÙˆØ±Ø¯: ' || COALESCE(v_supplier_name, '') || ' (' || COALESCE(p_reason, '') || ')',
            true
        ) ON CONFLICT (source_type, source_id) DO UPDATE SET
            cost_center_id = EXCLUDED.cost_center_id,
            cost_center_name = EXCLUDED.cost_center_name,
            cost_center_type = EXCLUDED.cost_center_type,
            supplier_id = EXCLUDED.supplier_id,
            supplier_name = EXCLUDED.supplier_name,
            item_name = EXCLUDED.item_name,
            category = EXCLUDED.category,
            currency = EXCLUDED.currency,
            exchange_rate = EXCLUDED.exchange_rate,
            total_in_currency = EXCLUDED.total_in_currency,
            amount = EXCLUDED.amount,
            notes = EXCLUDED.notes,
            updated_at = now();
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'ØªÙ… ØªØ·Ø¨ÙŠÙ‚ Ø¥Ø´Ø¹Ø§Ø± Ø§Ù„Ø®ØµÙ… Ø¨Ù†Ø¬Ø§Ø­ ÙˆØªØ­Ø¯ÙŠØ« Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª ÙˆØ§Ù„Ù…Ø±Ø§ÙƒØ² ÙˆØ§Ù„ØªÙƒØ§Ù„ÙŠÙ',
        'journal_entry_id', v_je_id,
        'entry_number', v_entry_num,
        'foreign_discount', v_foreign_discount,
        'base_discount', p_discount_amount
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_apply_packing_order_item_debit_note(BIGINT, TEXT, BIGINT, BIGINT, NUMERIC, TEXT, UUID, UUID) TO authenticated, service_role, anon;

-- ============================================================================
-- 10. ØªØ­Ø¯ÙŠØ« Ø¬Ø°Ø± Ø­Ø³Ø§Ø¨Ø§Øª Ø§Ù„Ù…ÙˆØ±Ø¯ÙŠÙ† Ù„ÙŠØªØ·Ø§Ø¨Ù‚ Ø¯Ø§Ø¦Ù…Ø§ Ù…Ø¹ ÙƒØ´Ù Ø§Ù„Ø­Ø³Ø§Ø¨
-- ============================================================================
ALTER TABLE public.purchase_invoices ADD COLUMN IF NOT EXISTS exchange_rate NUMERIC(15, 6) DEFAULT 1.0;
ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS is_multi_currency BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE public.suppliers ADD COLUMN IF NOT EXISTS initial_balances_by_currency JSONB DEFAULT '{}'::jsonb;

CREATE OR REPLACE FUNCTION public.get_supplier_true_balances()
RETURNS TABLE (
  supplier_id uuid,
  true_balance numeric
)
LANGUAGE sql
SECURITY DEFINER
AS $func$
  SELECT
    s.id,
    (
      -- 1. Initial Balance (EGP equivalent for multi-currency, or native for single)
      (CASE 
        WHEN s.is_multi_currency = true AND s.initial_balances_by_currency IS NOT NULL AND jsonb_typeof(s.initial_balances_by_currency) = 'object' THEN 
          (SELECT COALESCE(SUM((val->>'amount')::numeric * COALESCE((val->>'exchange_rate')::numeric, 1.0) * (CASE WHEN UPPER(COALESCE(val->>'direction', 'CREDIT')) = 'DEBIT' THEN -1 ELSE 1 END)), 0) 
           FROM jsonb_each(s.initial_balances_by_currency) elem(k, val))
        WHEN s.initial_balance_direction = 'CREDIT' THEN COALESCE(s.initial_balance, 0) 
        ELSE -COALESCE(s.initial_balance, 0) 
      END)
      
      -- 2. Purchases (converted to base EGP using exchange_rate)
      + COALESCE((SELECT SUM(COALESCE(total_amount * COALESCE(exchange_rate, 1.0), total_amount)) FROM purchase_invoices WHERE supplier_id = s.id AND status = 'confirmed'), 0)
      
      -- 3. Treasury Transactions
      + COALESCE((SELECT SUM(amount) FROM treasury_transactions WHERE supplier_id = s.id AND type IN ('deposit', 'receive', 'income', 'supplier_refund') AND (status = 'confirmed' OR status IS NULL)), 0)
      - COALESCE((SELECT SUM(amount) FROM treasury_transactions WHERE supplier_id = s.id AND type IN ('expense', 'supplier_payment') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 4. Bank Transactions
      + COALESCE((SELECT SUM(amount) FROM bank_account_transactions WHERE entity_type = 'supplier' AND entity_id = s.id::TEXT AND type IN ('deposit', 'receive', 'income', 'supplier_refund') AND (status = 'confirmed' OR status IS NULL)), 0)
      - COALESCE((SELECT SUM(amount) FROM bank_account_transactions WHERE entity_type = 'supplier' AND entity_id = s.id::TEXT AND type IN ('withdraw', 'expense', 'supplier_payment') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 5. Cheques
      + COALESCE((SELECT SUM(amount) FROM cheques WHERE supplier_id = s.id AND type = 'incoming' AND status IN ('cleared', 'collected')), 0)
      - COALESCE((SELECT SUM(amount) FROM cheques WHERE supplier_id = s.id AND type = 'outgoing' AND status IN ('cleared', 'collected')), 0)
      
      -- 6. Legacy Ledger Entries (Manual journal entries, packing costs, old lot receipts, etc.)
      -- We EXCLUDE entries that are already represented by treasury_transactions or bank_transactions above 
      + COALESCE((
          SELECT SUM(CASE WHEN entry_type = 'credit' THEN amount ELSE -amount END)
          FROM ledger_entries le
          WHERE le.entity_type = 'supplier' 
            AND le.entity_id IN (s.id::text, s.code)
            AND NOT (
                le.reference_type IN ('supplier_payment', 'treasury_deposit', 'treasury_withdrawal', 'treasury_transaction', 'cash_payment', 'receive', 'deposit', 'supplier_refund')
                AND EXISTS (SELECT 1 FROM treasury_transactions tt WHERE tt.id::TEXT = le.reference_id::TEXT)
            )
            AND NOT (
                le.reference_type IN ('bank_payment', 'bank_receipt', 'bank_transaction', 'cheque', 'supplier_payment', 'cheque_payment', 'receive', 'deposit', 'supplier_refund')
                AND EXISTS (SELECT 1 FROM bank_account_transactions bt WHERE bt.id::TEXT = le.reference_id::TEXT)
            )
            AND le.reference_type NOT IN ('lot_receipt', 'lot_adjustment', 'lot_price_adjustment', 'lot_return')
      ), 0)

      -- 7. New Enterprise Account Ledger Entries (New lot receipts, adjustments)
      -- Include source types that were migrated to enterprise journals and are no longer in legacy ledger_entries
      + COALESCE((
          SELECT SUM(ale.credit - ale.debit)
          FROM account_ledger_entries ale
          JOIN journal_entries je ON je.id = ale.journal_entry_id
          WHERE ale.account_id = s.account_id
            AND je.source_type IN (
              'lot_receipt', 'lot_adjustment', 'lot_price_adjustment', 'lot_return', 'manual'
            )
      ), 0)
    ) AS true_balance
  FROM suppliers s;
$func$;

GRANT EXECUTE ON FUNCTION public.get_supplier_true_balances() TO authenticated, anon, service_role;

CREATE OR REPLACE FUNCTION public.get_customer_true_balances()
RETURNS TABLE (
  customer_id bigint,
  true_balance numeric
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $func$
  SELECT
    c.id,
    (
      -- 1. Initial Balance (DEBIT is positive debt / customer owes us, CREDIT is negative / overpayment)
      (CASE 
        WHEN UPPER(COALESCE(c.initial_balance_direction, 'DEBIT')) = 'CREDIT' THEN -COALESCE(c.initial_balance, 0) 
        ELSE COALESCE(c.initial_balance, 0) 
      END)
      
      -- 2. Export Shipments (Debits - customer owes us)
      + COALESCE((
          SELECT SUM(
            CASE 
              WHEN UPPER(COALESCE(c.currency, 'EGP')) = 'EGP' THEN COALESCE(es.total_revenue_egp, 0)
              ELSE COALESCE(es.total_revenue_foreign, es.total_revenue_egp, 0)
            END 
            - COALESCE(es.discount_amount, 0)
          )
          FROM public.export_shipments es
          WHERE es.customer_id = c.id
            AND es.is_confirmed = true
            AND (es.status IS NULL OR es.status <> 'cancelled')
        ), 0)

      -- 3. Local Invoices (Debits - customer owes us)
      + COALESCE((
          SELECT SUM(COALESCE(inv.total_amount, 0))
          FROM public.invoices inv
          WHERE inv.customer_id = c.id
            AND inv.status IN ('confirmed', 'paid')
        ), 0)

      -- 4. Treasury Transactions (Receiving money from customer is Credit / reduces debt; refund is Debit)
      - COALESCE((SELECT SUM(amount) FROM public.treasury_transactions WHERE customer_id = c.id AND type IN ('deposit', 'receive', 'income') AND (status = 'confirmed' OR status IS NULL)), 0)
      + COALESCE((SELECT SUM(amount) FROM public.treasury_transactions WHERE customer_id = c.id AND type IN ('expense', 'withdrawal', 'customer_refund') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 5. Bank Transactions (Deposit from customer is Credit; withdrawal/refund is Debit)
      - COALESCE((SELECT SUM(amount) FROM public.bank_account_transactions WHERE entity_type = 'customer' AND entity_id = c.id::TEXT AND type IN ('deposit', 'receive', 'income') AND (status = 'confirmed' OR status IS NULL)), 0)
      + COALESCE((SELECT SUM(amount) FROM public.bank_account_transactions WHERE entity_type = 'customer' AND entity_id = c.id::TEXT AND type IN ('withdraw', 'withdrawal', 'expense') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 6. Cheques (Incoming cheques from customer are Credit / reduces debt; outgoing refund cheques are Debit)
      - COALESCE((SELECT SUM(amount) FROM public.cheques WHERE (counterparty_type = 'customer' AND counterparty_id = c.id) AND type = 'incoming' AND status IN ('cleared', 'collected', 'pending')), 0)
      + COALESCE((SELECT SUM(amount) FROM public.cheques WHERE (counterparty_type = 'customer' AND counterparty_id = c.id) AND type = 'outgoing' AND status IN ('cleared', 'collected', 'pending')), 0)

      -- 7. Direct / Manual Journal Entries specifically for this customer
      -- MUST EXCLUDE 'opening_balance' because initial_balance is already included in step 1!
      -- Also excludes automated entries for shipments, invoices, treasury, bank, and cheques.
      + COALESCE((
          SELECT SUM(ale.debit - ale.credit)
          FROM public.account_ledger_entries ale
          JOIN public.journal_entries je ON je.id = ale.journal_entry_id
          WHERE ale.account_id = c.account_id
            AND (je.source_id = 'customers_' || c.id::text OR je.source_id = c.id::text)
            AND je.source_type NOT IN (
                'opening_balance',
                'customer_opening_balance',
                'export_shipment',
                'invoice',
                'sales_invoice',
                'treasury_transaction',
                'treasury_deposit',
                'treasury_receive',
                'treasury_expense',
                'bank_transaction',
                'bank_deposit',
                'bank_withdrawal',
                'cheque_receipt',
                'cheque_issuance',
                'cheque_deposit',
                'cheque_clearance'
            )
        ), 0)
    ) AS true_balance
  FROM public.customers c;
$func$;

GRANT EXECUTE ON FUNCTION public.get_customer_true_balances() TO authenticated, anon, service_role;

