CREATE OR REPLACE FUNCTION public.get_shipping_company_true_balances()
RETURNS TABLE (
  shipping_company_id bigint,
  true_balance numeric
)
LANGUAGE sql
SECURITY DEFINER
AS $func$
  SELECT
    sc.id,
    (
      -- 1. Initial Balance
      (CASE WHEN sc.initial_balance_direction = 'CREDIT' THEN COALESCE(sc.initial_balance, 0) ELSE -COALESCE(sc.initial_balance, 0) END)
      
      -- 2. Shipment Cost Items (ØªÙƒØ§Ù„ÙŠÙ Ø§Ù„Ø´Ø­Ù†)
      + COALESCE((
          SELECT SUM(sci.total_price / COALESCE(NULLIF(sci.exchange_rate, 0), 1.0))
          FROM public.shipment_cost_items sci
          WHERE (
            (sci.shipping_company_id IS NOT NULL AND sci.shipping_company_id = sc.id)
            OR
            (sci.vendor_type = 'shipping_company' AND sci.vendor_id = sc.id)
          )
        ), 0)
      
      -- 3. Treasury Transactions
      + COALESCE((SELECT SUM(amount) FROM public.treasury_transactions WHERE shipping_company_id = sc.id AND type IN ('deposit', 'receive', 'income') AND (status = 'confirmed' OR status IS NULL)), 0)
      - COALESCE((SELECT SUM(amount) FROM public.treasury_transactions WHERE shipping_company_id = sc.id AND type IN ('expense', 'shipping_company_payment', 'payment') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 4. Bank Transactions
      + COALESCE((SELECT SUM(amount) FROM public.bank_account_transactions WHERE entity_type = 'shipping_company' AND entity_id = sc.id::TEXT AND type IN ('deposit', 'receive', 'income') AND (status = 'confirmed' OR status IS NULL)), 0)
      - COALESCE((SELECT SUM(amount) FROM public.bank_account_transactions WHERE entity_type = 'shipping_company' AND entity_id = sc.id::TEXT AND type IN ('withdraw', 'withdrawal', 'expense', 'shipping_company_payment', 'payment') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 5. Cheques
      + COALESCE((SELECT SUM(amount) FROM public.cheques WHERE (shipping_company_id = sc.id OR (counterparty_type = 'shipping_company' AND counterparty_id = sc.id)) AND type = 'incoming' AND status IN ('cleared', 'collected')), 0)
      - COALESCE((SELECT SUM(amount) FROM public.cheques WHERE (shipping_company_id = sc.id OR (counterparty_type = 'shipping_company' AND counterparty_id = sc.id)) AND type = 'outgoing' AND status IN ('cleared', 'collected')), 0)

      -- 6. Direct Ledger Entries (excluding ones created for treasury/bank transactions already counted)
      + COALESCE((
          SELECT SUM(CASE WHEN entry_type = 'credit' THEN amount ELSE -amount END)
          FROM public.ledger_entries le
          WHERE le.entity_type = 'shipping_company' 
            AND le.entity_id = sc.id::text
            AND le.reference_type NOT IN ('shipment_cost_item', 'expense', 'receive')
            AND NOT (
                le.reference_type IN ('shipping_company_payment', 'treasury_deposit', 'treasury_withdrawal', 'treasury_transaction', 'cash_payment', 'receive', 'deposit')
                AND EXISTS (SELECT 1 FROM public.treasury_transactions tt WHERE tt.id::TEXT = le.reference_id::TEXT)
            )
            AND NOT (
                le.reference_type IN ('bank_payment', 'bank_receipt', 'bank_transaction', 'cheque', 'shipping_company_payment', 'receive', 'deposit')
                AND EXISTS (SELECT 1 FROM public.bank_account_transactions bt WHERE bt.id::TEXT = le.reference_id::TEXT)
            )
      ), 0)
    ) AS true_balance
  FROM public.shipping_companies sc;
$func$;

GRANT EXECUTE ON FUNCTION public.get_shipping_company_true_balances() TO authenticated, anon, service_role;

CREATE OR REPLACE FUNCTION public.get_clearing_agent_true_balances()
RETURNS TABLE (
  clearing_agent_id bigint,
  true_balance numeric
)
LANGUAGE sql
SECURITY DEFINER
AS $func$
  SELECT
    ca.id,
    (
      -- 1. Initial Balance
      (CASE WHEN ca.initial_balance_direction = 'CREDIT' THEN COALESCE(ca.initial_balance, 0) ELSE -COALESCE(ca.initial_balance, 0) END)
      
      -- 2. Shipment Cost Items (ØªÙƒØ§Ù„ÙŠÙ Ø§Ù„ØªØ®Ù„ÙŠØµ)
      + COALESCE((
          SELECT SUM(sci.total_price / COALESCE(NULLIF(sci.exchange_rate, 0), 1.0))
          FROM public.shipment_cost_items sci
          WHERE (
            (sci.clearing_agent_id IS NOT NULL AND sci.clearing_agent_id = ca.id)
            OR
            (sci.vendor_type = 'clearing_agent' AND sci.vendor_id = ca.id)
          )
        ), 0)
      
      -- 3. Treasury Transactions
      + COALESCE((SELECT SUM(amount) FROM public.treasury_transactions WHERE clearing_agent_id = ca.id AND type IN ('deposit', 'receive', 'income') AND (status = 'confirmed' OR status IS NULL)), 0)
      - COALESCE((SELECT SUM(amount) FROM public.treasury_transactions WHERE clearing_agent_id = ca.id AND type IN ('expense', 'clearing_agent_payment', 'payment') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 4. Bank Transactions
      + COALESCE((SELECT SUM(amount) FROM public.bank_account_transactions WHERE entity_type = 'clearing_agent' AND entity_id = ca.id::TEXT AND type IN ('deposit', 'receive', 'income') AND (status = 'confirmed' OR status IS NULL)), 0)
      - COALESCE((SELECT SUM(amount) FROM public.bank_account_transactions WHERE entity_type = 'clearing_agent' AND entity_id = ca.id::TEXT AND type IN ('withdraw', 'withdrawal', 'expense', 'clearing_agent_payment', 'payment') AND (status = 'confirmed' OR status IS NULL)), 0)
      
      -- 5. Cheques
      + COALESCE((SELECT SUM(amount) FROM public.cheques WHERE (clearing_agent_id = ca.id OR (counterparty_type = 'clearing_agent' AND counterparty_id = ca.id)) AND type = 'incoming' AND status IN ('cleared', 'collected')), 0)
      - COALESCE((SELECT SUM(amount) FROM public.cheques WHERE (clearing_agent_id = ca.id OR (counterparty_type = 'clearing_agent' AND counterparty_id = ca.id)) AND type = 'outgoing' AND status IN ('cleared', 'collected')), 0)

      -- 6. Direct Ledger Entries (excluding ones created for treasury/bank transactions already counted)
      + COALESCE((
          SELECT SUM(CASE WHEN entry_type = 'credit' THEN amount ELSE -amount END)
          FROM public.ledger_entries le
          WHERE le.entity_type = 'clearing_agent' 
            AND le.entity_id = ca.id::text
            AND le.reference_type NOT IN ('shipment_cost_item', 'expense', 'receive')
            AND NOT (
                le.reference_type IN ('clearing_agent_payment', 'treasury_deposit', 'treasury_withdrawal', 'treasury_transaction', 'cash_payment', 'receive', 'deposit')
                AND EXISTS (SELECT 1 FROM public.treasury_transactions tt WHERE tt.id::TEXT = le.reference_id::TEXT)
            )
            AND NOT (
                le.reference_type IN ('bank_payment', 'bank_receipt', 'bank_transaction', 'cheque', 'clearing_agent_payment', 'receive', 'deposit')
                AND EXISTS (SELECT 1 FROM public.bank_account_transactions bt WHERE bt.id::TEXT = le.reference_id::TEXT)
            )
      ), 0)
    ) AS true_balance
  FROM public.clearing_agents ca;
$func$;

GRANT EXECUTE ON FUNCTION public.get_clearing_agent_true_balances() TO authenticated, anon, service_role;

-- ============================================================================
-- 10.5 View: v_journal_entry_lines (Ø¹Ø±Ø¶ Ø£Ø³Ø·Ø± Ø§Ù„Ù‚ÙŠÙˆØ¯ Ø§Ù„ÙŠÙˆÙ…ÙŠØ©)
-- ============================================================================
DROP VIEW IF EXISTS public.v_journal_entry_lines CASCADE;

CREATE OR REPLACE VIEW public.v_journal_entry_lines AS
SELECT
    ale.id,
    ale.journal_entry_id,
    je.id AS entry_id,
    je.entry_number,
    je.entry_date AS transaction_date,
    ale.account_id,
    COALESCE(NULLIF(a.account_code, ''), NULLIF(a.code, ''), '') AS account_code,
    COALESCE(NULLIF(a.account_name, ''), NULLIF(a.name, ''), '') AS account_name,
    CASE WHEN ale.debit > 0 THEN 'debit' ELSE 'credit' END AS type,
    (CASE WHEN ale.debit > 0 THEN ale.debit ELSE ale.credit END) AS amount,
    ale.description,
    je.created_by,
    je.created_at,
    je.company_id,
    ale.debit,
    ale.credit,
    ale.currency,
    ale.amount_in_base_currency,
    je.source_type,
    je.source_id,
    je.status,
    ale.cost_center_id,
    COALESCE(cc.name_ar, cc.name, cc.code, ale.cost_center_id, '') AS cost_center_name,
    COALESCE(cc.code, ale.cost_center_id, '') AS cost_center_code,
    ale.entity_type,
    ale.entity_id,
    ale.branch_id,
    st.name AS branch_name,
    st.code AS branch_code
FROM public.account_ledger_entries ale
JOIN public.journal_entries je ON je.id = ale.journal_entry_id
LEFT JOIN public.accounts a ON a.id = ale.account_id
LEFT JOIN public.stations st ON st.id = ale.branch_id
LEFT JOIN public.cost_centers cc ON (
    cc.code = ale.cost_center_id 
    OR cc.code = 'CC-' || UPPER(ale.cost_center_id)
    OR (ale.cost_center_id = 'general_admin' AND cc.code = 'CC-ADMIN')
    OR (ale.cost_center_id = 'packing_station' AND cc.code = 'CC-PACKING')
    OR (ale.cost_center_id = 'freight_logistics' AND cc.code = 'CC-LOGISTICS')
    OR (ale.cost_center_id = 'customs_clearance' AND cc.code = 'CC-CUSTOMS')
    OR cc.id::TEXT = ale.cost_center_id
)
WHERE je.deleted_at IS NULL
  AND ale.deleted_at IS NULL;

GRANT SELECT ON public.v_journal_entry_lines TO authenticated, service_role, anon;

CREATE OR REPLACE VIEW public.journal_entry_lines AS
SELECT * FROM public.v_journal_entry_lines;

GRANT SELECT ON public.journal_entry_lines TO authenticated, service_role, anon;

-- RPC: Build and Post Cash Receipt Journal Entry
CREATE OR REPLACE FUNCTION public.rpc_build_cash_receipt_journal(payload jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_date date;
    v_amount numeric;
    v_mode text;
    v_customer_id bigint;
    v_supplier_id bigint;
    v_desc text;
    v_idempotency_key text;
    v_journal_id bigint;
    v_entry_number text;
    v_cash_account_id bigint;
    v_credit_account_id bigint;
BEGIN
    v_date := COALESCE((payload->>'date')::date, CURRENT_DATE);
    v_amount := (payload->>'amount')::numeric;
    v_mode := COALESCE(payload->>'mode', 'customer');
    v_customer_id := (payload->>'customer_id')::bigint;
    v_supplier_id := (payload->>'supplier_id')::bigint;
    v_desc := COALESCE(payload->>'description', 'Ø³Ù†Ø¯ Ù‚Ø¨Ø¶ Ù†Ù‚Ø¯ÙŠ');
    v_idempotency_key := payload->>'idempotency_key';

    IF v_amount IS NULL OR v_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Ø§Ù„Ù…Ø¨Ù„Øº ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† Ø£ÙƒØ¨Ø± Ù…Ù† ØµÙØ±');
    END IF;

    IF v_idempotency_key IS NOT NULL THEN
        SELECT id, entry_number INTO v_journal_id, v_entry_number
        FROM public.journal_entries
        WHERE idempotency_key = v_idempotency_key
        LIMIT 1;

        IF FOUND THEN
            RETURN jsonb_build_object('success', true, 'journal_id', v_journal_id, 'journal_number', v_entry_number);
        END IF;
    END IF;

    SELECT id INTO v_cash_account_id
    FROM public.accounts
    WHERE (code = '12111' OR account_code = '12111' OR account_code = '12211' OR name LIKE '%ØµÙ†Ø¯ÙˆÙ‚%' OR name LIKE '%Ø®Ø²ÙŠÙ†Ø©%')
      AND is_active = true
    ORDER BY id ASC LIMIT 1;

    IF v_cash_account_id IS NULL THEN
        SELECT id INTO v_cash_account_id FROM public.accounts WHERE is_active = true LIMIT 1;
    END IF;

    IF v_mode = 'customer' AND v_customer_id IS NOT NULL THEN
        SELECT account_id INTO v_credit_account_id FROM public.customers WHERE id = v_customer_id;
    ELSIF v_mode = 'supplier' AND v_supplier_id IS NOT NULL THEN
        SELECT account_id INTO v_credit_account_id FROM public.suppliers WHERE id = v_supplier_id;
    END IF;

    IF v_credit_account_id IS NULL THEN
        SELECT id INTO v_credit_account_id FROM public.accounts WHERE (code = '12511' OR account_code = '12511') LIMIT 1;
    END IF;

    v_entry_number := 'CR-' || to_char(now(), 'YYYYMMDD') || '-' || lpad((nextval('public.journal_entries_id_seq'::regclass) % 10000)::text, 4, '0');

    INSERT INTO public.journal_entries (
        entry_number, entry_date, description, status, source_type, source_id, idempotency_key
    ) VALUES (
        v_entry_number, v_date, v_desc, 'posted', 'cash_receipt', 
        CASE WHEN v_customer_id IS NOT NULL THEN 'customers_' || v_customer_id::text ELSE NULL END,
        v_idempotency_key
    ) RETURNING id INTO v_journal_id;

    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description
    ) VALUES (
        v_journal_id, v_cash_account_id, v_amount, 0, 'EGP', v_amount, v_desc
    );

    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description,
        entity_type, entity_id
    ) VALUES (
        v_journal_id, v_credit_account_id, 0, v_amount, 'EGP', v_amount, v_desc,
        CASE WHEN v_customer_id IS NOT NULL THEN 'customer' WHEN v_supplier_id IS NOT NULL THEN 'supplier' ELSE NULL END,
        CASE WHEN v_customer_id IS NOT NULL THEN v_customer_id::text WHEN v_supplier_id IS NOT NULL THEN v_supplier_id::text ELSE NULL END
    );

    RETURN jsonb_build_object(
        'success', true,
        'journal_id', v_journal_id,
        'journal_number', v_entry_number
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_build_cash_receipt_journal(jsonb) TO authenticated, service_role, anon;

-- RPC: Build and Post Cash Payment Journal Entry
CREATE OR REPLACE FUNCTION public.rpc_build_cash_payment_journal(payload jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_date date;
    v_amount numeric;
    v_mode text;
    v_customer_id bigint;
    v_supplier_id bigint;
    v_desc text;
    v_idempotency_key text;
    v_journal_id bigint;
    v_entry_number text;
    v_cash_account_id bigint;
    v_debit_account_id bigint;
BEGIN
    v_date := COALESCE((payload->>'date')::date, CURRENT_DATE);
    v_amount := (payload->>'amount')::numeric;
    v_mode := COALESCE(payload->>'mode', 'supplier');
    v_customer_id := (payload->>'customer_id')::bigint;
    v_supplier_id := (payload->>'supplier_id')::bigint;
    v_desc := COALESCE(payload->>'description', 'Ø³Ù†Ø¯ ØµØ±Ù Ù†Ù‚Ø¯ÙŠ');
    v_idempotency_key := payload->>'idempotency_key';

    IF v_amount IS NULL OR v_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Ø§Ù„Ù…Ø¨Ù„Øº ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† Ø£ÙƒØ¨Ø± Ù…Ù† ØµÙØ±');
    END IF;

    IF v_idempotency_key IS NOT NULL THEN
        SELECT id, entry_number INTO v_journal_id, v_entry_number
        FROM public.journal_entries
        WHERE idempotency_key = v_idempotency_key
        LIMIT 1;

        IF FOUND THEN
            RETURN jsonb_build_object('success', true, 'journal_id', v_journal_id, 'journal_number', v_entry_number);
        END IF;
    END IF;

    SELECT id INTO v_cash_account_id
    FROM public.accounts
    WHERE (code = '12111' OR account_code = '12111' OR account_code = '12211' OR name LIKE '%ØµÙ†Ø¯ÙˆÙ‚%' OR name LIKE '%Ø®Ø²ÙŠÙ†Ø©%')
      AND is_active = true
    ORDER BY id ASC LIMIT 1;

    IF v_cash_account_id IS NULL THEN
        SELECT id INTO v_cash_account_id FROM public.accounts WHERE is_active = true LIMIT 1;
    END IF;

    IF v_mode = 'customer' AND v_customer_id IS NOT NULL THEN
        SELECT account_id INTO v_debit_account_id FROM public.customers WHERE id = v_customer_id;
    ELSIF v_mode = 'supplier' AND v_supplier_id IS NOT NULL THEN
        SELECT account_id INTO v_debit_account_id FROM public.suppliers WHERE id = v_supplier_id;
    END IF;

    IF v_debit_account_id IS NULL THEN
        IF v_mode = 'customer' THEN
            SELECT id INTO v_debit_account_id FROM public.accounts WHERE (code = '12511' OR account_code = '12511') LIMIT 1;
        ELSE
            SELECT id INTO v_debit_account_id FROM public.accounts WHERE (code = '21111' OR account_code = '21111') LIMIT 1;
        END IF;
    END IF;

    v_entry_number := 'CP-' || to_char(now(), 'YYYYMMDD') || '-' || lpad((nextval('public.journal_entries_id_seq'::regclass) % 10000)::text, 4, '0');

    INSERT INTO public.journal_entries (
        entry_number, entry_date, description, status, source_type, source_id, idempotency_key
    ) VALUES (
        v_entry_number, v_date, v_desc, 'posted', 'cash_payment',
        CASE WHEN v_customer_id IS NOT NULL THEN 'customers_' || v_customer_id::text WHEN v_supplier_id IS NOT NULL THEN 'suppliers_' || v_supplier_id::text ELSE NULL END,
        v_idempotency_key
    ) RETURNING id INTO v_journal_id;

    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description,
        entity_type, entity_id
    ) VALUES (
        v_journal_id, v_debit_account_id, v_amount, 0, 'EGP', v_amount, v_desc,
        CASE WHEN v_customer_id IS NOT NULL THEN 'customer' WHEN v_supplier_id IS NOT NULL THEN 'supplier' ELSE NULL END,
        CASE WHEN v_customer_id IS NOT NULL THEN v_customer_id::text WHEN v_supplier_id IS NOT NULL THEN v_supplier_id::text ELSE NULL END
    );

    INSERT INTO public.account_ledger_entries (
        journal_entry_id, account_id, debit, credit, currency, amount_in_base_currency, description
    ) VALUES (
        v_journal_id, v_cash_account_id, 0, v_amount, 'EGP', v_amount, v_desc
    );

    RETURN jsonb_build_object(
        'success', true,
        'journal_id', v_journal_id,
        'journal_number', v_entry_number
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_build_cash_payment_journal(jsonb) TO authenticated, service_role, anon;

-- ============================================================================
-- 11. ØªØ±ØªÙŠØ¨ Ø¯ÙØªØ± Ù‚ÙŠÙˆØ¯ Ø§Ù„ÙŠÙˆÙ…ÙŠØ© Ø­Ø³Ø¨ Ø§Ù„Ø£Ø­Ø¯Ø« Ø¥Ø¶Ø§ÙØ© (created_at DESC)
-- ============================================================================
CREATE OR REPLACE FUNCTION rpc_get_journal_history(
    p_search text DEFAULT NULL,
    p_from_date date DEFAULT NULL,
    p_to_date date DEFAULT NULL,
    p_limit int DEFAULT 300
)
RETURNS SETOF v_journal_entry_lines AS $$
BEGIN
  IF p_search IS NULL OR p_search = '' THEN
    RETURN QUERY
    WITH latest AS (
      SELECT id 
      FROM journal_entries 
      WHERE deleted_at IS NULL
        AND (p_from_date IS NULL OR entry_date >= p_from_date)
        AND (p_to_date IS NULL OR entry_date <= p_to_date)
      ORDER BY created_at DESC, id DESC 
      LIMIT p_limit
    )
    SELECT v.*
    FROM v_journal_entry_lines v
    JOIN latest l ON l.id = v.entry_id
    ORDER BY v.created_at DESC, v.entry_id DESC, v.id ASC;
  ELSE
    RETURN QUERY
    WITH matched_entries AS (
      SELECT entry_id
      FROM v_journal_entry_lines
      WHERE (p_from_date IS NULL OR transaction_date >= p_from_date)
        AND (p_to_date IS NULL OR transaction_date <= p_to_date)
        AND (
          entry_number ILIKE '%' || p_search || '%'
          OR account_name ILIKE '%' || p_search || '%'
          OR account_code ILIKE '%' || p_search || '%'
          OR description ILIKE '%' || p_search || '%'
        )
      GROUP BY entry_id
      ORDER BY MAX(created_at) DESC, entry_id DESC
      LIMIT p_limit
    )
    SELECT v.*
    FROM v_journal_entry_lines v
    JOIN matched_entries m ON m.entry_id = v.entry_id
    ORDER BY v.created_at DESC, v.entry_id DESC, v.id ASC;
  END IF;
END;
$$ LANGUAGE plpgsql;

GRANT EXECUTE ON FUNCTION rpc_get_journal_history(text, date, date, int) TO authenticated, service_role, anon;

