-- ============================================================================

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'treasury_transactions' AND column_name = 'status'
    ) THEN
        ALTER TABLE public.treasury_transactions 
        ADD COLUMN status TEXT NOT NULL DEFAULT 'confirmed';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'treasury_transactions' AND column_name = 'payload'
    ) THEN
        ALTER TABLE public.treasury_transactions 
        ADD COLUMN payload JSONB DEFAULT '{}'::jsonb;
    END IF;

    ALTER TABLE public.treasury_transactions 
        DROP CONSTRAINT IF EXISTS treasury_transactions_type_check;

    ALTER TABLE public.treasury_transactions 
        ADD CONSTRAINT treasury_transactions_type_check 
        CHECK (type = ANY (ARRAY[
            'deposit',
            'expense',
            'withdrawal',
            'withdraw',
            'disbursement',
            'disbursement_out',
            'transfer_in',
            'transfer_out',
            'transfer',
            'return_in',
            'return_out',
            'currency_exchange_out',
            'currency_exchange_in',
            'currency_exchange',
            'exchange',
            'exchange_out',
            'exchange_in',
            'supplier_payment',
            'customer_payment',
            'clearing_agent_payment',
            'shipping_company_payment',
            'shareholder_payment',
            'shareholder_withdrawal',
            'customer_refund',
            'revenue',
            'multi_payment',
            'receipt'
        ]));

    ALTER TABLE public.bank_account_transactions 
        DROP CONSTRAINT IF EXISTS bank_account_transactions_type_check;

    ALTER TABLE public.bank_account_transactions 
        ADD CONSTRAINT bank_account_transactions_type_check 
        CHECK (type = ANY (ARRAY[
            'deposit',
            'withdraw',
            'withdrawal',
            'exchange_in',
            'exchange_out',
            'currency_exchange_in',
            'currency_exchange_out',
            'currency_exchange',
            'exchange',
            'transfer_in',
            'transfer_out',
            'transfer',
            'supplier_payment',
            'customer_payment',
            'clearing_agent_payment',
            'shipping_company_payment',
            'shareholder_payment',
            'shareholder_withdrawal',
            'customer_refund',
            'revenue',
            'multi_payment',
            'receipt',
            'expense'
        ]));
END $$;

CREATE OR REPLACE FUNCTION public.fn_require_expense_account_treasury()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
    IF NEW.status = 'draft' THEN
        RETURN NEW;
    END IF;

    IF NEW.type = 'expense' 
       AND NEW.expense_account_id IS NULL 
       AND NEW.supplier_id IS NULL 
       AND NEW.customer_id IS NULL 
       AND NEW.clearing_agent_id IS NULL 
       AND NEW.shipping_company_id IS NULL 
       AND NEW.shareholder_id IS NULL THEN
        RAISE EXCEPTION 'ÙŠØ¬Ø¨ Ø§Ø®ØªÙŠØ§Ø± Ø­Ø³Ø§Ø¨ Ù…ØµØ±ÙˆÙØ§Øª Ù…Ù† Ø´Ø¬Ø±Ø© Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª â€” Ù„Ø§ ÙŠØ³Ù…Ø­ Ø¨Ø§Ù„Ù‚ÙŠÙˆØ¯ Ø§Ù„Ø§ÙØªØ±Ø§Ø¶ÙŠØ©';
    END IF;

    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.fn_require_revenue_account_treasury()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
    IF NEW.status = 'draft' THEN
        RETURN NEW;
    END IF;

    -- Skip revenue account check for internal transfers, cheque feedings, custody settlements, and opening balances
    IF NEW.source_type IN ('cheque', 'transfer', 'bank_transfer', 'treasury_transfer', 'opening_balance', 'custody_settlement')
       OR NEW.reference_type IN ('cheque', 'transfer', 'bank_transfer', 'custody_settlement') THEN
        RETURN NEW;
    END IF;

    IF NEW.type = 'deposit' 
       AND NEW.revenue_account_id IS NULL 
       AND NEW.customer_id IS NULL 
       AND NEW.supplier_id IS NULL 
       AND NEW.clearing_agent_id IS NULL 
       AND NEW.shipping_company_id IS NULL 
       AND NEW.shareholder_id IS NULL THEN
        RAISE EXCEPTION 'ÙŠØ¬Ø¨ Ø§Ø®ØªÙŠØ§Ø± Ø­Ø³Ø§Ø¨ Ø¥ÙŠØ±Ø§Ø¯Ø§Øª Ù…Ù† Ø´Ø¬Ø±Ø© Ø§Ù„Ø­Ø³Ø§Ø¨Ø§Øª â€” Ù„Ø§ ÙŠØ³Ù…Ø­ Ø¨Ø§Ù„Ù‚ÙŠÙˆØ¯ Ø§Ù„Ø§ÙØªØ±Ø§Ø¶ÙŠØ©';
    END IF;

    RETURN NEW;
END;
$$;
-- â”€â”€ rpc_save_treasury_draft & rpc_update_treasury_draft â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
ALTER TABLE public.treasury_transactions
  ADD COLUMN IF NOT EXISTS cost_center_id TEXT,
  ADD COLUMN IF NOT EXISTS branch_id BIGINT,
  ADD COLUMN IF NOT EXISTS to_branch_id BIGINT,
  ADD COLUMN IF NOT EXISTS to_cost_center_id TEXT;

DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT oid::regprocedure AS func_sig 
             FROM pg_proc 
             WHERE proname IN ('rpc_save_treasury_draft', 'rpc_update_treasury_draft')
               AND pronamespace = 'public'::regnamespace
    LOOP
        EXECUTE 'DROP FUNCTION ' || r.func_sig || ' CASCADE';
    END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.rpc_save_treasury_draft(
    p_treasury_id BIGINT,
    p_type TEXT,
    p_amount NUMERIC,
    p_currency TEXT,
    p_description TEXT DEFAULT NULL,
    p_notes TEXT DEFAULT NULL,
    p_category_id BIGINT DEFAULT NULL,
    p_expense_account_id BIGINT DEFAULT NULL,
    p_revenue_account_id BIGINT DEFAULT NULL,
    p_customer_id BIGINT DEFAULT NULL,
    p_supplier_id UUID DEFAULT NULL,
    p_clearing_agent_id BIGINT DEFAULT NULL,
    p_shipping_company_id BIGINT DEFAULT NULL,
    p_shareholder_id UUID DEFAULT NULL,
    p_payload JSONB DEFAULT '{}'::jsonb,
    p_cost_center_id TEXT DEFAULT NULL,
    p_branch_id BIGINT DEFAULT NULL,
    p_to_branch_id BIGINT DEFAULT NULL,
    p_to_cost_center_id TEXT DEFAULT NULL
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_tx_id BIGINT;
    v_payload JSONB;
    v_cc_id TEXT;
    v_branch_id BIGINT;
    v_cat_id BIGINT := p_category_id;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Ø§Ù„Ù…Ø¨Ù„Øº ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† Ø£ÙƒØ¨Ø± Ù…Ù† ØµÙØ±';
    END IF;

    -- Safety check: ensure category_id actually exists in expense_categories to prevent FK 23503
    IF v_cat_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.expense_categories WHERE id = v_cat_id) THEN
        v_cat_id := NULL;
    END IF;

    v_cc_id := COALESCE(p_cost_center_id, p_payload->>'cost_center_id');
    v_branch_id := COALESCE(p_branch_id, CASE WHEN (p_payload->>'branch_id') ~ '^[0-9]+$' THEN (p_payload->>'branch_id')::BIGINT ELSE NULL END);

    v_payload := COALESCE(p_payload, '{}'::jsonb);
    IF v_cc_id IS NOT NULL THEN
        v_payload := jsonb_set(v_payload, '{cost_center_id}', to_jsonb(v_cc_id));
    END IF;
    IF v_branch_id IS NOT NULL THEN
        v_payload := jsonb_set(v_payload, '{branch_id}', to_jsonb(v_branch_id));
    END IF;
    IF p_to_branch_id IS NOT NULL THEN
        v_payload := jsonb_set(v_payload, '{to_branch_id}', to_jsonb(p_to_branch_id));
    END IF;
    IF p_to_cost_center_id IS NOT NULL THEN
        v_payload := jsonb_set(v_payload, '{to_cost_center_id}', to_jsonb(p_to_cost_center_id));
    END IF;

    INSERT INTO public.treasury_transactions (
        treasury_id,
        type,
        amount,
        currency,
        description,
        notes,
        category_id,
        expense_account_id,
        revenue_account_id,
        customer_id,
        supplier_id,
        clearing_agent_id,
        shipping_company_id,
        shareholder_id,
        status,
        payload,
        cost_center_id,
        branch_id,
        to_branch_id,
        to_cost_center_id,
        created_by,
        created_at
    ) VALUES (
        p_treasury_id,
        p_type,
        p_amount,
        p_currency,
        p_description,
        p_notes,
        v_cat_id,
        p_expense_account_id,
        p_revenue_account_id,
        p_customer_id,
        p_supplier_id,
        p_clearing_agent_id,
        p_shipping_company_id,
        p_shareholder_id,
        'draft',
        v_payload,
        v_cc_id,
        v_branch_id,
        p_to_branch_id,
        p_to_cost_center_id,
        auth.uid(),
        NOW()
    )
    RETURNING id INTO v_tx_id;

    RETURN v_tx_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_save_treasury_draft(BIGINT, TEXT, NUMERIC, TEXT, TEXT, TEXT, BIGINT, BIGINT, BIGINT, BIGINT, UUID, BIGINT, BIGINT, UUID, JSONB, TEXT, BIGINT, BIGINT, TEXT) TO authenticated, service_role, anon;

CREATE OR REPLACE FUNCTION public.rpc_update_treasury_draft(
    p_transaction_id BIGINT,
    p_treasury_id BIGINT DEFAULT NULL,
    p_amount NUMERIC DEFAULT NULL,
    p_currency TEXT DEFAULT NULL,
    p_description TEXT DEFAULT NULL,
    p_notes TEXT DEFAULT NULL,
    p_category_id BIGINT DEFAULT NULL,
    p_expense_account_id BIGINT DEFAULT NULL,
    p_revenue_account_id BIGINT DEFAULT NULL,
    p_customer_id BIGINT DEFAULT NULL,
    p_supplier_id UUID DEFAULT NULL,
    p_clearing_agent_id BIGINT DEFAULT NULL,
    p_shipping_company_id BIGINT DEFAULT NULL,
    p_shareholder_id UUID DEFAULT NULL,
    p_payload JSONB DEFAULT NULL,
    p_cost_center_id TEXT DEFAULT NULL,
    p_branch_id BIGINT DEFAULT NULL,
    p_to_branch_id BIGINT DEFAULT NULL,
    p_to_cost_center_id TEXT DEFAULT NULL
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_cc_id TEXT;
    v_branch_id BIGINT;
    v_payload JSONB;
    v_cat_id BIGINT := p_category_id;
BEGIN
    -- Safety check: ensure category_id actually exists in expense_categories to prevent FK 23503
    IF v_cat_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.expense_categories WHERE id = v_cat_id) THEN
        v_cat_id := NULL;
    END IF;

    v_cc_id := COALESCE(p_cost_center_id, p_payload->>'cost_center_id');
    v_branch_id := COALESCE(p_branch_id, CASE WHEN (p_payload->>'branch_id') ~ '^[0-9]+$' THEN (p_payload->>'branch_id')::BIGINT ELSE NULL END);

    UPDATE public.treasury_transactions
    SET
        treasury_id = COALESCE(p_treasury_id, treasury_id),
        amount = COALESCE(p_amount, amount),
        currency = COALESCE(p_currency, currency),
        description = COALESCE(p_description, description),
        notes = p_notes,
        category_id = v_cat_id,
        expense_account_id = p_expense_account_id,
        revenue_account_id = p_revenue_account_id,
        customer_id = p_customer_id,
        supplier_id = p_supplier_id,
        clearing_agent_id = p_clearing_agent_id,
        shipping_company_id = p_shipping_company_id,
        shareholder_id = p_shareholder_id,
        cost_center_id = COALESCE(v_cc_id, cost_center_id),
        branch_id = COALESCE(v_branch_id, branch_id),
        to_branch_id = COALESCE(p_to_branch_id, to_branch_id),
        to_cost_center_id = COALESCE(p_to_cost_center_id, to_cost_center_id),
        payload = CASE 
            WHEN p_payload IS NOT NULL THEN p_payload
            ELSE payload 
        END
    WHERE id = p_transaction_id AND status = 'draft';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ù„Ù… ÙŠØªÙ… Ø§Ù„Ø¹Ø«ÙˆØ± Ø¹Ù„Ù‰ Ø§Ù„Ù…Ø³ÙˆØ¯Ø© Ø£Ùˆ Ø£Ù†Ù‡Ø§ Ù…Ø¤ÙƒØ¯Ø© Ø¨Ø§Ù„ÙØ¹Ù„';
    END IF;

    RETURN TRUE;
END;
$$;

GRANT EXECUTE ON FUNCTION public.rpc_update_treasury_draft(BIGINT, BIGINT, NUMERIC, TEXT, TEXT, TEXT, BIGINT, BIGINT, BIGINT, BIGINT, UUID, BIGINT, BIGINT, UUID, JSONB, TEXT, BIGINT, BIGINT, TEXT) TO authenticated, service_role, anon;



CREATE OR REPLACE FUNCTION public.rpc_delete_treasury_draft(
    p_transaction_id BIGINT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_deleted_count INT;
BEGIN
    DELETE FROM public.treasury_transactions
    WHERE id = p_transaction_id AND status = 'draft';

    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    IF v_deleted_count = 0 THEN
        RAISE EXCEPTION 'Ù„Ù… ÙŠØªÙ… Ø§Ù„Ø¹Ø«ÙˆØ± Ø¹Ù„Ù‰ Ø§Ù„Ù…Ø³ÙˆØ¯Ø© Ø£Ùˆ ØªÙ… ØªØ£ÙƒÙŠØ¯Ù‡Ø§ Ù…Ø³Ø¨Ù‚Ø§Ù‹';
    END IF;

    RETURN TRUE;
END;
$$;

CREATE OR REPLACE FUNCTION public.rpc_confirm_treasury_draft(
    p_transaction_id BIGINT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_tx RECORD;
    v_res JSONB;
    v_receipt_type TEXT;
    v_counterparty_type TEXT;
    v_mp_source_type TEXT;
    v_mp_source_id BIGINT;
BEGIN
    SELECT * INTO v_tx
    FROM public.treasury_transactions
    WHERE id = p_transaction_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ø§Ù„Ø­Ø±ÙƒØ© ØºÙŠØ± Ù…ÙˆØ¬ÙˆØ¯Ø©';
    END IF;

    IF v_tx.status != 'draft' THEN
        RAISE EXCEPTION 'Ù‡Ø°Ù‡ Ø§Ù„Ø­Ø±ÙƒØ© Ù…Ø¤ÙƒØ¯Ø© Ø¨Ø§Ù„ÙØ¹Ù„ ÙˆÙ„ÙŠØ³Øª Ù…Ø³ÙˆØ¯Ø©';
    END IF;

    IF v_tx.type = 'deposit' OR v_tx.type = 'receipt' THEN
        v_receipt_type := COALESCE(v_tx.payload->>'receipt_type', 'cash');
        v_counterparty_type := v_tx.payload->>'counterparty_type';

        v_res := public.receive_payment(
            p_receipt_type      := v_receipt_type,
            p_amount            := v_tx.amount,
            p_currency          := v_tx.currency,
            p_counterparty_type := v_counterparty_type,
            p_counterparty_id   := v_tx.customer_id,
            p_supplier_id       := v_tx.supplier_id,
            p_shareholder_id    := v_tx.shareholder_id,
            p_description       := v_tx.description,
            p_notes             := v_tx.notes,
            p_treasury_id       := v_tx.treasury_id
        );

        DELETE FROM public.treasury_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'ØªÙ… ØªØ£ÙƒÙŠØ¯ Ø§Ù„Ø§Ø³ØªÙ„Ø§Ù… ÙˆØªØ±Ø­ÙŠÙ„ Ø§Ù„Ù‚ÙŠØ¯ Ø¨Ù†Ø¬Ø§Ø­', 'result', v_res);

    ELSIF v_tx.type = 'multi_payment' OR COALESCE((v_tx.payload->>'is_multi_payment')::boolean, false) = true THEN
        -- Read source_type and source_id from payload (fixes bank account multi-payment)
        v_mp_source_type := COALESCE(v_tx.payload->>'source_type', 'treasury');
        v_mp_source_id   := COALESCE(
            (v_tx.payload->>'source_id')::bigint,
            v_tx.treasury_id::bigint
        );

        v_res := public.rpc_entity_multi_payment(
            p_source_type        := v_mp_source_type,
            p_source_id          := v_mp_source_id,
            p_currency           := v_tx.currency,
            p_amount             := v_tx.amount,
            p_entity_type        := LOWER(COALESCE(v_tx.payload->>'entity_type', 'supplier')),
            p_entity_id          := COALESCE(v_tx.payload->>'entity_id', v_tx.supplier_id::text),
            p_description        := COALESCE(v_tx.description, 'Ø³Ø¯Ø§Ø¯ Ù…ØªØ¹Ø¯Ø¯'),
            p_notes              := v_tx.notes,
            p_expense_account_id := v_tx.expense_account_id
        );

        DELETE FROM public.treasury_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'ØªÙ… ØªØ£ÙƒÙŠØ¯ Ø§Ù„Ø³Ø¯Ø§Ø¯ Ø§Ù„Ù…ØªØ¹Ø¯Ø¯ Ø¨Ù†Ø¬Ø§Ø­', 'result', v_res);

    ELSIF v_tx.type = 'exchange' OR v_tx.type = 'currency_exchange' THEN
        PERFORM public.exchange_currency(
            p_treasury_id   := v_tx.treasury_id::text,
            p_from_currency := COALESCE(v_tx.payload->>'from_currency', v_tx.currency),
            p_to_currency   := (v_tx.payload->>'to_currency')::text,
            p_amount_from   := COALESCE((v_tx.payload->>'amount_from')::numeric, v_tx.amount),
            p_amount_to     := (v_tx.payload->>'amount_to')::numeric,
            p_exchange_rate := (v_tx.payload->>'exchange_rate')::numeric,
            p_user_id       := v_tx.created_by,
            p_transfer_mode := COALESCE(v_tx.payload->>'transfer_mode', 'exchange')
        );

        DELETE FROM public.treasury_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'ØªÙ… ØªØ£ÙƒÙŠØ¯ ØªØ­ÙˆÙŠÙ„ Ø§Ù„Ø¹Ù…Ù„Ø© ÙˆØªØ±Ø­ÙŠÙ„ Ø§Ù„Ù‚ÙŠØ¯ Ø¨Ù†Ø¬Ø§Ø­');

    ELSE
        IF v_tx.category_id IS NOT NULL AND v_tx.category_id > 0 THEN
            PERFORM public.spend_with_category(
                p_treasury_id          := v_tx.treasury_id,
                p_currency             := v_tx.currency,
                p_amount               := v_tx.amount,
                p_description          := COALESCE(v_tx.description, ''),
                p_category_id          := v_tx.category_id::integer,
                p_customer_id          := v_tx.customer_id::integer,
                p_supplier_id          := v_tx.supplier_id,
                p_clearing_agent_id    := v_tx.clearing_agent_id,
                p_shipping_company_id  := v_tx.shipping_company_id,
                p_shareholder_id       := v_tx.shareholder_id,
                p_expense_account_id   := v_tx.expense_account_id::integer,
                p_reference_type       := v_tx.payload->>'reference_type',
                p_reference_id         := v_tx.payload->>'reference_id',
                p_notes                := v_tx.notes
            );
        ELSE
            PERFORM public.spend_custody(
                p_treasury_id          := v_tx.treasury_id,
                p_currency             := v_tx.currency,
                p_amount               := v_tx.amount,
                p_description          := COALESCE(v_tx.description, ''),
                p_expense_account_id   := v_tx.expense_account_id::integer,
                p_customer_id          := v_tx.customer_id::integer,
                p_supplier_id          := v_tx.supplier_id,
                p_clearing_agent_id    := v_tx.clearing_agent_id,
                p_shipping_company_id  := v_tx.shipping_company_id,
                p_shareholder_id       := v_tx.shareholder_id,
                p_reference_type       := v_tx.payload->>'reference_type',
                p_reference_id         := v_tx.payload->>'reference_id',
                p_notes                := v_tx.notes
            );
        END IF;

        DELETE FROM public.treasury_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'ØªÙ… ØªØ£ÙƒÙŠØ¯ ØµØ±Ù Ø§Ù„Ù…ØµØ±ÙˆÙ ÙˆØªØ±Ø­ÙŠÙ„ Ø§Ù„Ù‚ÙŠØ¯ Ø¨Ù†Ø¬Ø§Ø­');
    END IF;
END;
$$;

