CREATE OR REPLACE FUNCTION public.receive_payment(
    p_receipt_type character varying,
    p_amount numeric,
    p_currency character varying,
    p_counterparty_type character varying DEFAULT NULL::character varying,
    p_counterparty_id bigint DEFAULT NULL::bigint,
    p_supplier_id uuid DEFAULT NULL::uuid,
    p_shareholder_id uuid DEFAULT NULL::uuid,
    p_description text DEFAULT NULL::text,
    p_notes text DEFAULT NULL::text,
    p_treasury_id bigint DEFAULT NULL::bigint
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_treasury_id       BIGINT;
    v_current_balance   NUMERIC := 0;
    v_current_cost_base NUMERIC := 0;
    v_current_book_rate NUMERIC := 1.0;
    v_new_balance       NUMERIC := 0;
    v_new_cost_base     NUMERIC := 0;
    v_new_book_rate     NUMERIC := 1.0;
    v_tx_id             BIGINT;
    v_company_id        UUID;
    v_treasury_acct     BIGINT;
    v_ar_acct           BIGINT;
    v_je_id             BIGINT;
    v_desc              TEXT;
    v_counterparty_name TEXT;
    v_source_type       TEXT;
    v_treasury_name     TEXT;
    v_je_source         TEXT;
    v_credit_acct       BIGINT;
    v_rate              NUMERIC := 1.0;
    v_base_amount       NUMERIC;
    v_snapshot          JSONB;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Ø§Ù„Ù…Ø¨Ù„Øº ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† Ø£ÙƒØ¨Ø± Ù…Ù† ØµÙØ±';
    END IF;

    IF p_treasury_id IS NOT NULL THEN
        v_treasury_id := p_treasury_id;
    ELSE
        SELECT id INTO v_treasury_id
        FROM public.treasuries
        WHERE type = 'main' AND user_id = auth.uid()
        LIMIT 1;
        IF v_treasury_id IS NULL THEN
            SELECT id INTO v_treasury_id FROM public.treasuries WHERE type = 'main' LIMIT 1;
        END IF;
        IF v_treasury_id IS NULL THEN
            RAISE EXCEPTION 'Ù„Ù… ÙŠØªÙ… Ø§Ù„Ø¹Ø«ÙˆØ± Ø¹Ù„Ù‰ Ø§Ù„Ø®Ø²ÙŠÙ†Ø© Ø§Ù„Ø±Ø¦ÙŠØ³ÙŠØ©.';
        END IF;
    END IF;

    SELECT t.company_id INTO v_company_id FROM public.treasuries t WHERE t.id = v_treasury_id;

    -- 1. Lock treasury balance row & retrieve current cost_base and book_rate
    SELECT COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_current_balance, v_current_cost_base, v_current_book_rate
    FROM public.treasury_balances
    WHERE treasury_id::TEXT = v_treasury_id::TEXT AND currency = p_currency
    FOR UPDATE;

    -- 2. Calculate spot exchange rate & base amount
    IF p_currency = 'EGP' THEN
        v_rate := 1.0;
        v_base_amount := p_amount;
        v_new_cost_base := COALESCE(v_current_cost_base, 0) + p_amount;
        v_new_book_rate := 1.0;
    ELSE
        v_rate := public.fn_get_exchange_rate(p_currency);
        v_base_amount := ROUND(p_amount * v_rate, 2);
        v_new_cost_base := COALESCE(v_current_cost_base, 0) + v_base_amount;
    END IF;

    v_new_balance := COALESCE(v_current_balance, 0) + p_amount;

    IF v_new_balance > 0 AND p_currency != 'EGP' THEN
        v_new_book_rate := ROUND(v_new_cost_base / v_new_balance, 4);
    ELSIF p_currency = 'EGP' THEN
        v_new_book_rate := 1.0;
    ELSE
        v_new_book_rate := v_rate;
    END IF;

    IF p_counterparty_type IS NULL OR p_counterparty_type = 'opening' THEN
        v_source_type := 'opening_balance';
        SELECT name INTO v_treasury_name FROM public.treasuries WHERE id = v_treasury_id;
        v_desc := COALESCE(
            NULLIF(p_description, ''),
            'Ø§Ù„Ø±ØµÙŠØ¯ Ø§Ù„Ø§ÙØªØªØ§Ø­ÙŠ Ù„Ù„' || COALESCE(v_treasury_name, 'Ø§Ù„Ø®Ø²ÙŠÙ†Ø© Ø§Ù„Ø±Ø¦ÙŠØ³ÙŠØ©')
        );
    ELSE
        v_source_type := p_counterparty_type;
        v_desc := COALESCE(NULLIF(p_description, ''), 'Ø§Ø³ØªÙ„Ø§Ù… ' || p_receipt_type);
    END IF;

    v_treasury_acct := public.resolve_treasury_account(v_treasury_id, p_currency, v_company_id);

    IF p_counterparty_type = 'customer' THEN
        SELECT c.account_id, c.name INTO v_credit_acct, v_counterparty_name FROM public.customers c WHERE c.id = p_counterparty_id;
        IF v_counterparty_name IS NOT NULL AND v_counterparty_name != '' THEN
            IF p_description IS NOT NULL AND p_description != '' AND p_description NOT LIKE '%' || v_counterparty_name || '%' THEN
                v_desc := p_description || ' - Ø§Ù„Ø¹Ù…ÙŠÙ„: ' || v_counterparty_name || ' (Ø³Ø¯Ø§Ø¯ Ø­Ø³Ø§Ø¨ Ø§Ù„Ø¹Ù…ÙŠÙ„)';
            ELSIF p_description IS NULL OR p_description = '' OR p_description = 'Ø§Ø³ØªÙ„Ø§Ù… ' || p_receipt_type THEN
                v_desc := 'Ø§Ø³ØªÙ„Ø§Ù… Ù†Ù‚Ø¯ÙŠØ© Ù…Ù† Ø§Ù„Ø¹Ù…ÙŠÙ„ ' || v_counterparty_name || ' (Ø³Ø¯Ø§Ø¯ Ø­Ø³Ø§Ø¨ Ø§Ù„Ø¹Ù…ÙŠÙ„)';
            END IF;
        END IF;
        IF v_credit_acct IS NOT NULL THEN
            SELECT id INTO v_credit_acct FROM public.accounts WHERE id = v_credit_acct AND is_leaf = true AND is_active = true;
        END IF;
        IF v_credit_acct IS NULL THEN
            v_credit_acct := public.resolve_gl_account('12511', v_company_id);
        END IF;
    ELSIF p_counterparty_type = 'supplier' THEN
        SELECT s.account_id, s.name INTO v_credit_acct, v_counterparty_name FROM public.suppliers s WHERE s.id = p_supplier_id;
        IF v_counterparty_name IS NOT NULL AND v_counterparty_name != '' THEN
            IF p_description IS NOT NULL AND p_description != '' AND p_description NOT LIKE '%' || v_counterparty_name || '%' THEN
                v_desc := p_description || ' - Ø§Ù„Ù…ÙˆØ±Ø¯: ' || v_counterparty_name || ' (Ø¥ÙŠØ¯Ø§Ø¹ Ù†Ù‚Ø¯ÙŠ / Ø¯ÙØ¹Ø© Ù…Ù‚Ø¯Ù…Ø©)';
            ELSIF p_description IS NULL OR p_description = '' OR p_description = 'Ø§Ø³ØªÙ„Ø§Ù… ' || p_receipt_type OR p_description LIKE 'Ø§Ø³ØªÙ„Ø§Ù… % Ù…Ù† ' || v_counterparty_name THEN
                v_desc := 'Ø¥ÙŠØ¯Ø§Ø¹ Ù†Ù‚Ø¯ÙŠ / Ø¯ÙØ¹Ø© Ù…Ù‚Ø¯Ù…Ø© Ù…Ù† Ø§Ù„Ù…ÙˆØ±Ø¯ ' || v_counterparty_name;
            END IF;
        END IF;
        IF v_credit_acct IS NOT NULL THEN
            SELECT id INTO v_credit_acct FROM public.accounts WHERE id = v_credit_acct AND is_leaf = true AND is_active = true;
        END IF;
        IF v_credit_acct IS NULL THEN
            v_credit_acct := public.resolve_gl_account('21113', v_company_id);
        END IF;
        IF v_credit_acct IS NULL THEN
            v_credit_acct := public.resolve_gl_account('2000', v_company_id);
        END IF;
    ELSIF p_counterparty_type = 'clearing_agent' THEN
        SELECT ca.account_id INTO v_credit_acct FROM public.clearing_agents ca WHERE ca.id = p_counterparty_id;
        IF v_credit_acct IS NOT NULL THEN
            SELECT id INTO v_credit_acct FROM public.accounts WHERE id = v_credit_acct AND is_leaf = true AND is_active = true;
        END IF;
        IF v_credit_acct IS NULL THEN
            v_credit_acct := public.resolve_gl_account('2000', v_company_id);
        END IF;
    ELSIF p_counterparty_type = 'shipping_company' THEN
        SELECT sc.account_id INTO v_credit_acct FROM public.shipping_companies sc WHERE sc.id = p_counterparty_id;
        IF v_credit_acct IS NOT NULL THEN
            SELECT id INTO v_credit_acct FROM public.accounts WHERE id = v_credit_acct AND is_leaf = true AND is_active = true;
        END IF;
        IF v_credit_acct IS NULL THEN
            v_credit_acct := public.resolve_gl_account('2000', v_company_id);
        END IF;
    ELSIF p_counterparty_type = 'shareholder' THEN
        SELECT account_id INTO v_credit_acct FROM public.shareholders WHERE id = p_shareholder_id;
        IF v_credit_acct IS NOT NULL THEN
            SELECT id INTO v_credit_acct FROM public.accounts WHERE id = v_credit_acct AND is_leaf = true AND is_active = true;
        END IF;
        IF v_credit_acct IS NULL THEN
            v_credit_acct := public.resolve_equity_account(p_currency, v_company_id);
        END IF;
    ELSE
        v_credit_acct := public.resolve_opening_balance_equity_account(p_currency, v_company_id);
    END IF;

    v_snapshot := jsonb_build_object(
        'currency', p_currency,
        'exchange_rate', v_rate,
        'book_rate', v_new_book_rate,
        'amount', p_amount,
        'amount_in_base_currency', v_base_amount,
        'rate_date', CURRENT_DATE,
        'rate_source', 'exchange_rates_table'
    );

    INSERT INTO public.treasury_transactions (
        treasury_id, type, amount, currency, description, source_type,
        customer_id, supplier_id, clearing_agent_id, shipping_company_id, shareholder_id,
        balance_before, balance_after,
        created_by, revenue_account_id, notes,
        exchange_rate, amount_in_base_currency, currency_snapshot
    ) VALUES (
        v_treasury_id, 'deposit', p_amount, p_currency, v_desc, v_source_type,
        CASE WHEN p_counterparty_type = 'customer' THEN p_counterparty_id ELSE NULL END,
        CASE WHEN p_counterparty_type = 'supplier' THEN p_supplier_id ELSE NULL END,
        CASE WHEN p_counterparty_type = 'clearing_agent' THEN p_counterparty_id ELSE NULL END,
        CASE WHEN p_counterparty_type = 'shipping_company' THEN p_counterparty_id ELSE NULL END,
        CASE WHEN p_counterparty_type = 'shareholder' THEN p_shareholder_id ELSE NULL END,
        v_current_balance, v_new_balance,
        auth.uid(),
        v_credit_acct, p_notes,
        v_rate, v_base_amount, v_snapshot
    ) RETURNING id INTO v_tx_id;

    IF p_counterparty_type = 'customer' AND p_counterparty_id IS NOT NULL THEN
        UPDATE public.customers SET balance = balance - p_amount WHERE id = p_counterparty_id;
        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('customer', p_counterparty_id::TEXT, 'credit', p_amount, p_currency, 'receive', v_tx_id, v_desc, auth.uid());

        v_ar_acct := v_credit_acct;
        v_je_id := public.post_journal_entry(
            'customer_payment', v_desc, CURRENT_DATE, v_company_id, auth.uid(),
            jsonb_build_array(
                jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
                jsonb_build_object('account_id', v_ar_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
            )
        );

    ELSIF p_counterparty_type = 'supplier' AND p_supplier_id IS NOT NULL THEN
        UPDATE public.suppliers 
        SET outstanding_balance = outstanding_balance + p_amount 
        WHERE id = p_supplier_id;

        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('supplier', p_supplier_id::TEXT, 'credit', p_amount, p_currency, 'supplier_deposit', v_tx_id, v_desc, auth.uid());

        v_ar_acct := v_credit_acct;
        v_je_id := public.post_journal_entry(
            'supplier_advance_deposit', v_desc, CURRENT_DATE, v_company_id, auth.uid(),
            jsonb_build_array(
                jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
                jsonb_build_object('account_id', v_ar_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
            )
        );

        IF to_regproc('public.sync_supplier_balances') IS NOT NULL THEN
            PERFORM public.sync_supplier_balances(p_supplier_id);
        END IF;

    ELSIF p_counterparty_type = 'clearing_agent' AND p_counterparty_id IS NOT NULL THEN
        UPDATE public.clearing_agents
        SET manual_adjustment = COALESCE(manual_adjustment, 0) + p_amount,
            balance = COALESCE(balance, 0) + p_amount
        WHERE id = p_counterparty_id;

        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('clearing_agent', p_counterparty_id::TEXT, 'credit', p_amount, p_currency, 'receive', v_tx_id, v_desc, auth.uid());

        v_ar_acct := v_credit_acct;
        v_je_id := public.post_journal_entry(
            'clearing_agent_payment_received', v_desc, CURRENT_DATE, v_company_id, auth.uid(),
            jsonb_build_array(
                jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
                jsonb_build_object('account_id', v_ar_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
            )
        );

    ELSIF p_counterparty_type = 'shipping_company' AND p_counterparty_id IS NOT NULL THEN
        UPDATE public.shipping_companies
        SET manual_adjustment = COALESCE(manual_adjustment, 0) + p_amount,
            balance = COALESCE(balance, 0) + p_amount
        WHERE id = p_counterparty_id;

        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('shipping_company', p_counterparty_id::TEXT, 'credit', p_amount, p_currency, 'receive', v_tx_id, v_desc, auth.uid());

        v_ar_acct := v_credit_acct;
        v_je_id := public.post_journal_entry(
            'shipping_company_payment_received', v_desc, CURRENT_DATE, v_company_id, auth.uid(),
            jsonb_build_array(
                jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
                jsonb_build_object('account_id', v_ar_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
            )
        );

    ELSIF p_counterparty_type = 'shareholder' AND p_shareholder_id IS NOT NULL THEN
        IF p_currency = 'EGP' THEN
            UPDATE public.shareholders SET current_balance_egp = current_balance_egp + p_amount WHERE id = p_shareholder_id;
        ELSIF p_currency = 'USD' THEN
            UPDATE public.shareholders SET current_balance_usd = current_balance_usd + p_amount WHERE id = p_shareholder_id;
        ELSIF p_currency = 'EUR' THEN
            UPDATE public.shareholders SET current_balance_eur = current_balance_eur + p_amount WHERE id = p_shareholder_id;
        ELSIF p_currency = 'GBP' THEN
            UPDATE public.shareholders SET current_balance_gbp = current_balance_gbp + p_amount WHERE id = p_shareholder_id;
        END IF;

        INSERT INTO public.ledger_entries (entity_type, entity_id, entry_type, amount, currency, reference_type, reference_id, description, created_by)
        VALUES ('shareholder', p_shareholder_id::TEXT, 'credit', p_amount, p_currency, 'receive', v_tx_id, v_desc, auth.uid());

        v_ar_acct := v_credit_acct;
        v_je_id := public.post_journal_entry(
            'shareholder_payment_received', v_desc, CURRENT_DATE, v_company_id, auth.uid(),
            jsonb_build_array(
                jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
                jsonb_build_object('account_id', v_ar_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
            )
        );

    ELSE
        v_je_source := 'opening_balance';
        v_je_id := public.post_journal_entry(
            v_je_source, v_desc, CURRENT_DATE, v_company_id, auth.uid(),
            jsonb_build_array(
                jsonb_build_object('account_id', v_treasury_acct, 'debit', p_amount, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', p_currency, 'description', v_desc),
                jsonb_build_object('account_id', v_credit_acct, 'debit', 0, 'credit', p_amount, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', p_currency, 'description', v_desc)
            )
        );
    END IF;

    UPDATE public.treasury_transactions SET journal_entry_id = v_je_id WHERE id = v_tx_id;

    -- Sync treasury_balances with full cost_base and book_rate
    INSERT INTO public.treasury_balances (treasury_id, currency, balance, cost_base, book_rate, account_id, updated_at)
    VALUES (v_treasury_id, p_currency, v_new_balance, v_new_cost_base, v_new_book_rate, v_treasury_acct, NOW())
    ON CONFLICT (treasury_id, currency) DO UPDATE
    SET balance = v_new_balance,
        cost_base = v_new_cost_base,
        book_rate = v_new_book_rate,
        updated_at = NOW();

    RETURN jsonb_build_object('success', true, 'treasury_tx_id', v_tx_id, 'journal_entry_id', v_je_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.exchange_currency(
    p_treasury_id text,
    p_from_currency text,
    p_to_currency text,
    p_amount_from numeric,
    p_amount_to numeric,
    p_exchange_rate numeric,
    p_user_id uuid DEFAULT auth.uid(),
    p_transfer_mode text DEFAULT 'exchange',
    p_description text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_treasury_id         BIGINT;
    v_balance_before_from DECIMAL(15,2);
    v_balance_after_from  DECIMAL(15,2);
    v_cost_before_from    DECIMAL(15,2);
    v_rate_before_from    DECIMAL(15,4);
    v_new_cost_from       DECIMAL(15,2);
    v_new_rate_from       DECIMAL(15,4);

    v_balance_before_to   DECIMAL(15,2);
    v_balance_after_to    DECIMAL(15,2);
    v_cost_before_to      DECIMAL(15,2);
    v_rate_before_to      DECIMAL(15,4);
    v_new_cost_to         DECIMAL(15,2);
    v_new_rate_to         DECIMAL(15,4);

    v_company_id          UUID;
    v_from_acct           BIGINT;
    v_to_acct             BIGINT;
    v_fx_gain_loss_acct   BIGINT;
    v_je_id               BIGINT;
    v_desc                TEXT;
    v_base_amount         NUMERIC;
    v_cost_base_released  NUMERIC;
    v_realized_fx_diff    NUMERIC;
    v_user_id             UUID := COALESCE(p_user_id, auth.uid());
BEGIN
    IF p_amount_from <= 0 OR p_amount_to <= 0 THEN
        RAISE EXCEPTION 'Ø§Ù„Ù…Ø¨Ø§Ù„Øº ÙŠØ¬Ø¨ Ø£Ù† ØªÙƒÙˆÙ† Ø£ÙƒØ¨Ø± Ù…Ù† ØµÙØ±';
    END IF;

    IF UPPER(p_from_currency) = UPPER(p_to_currency) THEN
        RAISE EXCEPTION 'Ù„Ø§ ÙŠÙ…ÙƒÙ† Ø§Ù„ØªØ­ÙˆÙŠÙ„ Ù„Ù†ÙØ³ Ø§Ù„Ø¹Ù…Ù„Ø©';
    END IF;

    -- Clean treasury ID
    v_treasury_id := p_treasury_id::BIGINT;

    -- Description handling
    v_desc := COALESCE(
        NULLIF(TRIM(p_description), ''),
        'ØªØ­ÙˆÙŠÙ„ Ø¹Ù…Ù„Ø© Ù…Ù† (' || p_amount_from || ' ' || UPPER(p_from_currency) || ') Ø¥Ù„Ù‰ (' || p_amount_to || ' ' || UPPER(p_to_currency) || ') Ø¨Ø³Ø¹Ø± ' || p_exchange_rate
    );

    -- 1. Lock from_currency row in treasury_balances
    SELECT balance, COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_balance_before_from, v_cost_before_from, v_rate_before_from
    FROM public.treasury_balances
    WHERE treasury_id = v_treasury_id AND UPPER(currency) = UPPER(p_from_currency)
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ù„Ø§ ÙŠÙˆØ¬Ø¯ Ø±ØµÙŠØ¯ Ø¨Ø¹Ù…Ù„Ø© % ÙÙŠ Ù‡Ø°Ù‡ Ø§Ù„Ø®Ø²ÙŠÙ†Ø©', p_from_currency;
    END IF;

    IF v_balance_before_from < p_amount_from THEN
        RAISE EXCEPTION 'Ø§Ù„Ø±ØµÙŠØ¯ ØºÙŠØ± ÙƒØ§ÙÙ. Ø§Ù„Ù…ØªÙˆÙØ±: %ØŒ Ø§Ù„Ù…Ø·Ù„ÙˆØ¨: %', v_balance_before_from, p_amount_from;
    END IF;

    -- Ensure to_currency balance row exists
    INSERT INTO public.treasury_balances (treasury_id, currency, balance, cost_base, book_rate)
    VALUES (v_treasury_id, UPPER(p_to_currency), 0.00, 0.00, 1.0000)
    ON CONFLICT (treasury_id, currency) DO NOTHING;

    SELECT balance, COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_balance_before_to, v_cost_before_to, v_rate_before_to
    FROM public.treasury_balances
    WHERE treasury_id = v_treasury_id AND UPPER(currency) = UPPER(p_to_currency)
    FOR UPDATE;

    SELECT t.company_id INTO v_company_id FROM public.treasuries t WHERE t.id = v_treasury_id;
    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM public.sys_companies LIMIT 1;
    END IF;

    -- Resolve GL Accounts for from_currency and to_currency
    v_from_acct := public.resolve_treasury_account(v_treasury_id, p_from_currency, v_company_id);
    IF v_from_acct IS NULL THEN
        v_from_acct := public.resolve_gl_account(
            CASE UPPER(p_from_currency) 
                WHEN 'EGP' THEN '12111' 
                WHEN 'USD' THEN '12122' 
                WHEN 'EUR' THEN '12123' 
                WHEN 'GBP' THEN '12124' 
                ELSE '12111' 
            END,
            v_company_id
        );
    END IF;
    IF v_from_acct IS NULL THEN
        v_from_acct := public.resolve_gl_account(
            CASE UPPER(p_from_currency) 
                WHEN 'EGP' THEN '11101' 
                WHEN 'USD' THEN '11102' 
                WHEN 'EUR' THEN '11103' 
                WHEN 'GBP' THEN '11104' 
                ELSE '11101' 
            END,
            v_company_id
        );
    END IF;

    v_to_acct := public.resolve_treasury_account(v_treasury_id, p_to_currency, v_company_id);
    IF v_to_acct IS NULL THEN
        v_to_acct := public.resolve_gl_account(
            CASE UPPER(p_to_currency) 
                WHEN 'EGP' THEN '12111' 
                WHEN 'USD' THEN '12122' 
                WHEN 'EUR' THEN '12123' 
                WHEN 'GBP' THEN '12124' 
                ELSE '12111' 
            END,
            v_company_id
        );
    END IF;
    IF v_to_acct IS NULL THEN
        v_to_acct := public.resolve_gl_account(
            CASE UPPER(p_to_currency) 
                WHEN 'EGP' THEN '11101' 
                WHEN 'USD' THEN '11102' 
                WHEN 'EUR' THEN '11103' 
                WHEN 'GBP' THEN '11104' 
                ELSE '11101' 
            END,
            v_company_id
        );
    END IF;

    -- Calculate balances and cost base
    v_balance_after_from := v_balance_before_from - p_amount_from;
    v_balance_after_to   := v_balance_before_to + p_amount_to;

    IF UPPER(p_from_currency) != 'EGP' THEN
        -- Selling foreign currency -> release cost base
        v_cost_base_released := ROUND(p_amount_from * v_rate_before_from, 2);
        v_new_cost_from      := GREATEST(0, v_cost_before_from - v_cost_base_released);
        v_new_rate_from      := CASE WHEN v_balance_after_from > 0 THEN ROUND(v_new_cost_from / v_balance_after_from, 4) ELSE v_rate_before_from END;

        v_new_cost_to        := v_balance_after_to;
        v_new_rate_to        := 1.0;
        v_realized_fx_diff   := p_amount_to - v_cost_base_released;
    ELSE
        -- Buying foreign currency with EGP
        v_new_cost_from      := v_balance_after_from;
        v_new_rate_from      := 1.0;

        v_new_cost_to        := v_cost_before_to + p_amount_from;
        v_new_rate_to        := CASE WHEN v_balance_after_to > 0 THEN ROUND(v_new_cost_to / v_balance_after_to, 4) ELSE p_exchange_rate END;
        v_realized_fx_diff   := 0;
        v_cost_base_released := p_amount_from;
    END IF;

    -- Update treasury balances
    UPDATE public.treasury_balances
    SET balance    = v_balance_after_from,
        cost_base  = v_new_cost_from,
        book_rate  = v_new_rate_from,
        updated_at = NOW()
    WHERE treasury_id = v_treasury_id AND UPPER(currency) = UPPER(p_from_currency);

    UPDATE public.treasury_balances
    SET balance    = v_balance_after_to,
        cost_base  = v_new_cost_to,
        book_rate  = v_new_rate_to,
        updated_at = NOW()
    WHERE treasury_id = v_treasury_id AND UPPER(currency) = UPPER(p_to_currency);

    -- Base amount calculation
    IF UPPER(p_from_currency) = 'EGP' THEN
        v_base_amount := p_amount_from;
    ELSE
        v_base_amount := p_amount_to;
    END IF;

    -- Post balanced Journal Entry
    IF v_realized_fx_diff != 0 THEN
        IF v_realized_fx_diff > 0 THEN
            v_fx_gain_loss_acct := public.resolve_realized_fx_gain_account(v_company_id);
            IF v_fx_gain_loss_acct IS NULL THEN
                v_fx_gain_loss_acct := public.resolve_gl_account('4310', v_company_id);
            END IF;
            IF v_fx_gain_loss_acct IS NULL THEN
                v_fx_gain_loss_acct := public.resolve_gl_account('4220', v_company_id);
            END IF;

            v_je_id := public.post_journal_entry(
                'currency_exchange', v_desc, CURRENT_DATE, v_company_id, v_user_id,
                jsonb_build_array(
                    jsonb_build_object('account_id', v_to_acct, 'debit', p_amount_to, 'credit', 0, 'base_debit', p_amount_to, 'base_credit', 0, 'currency', UPPER(p_to_currency), 'description', v_desc),
                    jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount_from, 'base_debit', 0, 'base_credit', v_cost_base_released, 'currency', UPPER(p_from_currency), 'description', v_desc),
                    jsonb_build_object('account_id', v_fx_gain_loss_acct, 'debit', 0, 'credit', v_realized_fx_diff, 'base_debit', 0, 'base_credit', v_realized_fx_diff, 'currency', 'EGP', 'description', 'Ø£Ø±Ø¨Ø§Ø­ ÙØ±ÙˆÙ‚ Ø¹Ù…Ù„Ø© Ù…Ø­Ù‚Ù‚Ø©')
                )
            );
        ELSE
            v_fx_gain_loss_acct := public.resolve_realized_fx_loss_account(v_company_id);
            IF v_fx_gain_loss_acct IS NULL THEN
                v_fx_gain_loss_acct := public.resolve_gl_account('6151', v_company_id);
            END IF;
            IF v_fx_gain_loss_acct IS NULL THEN
                v_fx_gain_loss_acct := public.resolve_gl_account('5220', v_company_id);
            END IF;

            v_je_id := public.post_journal_entry(
                'currency_exchange', v_desc, CURRENT_DATE, v_company_id, v_user_id,
                jsonb_build_array(
                    jsonb_build_object('account_id', v_to_acct, 'debit', p_amount_to, 'credit', 0, 'base_debit', p_amount_to, 'base_credit', 0, 'currency', UPPER(p_to_currency), 'description', v_desc),
                    jsonb_build_object('account_id', v_fx_gain_loss_acct, 'debit', ABS(v_realized_fx_diff), 'credit', 0, 'base_debit', ABS(v_realized_fx_diff), 'base_credit', 0, 'currency', 'EGP', 'description', 'Ø®Ø³Ø§Ø¦Ø± ÙØ±ÙˆÙ‚ Ø¹Ù…Ù„Ø© Ù…Ø­Ù‚Ù‚Ø©'),
                    jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount_from, 'base_debit', 0, 'base_credit', v_cost_base_released, 'currency', UPPER(p_from_currency), 'description', v_desc)
                )
            );
        END IF;
    ELSE
        v_je_id := public.post_journal_entry(
            'currency_exchange', v_desc, CURRENT_DATE, v_company_id, v_user_id,
            jsonb_build_array(
                jsonb_build_object('account_id', v_to_acct, 'debit', p_amount_to, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', UPPER(p_to_currency), 'description', v_desc),
                jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount_from, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', UPPER(p_from_currency), 'description', v_desc)
            )
        );
    END IF;

    -- Record outgoing transaction
    INSERT INTO public.treasury_transactions (
        treasury_id, type, amount, currency, description,
        balance_before, balance_after,
        created_by, exchange_rate, amount_in_base_currency, journal_entry_id
    ) VALUES (
        v_treasury_id, 'currency_exchange_out', p_amount_from, UPPER(p_from_currency),
        v_desc || ' (ØµØ§Ø¯Ø±)', v_balance_before_from, v_balance_after_from,
        v_user_id, p_exchange_rate, v_base_amount, v_je_id
    );

    -- Record incoming transaction
    INSERT INTO public.treasury_transactions (
        treasury_id, type, amount, currency, description,
        balance_before, balance_after,
        created_by, exchange_rate, amount_in_base_currency, journal_entry_id
    ) VALUES (
        v_treasury_id, 'currency_exchange_in', p_amount_to, UPPER(p_to_currency),
        v_desc || ' (ÙˆØ§Ø±Ø¯)', v_balance_before_to, v_balance_after_to,
        v_user_id, p_exchange_rate, v_base_amount, v_je_id
    );

    RETURN jsonb_build_object(
        'success', true,
        'journal_entry_id', v_je_id,
        'amount_from', p_amount_from,
        'from_currency', UPPER(p_from_currency),
        'amount_to', p_amount_to,
        'to_currency', UPPER(p_to_currency),
        'exchange_rate', p_exchange_rate
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.exchange_currency(text, text, text, numeric, numeric, numeric, uuid, text, text) TO authenticated, service_role, anon;

-- Overload for bigint treasury_id
CREATE OR REPLACE FUNCTION public.exchange_currency(
    p_treasury_id bigint,
    p_from_currency text,
    p_to_currency text,
    p_amount_from numeric,
    p_amount_to numeric,
    p_exchange_rate numeric,
    p_user_id uuid DEFAULT auth.uid(),
    p_transfer_mode text DEFAULT 'exchange',
    p_description text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    RETURN public.exchange_currency(
        p_treasury_id   := p_treasury_id::text,
        p_from_currency := p_from_currency,
        p_to_currency   := p_to_currency,
        p_amount_from   := p_amount_from,
        p_amount_to     := p_amount_to,
        p_exchange_rate := p_exchange_rate,
        p_user_id       := p_user_id,
        p_transfer_mode := p_transfer_mode,
        p_description   := p_description
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.exchange_currency(bigint, text, text, numeric, numeric, numeric, uuid, text, text) TO authenticated, service_role, anon;


-- ============================================================================
-- â”€â”€ Bank Account Draft & Confirm Workflow Support â”€â”€
-- ============================================================================

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'status'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN status TEXT NOT NULL DEFAULT 'confirmed';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'payload'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN payload JSONB DEFAULT '{}'::jsonb;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'source_type'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN source_type TEXT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'revenue_account_id'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN revenue_account_id BIGINT REFERENCES public.accounts(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'expense_account_id'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN expense_account_id BIGINT REFERENCES public.accounts(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'source_id'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN source_id TEXT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'category_id'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN category_id TEXT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'cost_center_id'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN cost_center_id TEXT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'reference_type'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN reference_type TEXT;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'bank_account_transactions' AND column_name = 'reference_id'
    ) THEN
        ALTER TABLE public.bank_account_transactions 
        ADD COLUMN reference_id TEXT;
    END IF;

    -- 3. Fix foreign currency bank accounts default book_rate
    UPDATE public.bank_accounts ba
    SET book_rate = COALESCE(
        (SELECT rate_to_egp FROM public.exchange_rates er WHERE er.currency_code = ba.currency LIMIT 1),
        CASE ba.currency WHEN 'USD' THEN 50.0 WHEN 'EUR' THEN 54.0 WHEN 'GBP' THEN 63.0 ELSE 50.0 END
    )
    WHERE ba.currency != 'EGP' AND (ba.book_rate <= 1.0 OR ba.book_rate IS NULL);
END $$;

-- â”€â”€ Soften fiscal-year trigger for 'draft' transactions (Treasury & Bank) â”€â”€
CREATE OR REPLACE FUNCTION public.check_fiscal_year_allows_financial()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  _fy_status text;
BEGIN
  IF TG_TABLE_NAME IN ('bank_account_transactions', 'treasury_transactions')
     AND NEW.status = 'draft' THEN
    RETURN NEW;
  END IF;

  SELECT fy.status INTO _fy_status
  FROM public.fiscal_years fy
  WHERE fy.is_current = true
    AND fy.deleted_at IS NULL
  LIMIT 1;

  IF _fy_status IN ('CLOSING', 'CLOSED') THEN
    RAISE EXCEPTION 'Ù„Ø§ ÙŠÙ…ÙƒÙ† Ø¥Ù†Ø´Ø§Ø¡ Ù…Ø³ØªÙ†Ø¯Ø§Øª Ù…Ø§Ù„ÙŠØ© ÙÙŠ Ø³Ù†Ø© Ù…Ø§Ù„ÙŠØ© %', _fy_status;
  END IF;

  RETURN NEW;
END;
$$;

-- â”€â”€ RPC: Save Bank Draft â”€â”€
CREATE OR REPLACE FUNCTION public.rpc_save_bank_draft(
    p_bank_account_id BIGINT,
    p_type TEXT,
    p_amount NUMERIC,
    p_description TEXT DEFAULT NULL,
    p_notes TEXT DEFAULT NULL,
    p_entity_type TEXT DEFAULT NULL,
    p_entity_id TEXT DEFAULT NULL,
    p_counterparty_name TEXT DEFAULT NULL,
    p_payload JSONB DEFAULT '{}'::jsonb
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_tx_id BIGINT;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Ø§Ù„Ù…Ø¨Ù„Øº ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† Ø£ÙƒØ¨Ø± Ù…Ù† ØµÙØ±';
    END IF;

    INSERT INTO public.bank_account_transactions (
        bank_account_id,
        type,
        amount,
        balance_before,
        balance_after,
        description,
        notes,
        entity_type,
        entity_id,
        counterparty_name,
        status,
        payload,
        created_by,
        created_at
    ) VALUES (
        p_bank_account_id,
        p_type,
        p_amount,
        0,
        0,
        p_description,
        p_notes,
        p_entity_type,
        p_entity_id,
        p_counterparty_name,
        'draft',
        COALESCE(p_payload, '{}'::jsonb),
        auth.uid(),
        NOW()
    )
    RETURNING id INTO v_tx_id;

    RETURN v_tx_id;
END;
$$;

-- â”€â”€ RPC: Update Bank Draft â”€â”€
CREATE OR REPLACE FUNCTION public.rpc_update_bank_draft(
    p_transaction_id BIGINT,
    p_bank_account_id BIGINT DEFAULT NULL,
    p_type TEXT DEFAULT NULL,
    p_amount NUMERIC DEFAULT NULL,
    p_description TEXT DEFAULT NULL,
    p_notes TEXT DEFAULT NULL,
    p_entity_type TEXT DEFAULT NULL,
    p_entity_id TEXT DEFAULT NULL,
    p_counterparty_name TEXT DEFAULT NULL,
    p_payload JSONB DEFAULT NULL
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
    UPDATE public.bank_account_transactions
    SET
        bank_account_id = COALESCE(p_bank_account_id, bank_account_id),
        type = COALESCE(p_type, type),
        amount = COALESCE(p_amount, amount),
        description = COALESCE(p_description, description),
        notes = p_notes,
        entity_type = p_entity_type,
        entity_id = p_entity_id,
        counterparty_name = p_counterparty_name,
        payload = CASE WHEN p_payload IS NOT NULL THEN p_payload ELSE payload END
    WHERE id = p_transaction_id AND status = 'draft';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ù„Ù… ÙŠØªÙ… Ø§Ù„Ø¹Ø«ÙˆØ± Ø¹Ù„Ù‰ Ø§Ù„Ù…Ø³ÙˆØ¯Ø© Ø£Ùˆ Ø£Ù†Ù‡Ø§ Ù…Ø¤ÙƒØ¯Ø© Ø¨Ø§Ù„ÙØ¹Ù„';
    END IF;

    RETURN TRUE;
END;
$$;

-- â”€â”€ RPC: Delete Bank Draft â”€â”€
CREATE OR REPLACE FUNCTION public.rpc_delete_bank_draft(
    p_transaction_id BIGINT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_deleted_count INT;
BEGIN
    DELETE FROM public.bank_account_transactions
    WHERE id = p_transaction_id AND status = 'draft';

    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    IF v_deleted_count = 0 THEN
        RAISE EXCEPTION 'Ù„Ù… ÙŠØªÙ… Ø§Ù„Ø¹Ø«ÙˆØ± Ø¹Ù„Ù‰ Ø§Ù„Ù…Ø³ÙˆØ¯Ø© Ø£Ùˆ ØªÙ… ØªØ£ÙƒÙŠØ¯Ù‡Ø§ Ù…Ø³Ø¨Ù‚Ø§Ù‹';
    END IF;

    RETURN TRUE;
END;
$$;

-- â”€â”€ Drop all existing overloads of exchange_bank_currency (Migration 377) â”€â”€
DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN (
        SELECT p.proname, pg_get_function_identity_arguments(p.oid) as args
        FROM pg_proc p
        JOIN pg_namespace n ON p.pronamespace = n.oid
        WHERE n.nspname = 'public' AND p.proname = 'exchange_bank_currency'
    ) LOOP
        EXECUTE 'DROP FUNCTION IF EXISTS public.' || quote_ident(r.proname) || '(' || r.args || ') CASCADE;';
    END LOOP;
END $$;

-- â”€â”€ Single Unified exchange_bank_currency (Migration 377) â”€â”€
CREATE OR REPLACE FUNCTION public.exchange_bank_currency(
    p_from_account_id integer,
    p_to_account_id integer,
    p_amount_from numeric,
    p_amount_to numeric,
    p_exchange_rate numeric
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_from_currency       TEXT;
    v_to_currency         TEXT;
    v_balance_before_from NUMERIC;
    v_balance_before_to   NUMERIC;
    v_balance_after_from  NUMERIC;
    v_balance_after_to    NUMERIC;
    
    v_cost_before_from    NUMERIC;
    v_rate_before_from    NUMERIC;
    v_cost_before_to      NUMERIC;
    v_rate_before_to      NUMERIC;
    
    v_new_cost_from       NUMERIC;
    v_new_rate_from       NUMERIC;
    v_new_cost_to         NUMERIC;
    v_new_rate_to         NUMERIC;
    
    v_cost_base_released  NUMERIC := 0;
    v_realized_fx_diff    NUMERIC := 0;
    v_base_amount         NUMERIC;
    
    v_from_acct           BIGINT;
    v_to_acct             BIGINT;
    v_fx_gain_loss_acct   BIGINT;
    v_je_id               BIGINT;
    v_desc                TEXT;
    v_company_id          UUID;
    v_user_id             UUID;
    v_transaction_id      BIGINT;
    v_result              JSONB;
BEGIN
    v_user_id := auth.uid();

    IF p_amount_from <= 0 OR p_amount_to <= 0 OR p_exchange_rate <= 0 THEN
        RAISE EXCEPTION 'Ø§Ù„Ù…Ø¨Ø§Ù„Øº ÙˆØ³Ø¹Ø± Ø§Ù„ØµØ±Ù ÙŠØ¬Ø¨ Ø£Ù† ØªÙƒÙˆÙ† Ø£ÙƒØ¨Ø± Ù…Ù† ØµÙØ±';
    END IF;

    -- 1. Lock from_account and fetch balances & cost base
    SELECT currency, COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0), company_id
    INTO v_from_currency, v_balance_before_from, v_cost_before_from, v_rate_before_from, v_company_id
    FROM public.bank_accounts
    WHERE id = p_from_account_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ø§Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„Ø¨Ù†ÙƒÙŠ Ø§Ù„Ù…ØµØ¯Ø± ØºÙŠØ± Ù…ÙˆØ¬ÙˆØ¯';
    END IF;

    IF v_balance_before_from < p_amount_from THEN
        RAISE EXCEPTION 'Ø§Ù„Ø±ØµÙŠØ¯ ØºÙŠØ± ÙƒØ§ÙÙ ÙÙŠ Ø§Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„Ø¨Ù†ÙƒÙŠ Ø§Ù„Ù…ØµØ¯Ø±. Ø§Ù„Ù…ØªÙˆÙØ±: %ØŒ Ø§Ù„Ù…Ø·Ù„ÙˆØ¨: %', v_balance_before_from, p_amount_from;
    END IF;

    -- 2. Lock to_account and fetch balances & cost base
    SELECT currency, COALESCE(balance, 0), COALESCE(cost_base, 0), COALESCE(book_rate, 1.0)
    INTO v_to_currency, v_balance_before_to, v_cost_before_to, v_rate_before_to
    FROM public.bank_accounts
    WHERE id = p_to_account_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ø§Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„Ø¨Ù†ÙƒÙŠ Ø§Ù„Ù…Ø­ÙˆÙ„ Ø¥Ù„ÙŠÙ‡ ØºÙŠØ± Ù…ÙˆØ¬ÙˆØ¯';
    END IF;

    IF v_company_id IS NULL THEN
        SELECT company_id INTO v_company_id FROM public.bank_accounts WHERE id = p_to_account_id;
        IF v_company_id IS NULL THEN
            SELECT id INTO v_company_id FROM public.sys_companies LIMIT 1;
        END IF;
    END IF;

    -- Strict Rule: One of the currencies MUST be EGP
    IF v_from_currency != 'EGP' AND v_to_currency != 'EGP' THEN
        RAISE EXCEPTION 'Ø§Ù„ØªØ­ÙˆÙŠÙ„ Ø§Ù„Ù…Ø¨Ø§Ø´Ø± Ø¨ÙŠÙ† Ø¹Ù…Ù„ØªÙŠÙ† Ø£Ø¬Ù†Ø¨ÙŠØªÙŠÙ† ØºÙŠØ± Ù…Ø³Ù…ÙˆØ­. ÙŠØ¬Ø¨ Ø§Ù„ØªØ­ÙˆÙŠÙ„ Ø¹Ø¨Ø± Ø§Ù„Ø¬Ù†ÙŠÙ‡ Ø§Ù„Ù…ØµØ±ÙŠ ÙƒØ®Ø·ÙˆØªÙŠÙ† Ù…Ù†ÙØµÙ„ØªÙŠÙ†.';
    END IF;

    -- Fallback for uninitialized cost base
    IF v_from_currency != 'EGP' AND (v_cost_before_from <= 0 OR v_rate_before_from <= 0) THEN
        v_rate_before_from := COALESCE(NULLIF(v_rate_before_from, 0), public.fn_get_exchange_rate(v_from_currency));
        IF v_rate_before_from <= 0 THEN v_rate_before_from := p_exchange_rate; END IF;
        v_cost_before_from := ROUND(v_balance_before_from * v_rate_before_from, 2);
    END IF;

    v_desc := 'ØªØ­ÙˆÙŠÙ„ Ø¨Ù†ÙƒÙŠ Ù…Ù† ' || v_from_currency || ' Ø¥Ù„Ù‰ ' || v_to_currency || ' Ø¨Ø³Ø¹Ø± ØµØ±Ù ' || p_exchange_rate;

    v_from_acct := public.resolve_gl_account(
        CASE v_from_currency WHEN 'EGP' THEN '11201' WHEN 'USD' THEN '11202' WHEN 'EUR' THEN '11203' WHEN 'GBP' THEN '11204' ELSE '11201' END,
        v_company_id
    );
    v_to_acct := public.resolve_gl_account(
        CASE v_to_currency WHEN 'EGP' THEN '11201' WHEN 'USD' THEN '11202' WHEN 'EUR' THEN '11203' WHEN 'GBP' THEN '11204' ELSE '11201' END,
        v_company_id
    );

    v_balance_after_from := v_balance_before_from - p_amount_from;
    v_balance_after_to := v_balance_before_to + p_amount_to;

    -- 3. IAS 21 Multi-Currency Cost Base & Realized FX Calculation
    IF v_from_currency != 'EGP' THEN
        -- Case A: Selling foreign currency (e.g. USD -> EGP)
        v_cost_base_released := ROUND(p_amount_from * v_rate_before_from, 2);
        v_new_cost_from := GREATEST(0, v_cost_before_from - v_cost_base_released);
        v_new_rate_from := CASE WHEN v_balance_after_from > 0 THEN ROUND(v_new_cost_from / v_balance_after_from, 4) ELSE v_rate_before_from END;

        v_new_cost_to := v_balance_after_to;
        v_new_rate_to := 1.0;
        v_realized_fx_diff := p_amount_to - v_cost_base_released;
    ELSE
        -- Case B: Buying foreign currency (e.g. EGP -> USD)
        v_new_cost_from := v_balance_after_from;
        v_new_rate_from := 1.0;

        v_new_cost_to := v_cost_before_to + p_amount_from;
        v_new_rate_to := CASE WHEN v_balance_after_to > 0 THEN ROUND(v_new_cost_to / v_balance_after_to, 4) ELSE p_exchange_rate END;
        v_realized_fx_diff := 0;
    END IF;

    -- Update Bank Accounts balances, cost_base, and book_rate
    UPDATE public.bank_accounts
    SET balance = v_balance_after_from,
        cost_base = v_new_cost_from,
        book_rate = v_new_rate_from,
        updated_at = NOW()
    WHERE id = p_from_account_id;

    UPDATE public.bank_accounts
    SET balance = v_balance_after_to,
        cost_base = v_new_cost_to,
        book_rate = v_new_rate_to,
        updated_at = NOW()
    WHERE id = p_to_account_id;

    -- Base Amount is the EGP amount
    IF v_from_currency = 'EGP' THEN
        v_base_amount := p_amount_from;
    ELSE
        v_base_amount := p_amount_to;
    END IF;

    -- 4. Post Balanced Journal Entry with Realized FX Gain/Loss
    IF v_realized_fx_diff != 0 THEN
        IF v_realized_fx_diff > 0 THEN
            v_fx_gain_loss_acct := public.resolve_gl_account('4310', v_company_id);
            v_je_id := public.post_journal_entry(
                'currency_exchange', v_desc, CURRENT_DATE, v_company_id, v_user_id,
                jsonb_build_array(
                    jsonb_build_object('account_id', v_to_acct, 'debit', p_amount_to, 'credit', 0, 'base_debit', p_amount_to, 'base_credit', 0, 'currency', v_to_currency, 'description', v_desc || ' (ÙˆØ§Ø±Ø¯)'),
                    jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount_from, 'base_debit', 0, 'base_credit', v_cost_base_released, 'currency', v_from_currency, 'description', v_desc || ' (ØµØ§Ø¯Ø± Ø¨Ø§Ù„ØªÙƒÙ„ÙØ© Ø§Ù„Ø¯ÙØªØ±ÙŠØ©)'),
                    jsonb_build_object('account_id', v_fx_gain_loss_acct, 'debit', 0, 'credit', v_realized_fx_diff, 'base_debit', 0, 'base_credit', v_realized_fx_diff, 'currency', 'EGP', 'description', 'Ø£Ø±Ø¨Ø§Ø­ ÙØ±ÙˆÙ‚ Ø¹Ù…Ù„Ø© Ù…Ø­Ù‚Ù‚Ø©')
                )
            );
        ELSE
            v_fx_gain_loss_acct := public.resolve_gl_account('6151', v_company_id);
            v_je_id := public.post_journal_entry(
                'currency_exchange', v_desc, CURRENT_DATE, v_company_id, v_user_id,
                jsonb_build_array(
                    jsonb_build_object('account_id', v_to_acct, 'debit', p_amount_to, 'credit', 0, 'base_debit', p_amount_to, 'base_credit', 0, 'currency', v_to_currency, 'description', v_desc || ' (ÙˆØ§Ø±Ø¯)'),
                    jsonb_build_object('account_id', v_fx_gain_loss_acct, 'debit', ABS(v_realized_fx_diff), 'credit', 0, 'base_debit', ABS(v_realized_fx_diff), 'base_credit', 0, 'currency', 'EGP', 'description', 'Ø®Ø³Ø§Ø¦Ø± ÙØ±ÙˆÙ‚ Ø¹Ù…Ù„Ø© Ù…Ø­Ù‚Ù‚Ø©'),
                    jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount_from, 'base_debit', 0, 'base_credit', v_cost_base_released, 'currency', v_from_currency, 'description', v_desc || ' (ØµØ§Ø¯Ø± Ø¨Ø§Ù„ØªÙƒÙ„ÙØ© Ø§Ù„Ø¯ÙØªØ±ÙŠØ©)')
                )
            );
        END IF;
    ELSE
        v_je_id := public.post_journal_entry(
            'currency_exchange', v_desc, CURRENT_DATE, v_company_id, v_user_id,
            jsonb_build_array(
                jsonb_build_object('account_id', v_to_acct, 'debit', p_amount_to, 'credit', 0, 'base_debit', v_base_amount, 'base_credit', 0, 'currency', v_to_currency, 'description', v_desc || ' (ÙˆØ§Ø±Ø¯)'),
                jsonb_build_object('account_id', v_from_acct, 'debit', 0, 'credit', p_amount_from, 'base_debit', 0, 'base_credit', v_base_amount, 'currency', v_from_currency, 'description', v_desc || ' (ØµØ§Ø¯Ø±)')
            )
        );
    END IF;

    -- 5. Insert Transaction Records
    INSERT INTO public.bank_account_transactions (
        bank_account_id, type, amount, balance_before, balance_after,
        description, entity_type, journal_entry_id,
        exchange_rate, amount_in_base_currency, currency_snapshot, status
    ) VALUES (
        p_from_account_id, 'currency_exchange_out', p_amount_from, v_balance_before_from, v_balance_after_from,
        v_desc || ' (ØµØ§Ø¯Ø±)', 'exchange', v_je_id,
        p_exchange_rate, CASE WHEN v_from_currency != 'EGP' THEN v_cost_base_released ELSE v_base_amount END,
        jsonb_build_object('currency', v_from_currency, 'exchange_rate', p_exchange_rate, 'book_rate', v_new_rate_from, 'amount', p_amount_from, 'amount_in_base_currency', CASE WHEN v_from_currency != 'EGP' THEN v_cost_base_released ELSE v_base_amount END),
        'confirmed'
    ) RETURNING id INTO v_transaction_id;

    INSERT INTO public.bank_account_transactions (
        bank_account_id, type, amount, balance_before, balance_after,
        description, entity_type, journal_entry_id,
        exchange_rate, amount_in_base_currency, currency_snapshot, status
    ) VALUES (
        p_to_account_id, 'currency_exchange_in', p_amount_to, v_balance_before_to, v_balance_after_to,
        v_desc || ' (ÙˆØ§Ø±Ø¯)', 'exchange', v_je_id,
        p_exchange_rate, v_base_amount,
        jsonb_build_object('currency', v_to_currency, 'exchange_rate', p_exchange_rate, 'book_rate', v_new_rate_to, 'amount', p_amount_to, 'amount_in_base_currency', v_base_amount),
        'confirmed'
    );

    v_result := jsonb_build_object(
        'success', true,
        'transaction_id', v_transaction_id,
        'journal_entry_id', v_je_id,
        'realized_fx_diff', v_realized_fx_diff
    );

    RETURN v_result;
END;
$$;

GRANT EXECUTE ON FUNCTION public.exchange_bank_currency(integer, integer, numeric, numeric, numeric) TO authenticated, anon, service_role;

-- â”€â”€ RPC: Confirm Bank Draft â”€â”€
CREATE OR REPLACE FUNCTION public.rpc_confirm_bank_draft(
    p_transaction_id BIGINT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_tx RECORD;
    v_res JSONB;
BEGIN
    SELECT * INTO v_tx
    FROM public.bank_account_transactions
    WHERE id = p_transaction_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ø§Ù„Ø­Ø±ÙƒØ© ØºÙŠØ± Ù…ÙˆØ¬ÙˆØ¯Ø©';
    END IF;

    IF v_tx.status != 'draft' THEN
        RAISE EXCEPTION 'Ù‡Ø°Ù‡ Ø§Ù„Ø­Ø±ÙƒØ© Ù…Ø¤ÙƒØ¯Ø© Ø¨Ø§Ù„ÙØ¹Ù„ ÙˆÙ„ÙŠØ³Øª Ù…Ø³ÙˆØ¯Ø©';
    END IF;

    IF v_tx.type = 'deposit' THEN
        v_res := public.deposit_bank_account(
            p_account_id        := v_tx.bank_account_id::bigint,
            p_amount            := v_tx.amount,
            p_description       := v_tx.description,
            p_revenue_account_id := COALESCE((v_tx.payload->>'revenue_account_id')::bigint, NULL),
            p_entity_type       := v_tx.entity_type,
            p_entity_id         := v_tx.entity_id,
            p_counterparty_name := v_tx.counterparty_name,
            p_source_type       := COALESCE(v_tx.payload->>'source_type', 'deposit'),
            p_notes             := v_tx.notes
        );

        DELETE FROM public.bank_account_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'ØªÙ… ØªØ£ÙƒÙŠØ¯ Ø§Ù„Ø¥ÙŠØ¯Ø§Ø¹ ÙˆØªØ±Ø­ÙŠÙ„ Ø§Ù„Ù‚ÙŠØ¯ Ø¨Ù†Ø¬Ø§Ø­', 'result', v_res);

    ELSIF v_tx.type = 'withdraw' THEN
        v_res := public.withdraw_bank_account(
            p_account_id        := v_tx.bank_account_id,
            p_amount            := v_tx.amount,
            p_description       := v_tx.description,
            p_entity_type       := v_tx.entity_type,
            p_entity_id         := v_tx.entity_id,
            p_counterparty_name := v_tx.counterparty_name,
            p_expense_account_id := COALESCE((v_tx.payload->>'expense_account_id')::integer, NULL),
            p_notes             := v_tx.notes,
            p_reference_type    := v_tx.payload->>'reference_type',
            p_reference_id      := v_tx.payload->>'reference_id'
        );

        DELETE FROM public.bank_account_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'ØªÙ… ØªØ£ÙƒÙŠØ¯ Ø§Ù„ØµØ±Ù ÙˆØªØ±Ø­ÙŠÙ„ Ø§Ù„Ù‚ÙŠØ¯ Ø¨Ù†Ø¬Ø§Ø­', 'result', v_res);

    ELSIF v_tx.type IN ('currency_exchange_out', 'currency_exchange_in', 'exchange') THEN
        v_res := public.exchange_bank_currency(
            p_from_account_id := v_tx.bank_account_id::integer,
            p_to_account_id   := (v_tx.payload->>'to_account_id')::integer,
            p_amount_from     := COALESCE((v_tx.payload->>'amount_from')::numeric, v_tx.amount),
            p_amount_to       := (v_tx.payload->>'amount_to')::numeric,
            p_exchange_rate   := (v_tx.payload->>'exchange_rate')::numeric
        );

        DELETE FROM public.bank_account_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'ØªÙ… ØªØ£ÙƒÙŠØ¯ ØªØ­ÙˆÙŠÙ„ Ø§Ù„Ø¹Ù…Ù„Ø© ÙˆØªØ±Ø­ÙŠÙ„ Ø§Ù„Ù‚ÙŠØ¯ Ø¨Ù†Ø¬Ø§Ø­', 'result', v_res);

    ELSIF v_tx.type = 'transfer' THEN
        PERFORM public.bank_transfer(
            p_from_account_id := v_tx.bank_account_id::integer,
            p_to_account_id   := (v_tx.payload->>'to_account_id')::integer,
            p_amount          := v_tx.amount,
            p_description     := v_tx.description,
            p_bank_fee        := COALESCE((v_tx.payload->>'bank_fee')::numeric, 0),
            p_notes           := v_tx.notes
        );

        DELETE FROM public.bank_account_transactions WHERE id = p_transaction_id;

        RETURN jsonb_build_object('success', true, 'message', 'ØªÙ… ØªØ£ÙƒÙŠØ¯ Ø§Ù„ØªØ­ÙˆÙŠÙ„ Ø§Ù„Ø¨Ù†ÙƒÙŠ ÙˆØªØ±Ø­ÙŠÙ„ Ø§Ù„Ù‚ÙŠØ¯ Ø¨Ù†Ø¬Ø§Ø­');

    ELSE
        RAISE EXCEPTION 'Ù†ÙˆØ¹ Ø§Ù„Ø­Ø±ÙƒØ© ØºÙŠØ± Ù…Ø¯Ø¹ÙˆÙ…: %', v_tx.type;
    END IF;
END;
$$;

-- â”€â”€ 7.5 Ensure all required columns exist on public.cheques â”€â”€
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'bank_account_id'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN bank_account_id INTEGER REFERENCES public.bank_accounts(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'journal_entry_id'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN journal_entry_id BIGINT REFERENCES public.journal_entries(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'expense_account_id'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN expense_account_id BIGINT REFERENCES public.accounts(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'exchange_rate'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN exchange_rate NUMERIC(15,6) DEFAULT 1.0;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'amount_in_base_currency'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN amount_in_base_currency NUMERIC(15,2);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'treasury_id'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN treasury_id BIGINT REFERENCES public.treasuries(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_schema = 'public' AND table_name = 'cheques' AND column_name = 'bank_transaction_id'
    ) THEN
        ALTER TABLE public.cheques ADD COLUMN bank_transaction_id BIGINT;
    END IF;
END $$;

-- â”€â”€ 7.4 Create Cheque RPC (Fixed shareholder_id UUID type) â”€â”€
DROP FUNCTION IF EXISTS public.create_cheque(text, text, numeric, text, date, date, text, bigint, text, uuid, bigint, bigint, bigint, integer);
DROP FUNCTION IF EXISTS public.create_cheque(character varying, character varying, numeric, character varying, date, character varying, bigint, uuid, bigint, bigint, uuid, text);
DROP FUNCTION IF EXISTS public.create_cheque(text, text, numeric, text, date, date, text, bigint, text, uuid, bigint, bigint, uuid, integer);
DROP FUNCTION IF EXISTS public.create_cheque(text, text, numeric, text, date, date, text, bigint, text, uuid, bigint, bigint, uuid, integer, bigint);
DROP FUNCTION IF EXISTS public.create_cheque(text, text, numeric, text, date, date, text, bigint, text, uuid, bigint, bigint, uuid, integer, bigint, boolean);

CREATE OR REPLACE FUNCTION public.create_cheque(
    p_cheque_number text,
    p_type text,
    p_amount numeric,
    p_currency text,
    p_issue_date date,
    p_due_date date,
    p_counterparty_type text DEFAULT NULL::text,
    p_counterparty_id bigint DEFAULT NULL::bigint,
    p_notes text DEFAULT NULL::text,
    p_supplier_id uuid DEFAULT NULL::uuid,
    p_clearing_agent_id bigint DEFAULT NULL::bigint,
    p_shipping_company_id bigint DEFAULT NULL::bigint,
    p_shareholder_id uuid DEFAULT NULL::uuid,
    p_category_id integer DEFAULT NULL::integer,
    p_expense_account_id bigint DEFAULT NULL::bigint,
    p_post_ledger boolean DEFAULT true
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_id BIGINT;
    v_je_id BIGINT := NULL;
    v_company_id UUID;
    v_rate NUMERIC;
    v_base_amount NUMERIC;
    v_norm_counterparty_type TEXT;
    v_counterparty_acct BIGINT;
    v_holding_acct BIGINT;
    v_je_lines JSONB := '[]'::jsonb;
    v_desc TEXT;
    v_counterparty_name TEXT;
BEGIN
    IF p_amount <= 0 THEN
        RAISE EXCEPTION 'Ø§Ù„Ù…Ø¨Ù„Øº ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† Ø£ÙƒØ¨Ø± Ù…Ù† ØµÙØ±';
    END IF;

    IF p_due_date < p_issue_date THEN
        RAISE EXCEPTION 'ØªØ§Ø±ÙŠØ® Ø§Ù„Ø§Ø³ØªØ­Ù‚Ø§Ù‚ ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† Ø¨Ø¹Ø¯ ØªØ§Ø±ÙŠØ® Ø§Ù„ØªØ­Ø±ÙŠØ±';
    END IF;

    -- Optional immediate Stage-1 ledger posting if requested
    IF p_post_ledger THEN
        SELECT id INTO v_company_id FROM public.sys_companies WHERE deleted_at IS NULL ORDER BY created_at ASC LIMIT 1;
        v_rate := public.fn_get_exchange_rate(p_currency);
        v_base_amount := ROUND(p_amount * v_rate, 2);
        v_norm_counterparty_type := LOWER(COALESCE(p_counterparty_type, ''));

        IF p_type = 'incoming' THEN
            v_holding_acct := public.resolve_gl_account('12121', v_company_id);

            IF v_norm_counterparty_type = 'customer' AND p_counterparty_id IS NOT NULL THEN
                SELECT account_id, name INTO v_counterparty_acct, v_counterparty_name FROM public.customers WHERE id = p_counterparty_id;
            ELSIF v_norm_counterparty_type = 'shareholder' AND p_shareholder_id IS NOT NULL THEN
                SELECT account_id, name INTO v_counterparty_acct, v_counterparty_name FROM public.shareholders WHERE id = p_shareholder_id;
            END IF;

            IF v_counterparty_acct IS NULL THEN
                v_counterparty_acct := public.resolve_gl_account('12511', v_company_id);
            END IF;

            IF v_norm_counterparty_type = 'customer' AND v_counterparty_name IS NOT NULL AND v_counterparty_name != '' THEN
                v_desc := 'Ø§Ø³ØªÙ„Ø§Ù… Ø´ÙŠÙƒ Ø¨Ø±Ø³Ù… Ø§Ù„ØªØ­ØµÙŠÙ„ Ø±Ù‚Ù… ' || p_cheque_number || ' Ù…Ù† Ø§Ù„Ø¹Ù…ÙŠÙ„ ' || v_counterparty_name || ' (Ø³Ø¯Ø§Ø¯ Ø­Ø³Ø§Ø¨ Ø§Ù„Ø¹Ù…ÙŠÙ„)';
            ELSE
                v_desc := 'Ø§Ø³ØªÙ„Ø§Ù… Ø´ÙŠÙƒ Ø¨Ø±Ø³Ù… Ø§Ù„ØªØ­ØµÙŠÙ„ Ø±Ù‚Ù…: ' || p_cheque_number;
            END IF;

            v_je_lines := jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_holding_acct,
                    'debit', p_amount,
                    'credit', 0,
                    'base_debit', v_base_amount,
                    'base_credit', 0,
                    'currency', p_currency,
                    'description', v_desc
                ),
                jsonb_build_object(
                    'account_id', v_counterparty_acct,
                    'debit', 0,
                    'credit', p_amount,
                    'base_debit', 0,
                    'base_credit', v_base_amount,
                    'currency', p_currency,
                    'description', v_desc
                )
            );

            v_je_id := public.post_journal_entry(
                'cheque_receipt',
                v_desc,
                p_issue_date,
                v_company_id,
                auth.uid(),
                v_je_lines,
                p_cheque_number
            );
        ELSIF p_type = 'outgoing' THEN
            v_desc := 'Ø¥ØµØ¯Ø§Ø± Ø´ÙŠÙƒ Ø£ÙˆØ±Ø§Ù‚ Ø¯ÙØ¹ Ø±Ù‚Ù…: ' || p_cheque_number;
            v_holding_acct := public.resolve_gl_account('21121', v_company_id);

            IF v_norm_counterparty_type = 'supplier' AND p_supplier_id IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.suppliers WHERE id = p_supplier_id;
            ELSIF v_norm_counterparty_type = 'shipping_company' AND (p_shipping_company_id IS NOT NULL OR p_counterparty_id IS NOT NULL) THEN
                SELECT account_id INTO v_counterparty_acct FROM public.shipping_companies WHERE id = COALESCE(p_shipping_company_id, p_counterparty_id);
            ELSIF v_norm_counterparty_type = 'clearing_agent' AND (p_clearing_agent_id IS NOT NULL OR p_counterparty_id IS NOT NULL) THEN
                SELECT account_id INTO v_counterparty_acct FROM public.clearing_agents WHERE id = COALESCE(p_clearing_agent_id, p_counterparty_id);
            ELSIF v_norm_counterparty_type = 'shareholder' AND p_shareholder_id IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.shareholders WHERE id = p_shareholder_id;
            ELSIF p_expense_account_id IS NOT NULL THEN
                v_counterparty_acct := p_expense_account_id;
            END IF;

            IF v_counterparty_acct IS NULL THEN
                v_counterparty_acct := public.resolve_gl_account('21113', v_company_id);
            END IF;

            v_je_lines := jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_counterparty_acct,
                    'debit', p_amount,
                    'credit', 0,
                    'base_debit', v_base_amount,
                    'base_credit', 0,
                    'currency', p_currency,
                    'description', v_desc || ' (ØªØ³ÙˆÙŠØ© Ù…Ø³ØªØ­Ù‚Ø§Øª)'
                ),
                jsonb_build_object(
                    'account_id', v_holding_acct,
                    'debit', 0,
                    'credit', p_amount,
                    'base_debit', 0,
                    'base_credit', v_base_amount,
                    'currency', p_currency,
                    'description', v_desc
                )
            );

            v_je_id := public.post_journal_entry(
                'cheque_issued',
                v_desc,
                p_issue_date,
                v_company_id,
                auth.uid(),
                v_je_lines,
                p_cheque_number
            );
        END IF;
    END IF;

    INSERT INTO public.cheques (
        cheque_number, type, status, amount, currency,
        issue_date, due_date, counterparty_type, counterparty_id,
        supplier_id, clearing_agent_id, shipping_company_id, shareholder_id, notes, created_by, category_id,
        expense_account_id, journal_entry_id
    ) VALUES (
        p_cheque_number, p_type, 'pending', p_amount, p_currency,
        p_issue_date, p_due_date, p_counterparty_type, p_counterparty_id,
        p_supplier_id, p_clearing_agent_id, p_shipping_company_id, p_shareholder_id, p_notes, auth.uid(), p_category_id,
        p_expense_account_id, v_je_id
    ) RETURNING id INTO v_id;

    RETURN jsonb_build_object('id', v_id, 'journal_entry_id', v_je_id);
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_cheque TO authenticated, anon, service_role;

-- â”€â”€ 7.4b Cancel Cheque RPC â”€â”€
CREATE OR REPLACE FUNCTION public.cancel_cheque(p_cheque_id bigint)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_cheque RECORD;
    v_rev_lines JSONB := '[]'::jsonb;
    v_rev_je_id BIGINT;
    v_holding_acct BIGINT;
    v_counterparty_acct BIGINT;
    v_norm_counterparty_type TEXT;
    v_rate NUMERIC;
    v_base_amount NUMERIC;
BEGIN
    SELECT * INTO v_cheque
    FROM public.cheques
    WHERE id = p_cheque_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ø§Ù„Ø´ÙŠÙƒ ØºÙŠØ± Ù…ÙˆØ¬ÙˆØ¯';
    END IF;

    IF v_cheque.status != 'pending' THEN
        RAISE EXCEPTION 'Ù„Ø§ ÙŠÙ…ÙƒÙ† Ø¥Ù„ØºØ§Ø¡ Ø´ÙŠÙƒ Ø¨Ø­Ø§Ù„Ø© %', v_cheque.status;
    END IF;

    -- If a journal entry was previously posted while pending, reverse it
    IF v_cheque.journal_entry_id IS NOT NULL THEN
        v_rate := public.fn_get_exchange_rate(v_cheque.currency);
        v_base_amount := ROUND(v_cheque.amount * v_rate, 2);
        v_norm_counterparty_type := LOWER(COALESCE(v_cheque.counterparty_type, ''));

        IF v_cheque.type = 'incoming' THEN
            v_holding_acct := public.resolve_gl_account('12121', v_cheque.company_id);

            IF v_norm_counterparty_type = 'customer' AND v_cheque.counterparty_id IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.customers WHERE id = v_cheque.counterparty_id;
            ELSIF v_norm_counterparty_type = 'shareholder' AND v_cheque.shareholder_id IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.shareholders WHERE id = v_cheque.shareholder_id;
            END IF;

            IF v_counterparty_acct IS NULL THEN
                v_counterparty_acct := public.resolve_gl_account('12511', v_cheque.company_id);
            END IF;

            -- Reversal: Dr Customer / Cr 12121
            v_rev_lines := jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_counterparty_acct,
                    'debit', v_cheque.amount,
                    'credit', 0,
                    'base_debit', v_base_amount,
                    'base_credit', 0,
                    'currency', v_cheque.currency,
                    'description', 'Ø¥Ù„ØºØ§Ø¡ Ø´ÙŠÙƒ ÙˆØ§Ø±Ø¯ Ø¨Ø±Ø³Ù… Ø§Ù„ØªØ­ØµÙŠÙ„ Ø±Ù‚Ù…: ' || v_cheque.cheque_number
                ),
                jsonb_build_object(
                    'account_id', v_holding_acct,
                    'debit', 0,
                    'credit', v_cheque.amount,
                    'base_debit', 0,
                    'base_credit', v_base_amount,
                    'currency', v_cheque.currency,
                    'description', 'Ø¥Ù„ØºØ§Ø¡ Ø´ÙŠÙƒ ÙˆØ§Ø±Ø¯ Ø¨Ø±Ø³Ù… Ø§Ù„ØªØ­ØµÙŠÙ„ Ø±Ù‚Ù…: ' || v_cheque.cheque_number
                )
            );
        ELSE
            v_holding_acct := public.resolve_gl_account('21121', v_cheque.company_id);

            IF v_norm_counterparty_type = 'supplier' AND v_cheque.supplier_id IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.suppliers WHERE id = v_cheque.supplier_id;
            ELSIF v_norm_counterparty_type = 'shipping_company' AND COALESCE(v_cheque.shipping_company_id, v_cheque.counterparty_id) IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.shipping_companies WHERE id = COALESCE(v_cheque.shipping_company_id, v_cheque.counterparty_id)::bigint;
            ELSIF v_norm_counterparty_type = 'clearing_agent' AND COALESCE(v_cheque.clearing_agent_id, v_cheque.counterparty_id) IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.clearing_agents WHERE id = COALESCE(v_cheque.clearing_agent_id, v_cheque.counterparty_id)::bigint;
            ELSIF v_norm_counterparty_type = 'shareholder' AND v_cheque.shareholder_id IS NOT NULL THEN
                SELECT account_id INTO v_counterparty_acct FROM public.shareholders WHERE id = v_cheque.shareholder_id;
            ELSIF v_cheque.expense_account_id IS NOT NULL THEN
                v_counterparty_acct := v_cheque.expense_account_id;
            END IF;

            IF v_counterparty_acct IS NULL THEN
                v_counterparty_acct := public.resolve_gl_account('21113', v_cheque.company_id);
            END IF;

            -- Reversal: Dr 21121 / Cr Supplier
            v_rev_lines := jsonb_build_array(
                jsonb_build_object(
                    'account_id', v_holding_acct,
                    'debit', v_cheque.amount,
                    'credit', 0,
                    'base_debit', v_base_amount,
                    'base_credit', 0,
                    'currency', v_cheque.currency,
                    'description', 'Ø¥Ù„ØºØ§Ø¡ Ø´ÙŠÙƒ Ø£ÙˆØ±Ø§Ù‚ Ø¯ÙØ¹ Ø±Ù‚Ù…: ' || v_cheque.cheque_number
                ),
                jsonb_build_object(
                    'account_id', v_counterparty_acct,
                    'debit', 0,
                    'credit', v_cheque.amount,
                    'base_debit', 0,
                    'base_credit', v_base_amount,
                    'currency', v_cheque.currency,
                    'description', 'Ø¥Ù„ØºØ§Ø¡ Ø´ÙŠÙƒ Ø£ÙˆØ±Ø§Ù‚ Ø¯ÙØ¹ Ø±Ù‚Ù…: ' || v_cheque.cheque_number
                )
            );
        END IF;

        v_rev_je_id := public.post_journal_entry(
            'cheque_cancelled',
            'Ø¥Ù„ØºØ§Ø¡ Ø´ÙŠÙƒ Ø±Ù‚Ù…: ' || v_cheque.cheque_number,
            CURRENT_DATE,
            v_cheque.company_id,
            auth.uid(),
            v_rev_lines,
            p_cheque_id::TEXT
        );
    END IF;

    UPDATE public.cheques
    SET status = 'cancelled', cancelled_at = NOW()
    WHERE id = p_cheque_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.cancel_cheque(bigint) TO authenticated, anon, service_role;

-- â”€â”€ 7.5 Unified clear_cheque with Cheques Under Collection (12121) & Notes Payable (21121) â”€â”€
CREATE OR REPLACE FUNCTION public.clear_cheque(p_cheque_id bigint)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_cheque RECORD;
    v_desc TEXT;
    v_bank_id INTEGER;
    v_bank_bal NUMERIC;
    v_current_cost_base NUMERIC := 0;
    v_current_book_rate NUMERIC := 1.0;
    v_new_cost_base NUMERIC := 0;
    v_new_book_rate NUMERIC := 1.0;
    v_cost_released NUMERIC := 0;
    v_currency TEXT;
    v_company_id UUID;
    v_new_bank_bal NUMERIC;
    v_bank_acct BIGINT;
    v_counterparty_acct BIGINT;
    v_realized_gain_acct BIGINT;
    v_realized_loss_acct BIGINT;
    v_je_id BIGINT;
    v_stage1_je_id BIGINT;
    v_stage1_je_lines JSONB := '[]'::jsonb;
    v_bank_tx_id BIGINT;
    v_rate NUMERIC := 1.0;
    v_counterparty_name TEXT;
    v_base_amount NUMERIC;
    v_book_rate NUMERIC := 1.0;
    v_snapshot JSONB;
    v_entity_id TEXT;
    v_norm_counterparty_type TEXT;
    v_je_lines JSONB := '[]'::jsonb;
    v_treasury_id BIGINT;
    v_tr_bal NUMERIC := 0;
    v_tr_cost_base NUMERIC := 0;
    v_tr_book_rate NUMERIC := 1.0;
    v_new_tr_bal NUMERIC := 0;
    v_new_tr_cost_base NUMERIC := 0;
    v_new_tr_book_rate NUMERIC := 1.0;
    v_cheques_under_collection_acct BIGINT;
    v_notes_payable_acct BIGINT;

    -- Liability matching & FX calculation variables
    v_total_ap_base   NUMERIC := 0.0;
    v_total_gain      NUMERIC := 0.0;
    v_total_loss      NUMERIC := 0.0;
    v_remaining_alloc NUMERIC;
    v_alloc           NUMERIC;
    v_inv_rate        NUMERIC;
    v_inv_base        NUMERIC;
    v_paid_base       NUMERIC;
    v_diff            NUMERIC;
    v_liab            RECORD;
    v_shipment        RECORD;
    v_spec_shipment   RECORD;
    v_total_cust_base NUMERIC;
    v_alloc_bank_base NUMERIC;
    v_alloc_cust_base NUMERIC;
BEGIN
    SELECT * INTO v_cheque
    FROM public.cheques
    WHERE id = p_cheque_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ø§Ù„Ø´ÙŠÙƒ ØºÙŠØ± Ù…ÙˆØ¬ÙˆØ¯';
    END IF;

    IF v_cheque.status != 'pending' THEN
        RAISE EXCEPTION 'Ù„Ø§ ÙŠÙ…ÙƒÙ† ØªØ³ÙˆÙŠØ© Ø´ÙŠÙƒ Ø¨Ø­Ø§Ù„Ø© %', v_cheque.status;
    END IF;

    v_currency := v_cheque.currency;
    v_rate := public.fn_get_exchange_rate(v_currency);
    v_base_amount := ROUND(v_cheque.amount * v_rate, 2);
    v_norm_counterparty_type := LOWER(COALESCE(v_cheque.counterparty_type, ''));

    IF v_norm_counterparty_type = 'customer' AND v_cheque.counterparty_id IS NOT NULL THEN
        SELECT name INTO v_counterparty_name FROM public.customers WHERE id = v_cheque.counterparty_id;
    END IF;

    IF v_cheque.type = 'outgoing' THEN
        v_desc := 'ØµØ±Ù Ø´ÙŠÙƒ Ø±Ù‚Ù…: ' || v_cheque.cheque_number;
    ELSE
        IF v_norm_counterparty_type = 'customer' AND v_counterparty_name IS NOT NULL AND v_counterparty_name != '' THEN
            v_desc := 'ØªØ­ØµÙŠÙ„ Ø´ÙŠÙƒ Ø±Ù‚Ù… ' || v_cheque.cheque_number || ' Ù…Ù† Ø§Ù„Ø¹Ù…ÙŠÙ„ ' || v_counterparty_name || ' (Ø³Ø¯Ø§Ø¯ Ø­Ø³Ø§Ø¨ Ø§Ù„Ø¹Ù…ÙŠÙ„)';
        ELSE
            v_desc := 'ØªØ­ØµÙŠÙ„ Ø´ÙŠÙƒ Ø±Ù‚Ù…: ' || v_cheque.cheque_number;
        END IF;
    END IF;

    -- Get bank account (use cheque's assigned bank if present, otherwise match currency)
    IF v_cheque.bank_account_id IS NOT NULL THEN
        SELECT id, balance, COALESCE(cost_base, 0), COALESCE(book_rate, 1.0), ba.company_id, ba.account_id
        INTO v_bank_id, v_bank_bal, v_current_cost_base, v_current_book_rate, v_company_id, v_bank_acct
        FROM public.bank_accounts ba
        WHERE ba.id = v_cheque.bank_account_id
        FOR UPDATE;
    ELSE
        SELECT id, balance, COALESCE(cost_base, 0), COALESCE(book_rate, 1.0), ba.company_id, ba.account_id
        INTO v_bank_id, v_bank_bal, v_current_cost_base, v_current_book_rate, v_company_id, v_bank_acct
        FROM public.bank_accounts ba
        WHERE ba.currency = v_currency AND ba.deleted_at IS NULL
        ORDER BY ba.id ASC
        LIMIT 1
        FOR UPDATE;
    END IF;

    IF v_bank_id IS NULL THEN
        RAISE EXCEPTION 'Ù„Ù… ÙŠØªÙ… Ø§Ù„Ø¹Ø«ÙˆØ± Ø¹Ù„Ù‰ Ø­Ø³Ø§Ø¨ Ø¨Ù†ÙƒÙŠ Ø¨Ø¹Ù…Ù„Ø© %', v_currency;
    END IF;

    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM public.sys_companies LIMIT 1;
    END IF;

    -- Resolve Bank GL Account if ba.account_id is null
    IF v_bank_acct IS NULL THEN
        v_bank_acct := public.resolve_gl_account(
            CASE v_currency WHEN 'EGP' THEN '12111' WHEN 'USD' THEN '12112' WHEN 'EUR' THEN '12113' WHEN 'GBP' THEN '12114' ELSE '12111' END,
            v_company_id
        );
    END IF;

    -- Resolve Cheques Under Collection (12121) and Notes Payable (21121)
    v_cheques_under_collection_acct := public.resolve_gl_account('12121', v_company_id);
    v_notes_payable_acct := public.resolve_gl_account('21121', v_company_id);

    -- ================================================================
    -- 1. OUTGOING CHEQUE: Notes Payable (21121) Transition & Bank Withdrawal
    -- ================================================================
    IF v_cheque.type = 'outgoing' THEN
        IF v_bank_bal < v_cheque.amount THEN
            RAISE EXCEPTION 'Ø±ØµÙŠØ¯ Ø§Ù„Ø­Ø³Ø§Ø¨ Ø§Ù„Ø¨Ù†ÙƒÙŠ ØºÙŠØ± ÙƒØ§ÙÙ. Ø§Ù„Ø±ØµÙŠØ¯ Ø§Ù„Ø­Ø§Ù„ÙŠ: %', v_bank_bal;
        END IF;

        IF v_currency = 'EGP' THEN
            v_book_rate := 1.0;
            v_cost_released := v_cheque.amount;
            v_new_cost_base := GREATEST(0, v_current_cost_base - v_cheque.amount);
            v_new_book_rate := 1.0;
        ELSE
            v_book_rate := COALESCE(NULLIF(v_current_book_rate, 0), v_rate);
            v_cost_released := ROUND(v_cheque.amount * v_book_rate, 2);
            v_new_cost_base := GREATEST(0, v_current_cost_base - v_cost_released);
        END IF;

        v_new_bank_bal := v_bank_bal - v_cheque.amount;

        IF v_new_bank_bal > 0 AND v_currency != 'EGP' THEN
            v_new_book_rate := ROUND(v_new_cost_base / v_new_bank_bal, 4);
        ELSIF v_currency = 'EGP' THEN
            v_new_book_rate := 1.0;
        ELSE
            v_new_book_rate := v_book_rate;
            v_new_cost_base := 0;
        END IF;

        v_counterparty_acct := NULL;
        v_entity_id := NULL;
        v_treasury_id := NULL;

        IF v_norm_counterparty_type = 'supplier' AND v_cheque.supplier_id IS NOT NULL THEN
            v_entity_id := v_cheque.supplier_id::text;
            SELECT account_id INTO v_counterparty_acct FROM public.suppliers WHERE id = v_cheque.supplier_id;
        ELSIF v_norm_counterparty_type = 'shipping_company' AND COALESCE(v_cheque.shipping_company_id, v_cheque.counterparty_id) IS NOT NULL THEN
            v_entity_id := COALESCE(v_cheque.shipping_company_id, v_cheque.counterparty_id)::text;
            SELECT account_id INTO v_counterparty_acct FROM public.shipping_companies WHERE id = v_entity_id::bigint;
        ELSIF v_norm_counterparty_type = 'clearing_agent' AND COALESCE(v_cheque.clearing_agent_id, v_cheque.counterparty_id) IS NOT NULL THEN
            v_entity_id := COALESCE(v_cheque.clearing_agent_id, v_cheque.counterparty_id)::text;
            SELECT account_id INTO v_counterparty_acct FROM public.clearing_agents WHERE id = v_entity_id::bigint;
        ELSIF v_norm_counterparty_type = 'customer' AND v_cheque.counterparty_id IS NOT NULL THEN
            v_entity_id := v_cheque.counterparty_id::text;
            SELECT account_id INTO v_counterparty_acct FROM public.customers WHERE id = v_cheque.counterparty_id;
        ELSIF v_norm_counterparty_type = 'shareholder' AND v_cheque.shareholder_id IS NOT NULL THEN
            v_entity_id := v_cheque.shareholder_id::text;
            SELECT account_id INTO v_counterparty_acct FROM public.shareholders WHERE id = v_cheque.shareholder_id;
        ELSIF v_norm_counterparty_type = 'treasury' OR v_cheque.treasury_id IS NOT NULL THEN
            v_treasury_id := COALESCE(v_cheque.treasury_id, v_cheque.counterparty_id::bigint);
            v_entity_id := v_treasury_id::text;
            v_counterparty_acct := public.resolve_treasury_account(v_treasury_id::integer, v_currency, v_company_id);
        ELSIF v_cheque.expense_account_id IS NOT NULL THEN
            v_counterparty_acct := v_cheque.expense_account_id;
        END IF;

        IF v_counterparty_acct IS NULL THEN
            IF v_norm_counterparty_type = 'supplier' THEN
                v_counterparty_acct := public.resolve_gl_account('21113', v_company_id);
            ELSIF v_norm_counterparty_type = 'shipping_company' THEN
                v_counterparty_acct := public.resolve_gl_account('21115', v_company_id);
            ELSIF v_norm_counterparty_type = 'clearing_agent' THEN
                v_counterparty_acct := public.resolve_gl_account('21116', v_company_id);
            ELSE
                v_counterparty_acct := public.resolve_gl_account('21121', v_company_id);
            END IF;
        END IF;

        -- Multi-liability allocation and FX Calculation for Supplier / Shipping Company / Clearing Agent
        v_remaining_alloc := v_cheque.amount;
        v_total_ap_base := 0.0;
        v_total_gain := 0.0;
        v_total_loss := 0.0;

