                    UPDATE public.purchase_invoices
                    SET paid_amount = COALESCE(paid_amount, 0) + v_alloc,
                        payment_status = CASE WHEN (COALESCE(paid_amount, 0) + v_alloc) >= (COALESCE(total_amount, 0) - COALESCE(discount_amount, 0) - 0.001) THEN 'paid' ELSE 'partial' END,
                        payment_bank_account_id = v_bank_id,
