-- Validation Trigger for Strict Numerical Range Segregation across Suppliers
CREATE OR REPLACE FUNCTION public.trg_fn_validate_supplier_category_code_range()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_code_num INTEGER;
BEGIN
  IF NEW.code ~ '^[0-9]+$' THEN
    v_code_num := NEW.code::INTEGER;
    -- Preserve existing legacy codes (< 1000) safely
    IF v_code_num < 1000 THEN
      RETURN NEW;
    END IF;
  ELSE
    RETURN NEW;
  END IF;

  CASE NEW.supplier_type
    WHEN 'crop' THEN
      IF v_code_num < 50000 OR v_code_num > 59999 THEN
        RAISE EXCEPTION 'ÙƒÙˆØ¯ Ù…ÙˆØ±Ø¯ Ø§Ù„Ù…Ø­Ø§ØµÙŠÙ„ ØºÙŠØ± ØµØ§Ù„Ø­: (%) ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† Ø¨ÙŠÙ† 50000 Ùˆ 59999 (Ø³Ø¹Ø©: 10000 Ø³Ø¬Ù„)', NEW.code;
      END IF;

    WHEN 'transport' THEN
      IF v_code_num < 60000 OR v_code_num > 69999 THEN
        RAISE EXCEPTION 'ÙƒÙˆØ¯ Ù…ÙˆØ±Ø¯ Ø§Ù„Ù†Ù‚Ù„ ØºÙŠØ± ØµØ§Ù„Ø­: (%) ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† Ø¨ÙŠÙ† 60000 Ùˆ 69999 (Ø³Ø¹Ø©: 10000 Ø³Ø¬Ù„)', NEW.code;
      END IF;

    WHEN 'packaging' THEN
      IF v_code_num < 70000 OR v_code_num > 74999 THEN
        RAISE EXCEPTION 'ÙƒÙˆØ¯ Ù…ÙˆØ±Ø¯ Ù…ÙˆØ§Ø¯ Ø§Ù„ØªØ¹Ø¨Ø¦Ø© ÙˆØ§Ù„ØªØºÙ„ÙŠÙ ØºÙŠØ± ØµØ§Ù„Ø­: (%) ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† Ø¨ÙŠÙ† 70000 Ùˆ 74999 (Ø³Ø¹Ø©: 5000 Ø³Ø¬Ù„)', NEW.code;
      END IF;

    WHEN 'shared' THEN
      IF v_code_num < 75000 OR v_code_num > 79999 THEN
        RAISE EXCEPTION 'ÙƒÙˆØ¯ Ø§Ù„Ù…ÙˆØ±Ø¯ Ø§Ù„Ù…Ø´ØªØ±Ùƒ ØºÙŠØ± ØµØ§Ù„Ø­: (%) ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† ÙÙŠ Ø§Ù„Ù†Ø·Ø§Ù‚ 75000 Ø¥Ù„Ù‰ 79999 Ù„Ù…Ù†Ø¹ Ø§Ù„ØªØ¯Ø§Ø®Ù„ (Ø³Ø¹Ø©: 5000 Ø³Ø¬Ù„)', NEW.code;
      END IF;

    WHEN 'station' THEN
      IF v_code_num < 85000 OR v_code_num > 89999 THEN
        RAISE EXCEPTION 'ÙƒÙˆØ¯ Ù…ÙˆØ±Ø¯ Ø§Ù„Ù…Ø­Ø·Ø© ØºÙŠØ± ØµØ§Ù„Ø­: (%) ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† ÙÙŠ Ø§Ù„Ù†Ø·Ø§Ù‚ 85000 Ø¥Ù„Ù‰ 89999 (Ø³Ø¹Ø©: 5000 Ø³Ø¬Ù„)', NEW.code;
      END IF;

    WHEN 'deduction', 'deductions' THEN
      IF v_code_num < 40000 OR v_code_num > 49999 THEN
        RAISE EXCEPTION 'ÙƒÙˆØ¯ Ù…ÙˆØ±Ø¯ Ø§Ù„ØªØ®ØµÙŠÙ…Ø§Øª ØºÙŠØ± ØµØ§Ù„Ø­: (%) ÙŠØ¬Ø¨ Ø£Ù† ÙŠÙƒÙˆÙ† ÙÙŠ Ø§Ù„Ù†Ø·Ø§Ù‚ 40000 Ø¥Ù„Ù‰ 49999 (Ø³Ø¹Ø©: 10000 Ø³Ø¬Ù„)', NEW.code;
      END IF;

    ELSE
      -- Default allow other types
  END CASE;

  RETURN NEW;
END;
$$;

