-- Unified Entity Multi-Payment Function, Document Types & Timezone Engine
-- ============================================================================
INSERT INTO public.sys_document_types (code, name, prefix, is_active)
VALUES 
  ('treasury_multi_payment', 'Treasury Multi-Payment / Ø³Ø¯Ø§Ø¯ Ù…ØªØ¹Ø¯Ø¯ Ù…Ù† Ø§Ù„Ø®Ø²ÙŠÙ†Ø©', 'TMPY', true),
  ('bank_multi_payment',     'Bank Multi-Payment / Ø³Ø¯Ø§Ø¯ Ù…ØªØ¹Ø¯Ø¯ Ù…Ù† Ø§Ù„Ø¨Ù†Ùƒ',         'BMPY', true)
ON CONFLICT (code) DO UPDATE SET 
  prefix = EXCLUDED.prefix,
