-- â”€â”€ 1. Document Types Registration â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

INSERT INTO public.sys_document_types (code, name, prefix, is_active)

VALUES 

  ('lot_receipt',          'Crop Purchase / Ø´Ø±Ø§Ø¡ Ù…Ø­ØµÙˆÙ„',          'LOT', true),

  ('lot_price_adjustment', 'Crop Price Adjustment / ØªØ¹Ø¯ÙŠÙ„ Ø³Ø¹Ø± Ù…Ø­ØµÙˆÙ„', 'ADJ', true)

ON CONFLICT (code) DO UPDATE SET 

