        'description', 'Ù…Ø³ØªØ­Ù‚Ø§Øª Ù…ÙˆØ±Ø¯: ' || COALESCE(v_supplier_name, '') || ' - ÙØ§ØªÙˆØ±Ø© ' || COALESCE(v_purchase.invoice_number, '') ||

                       CASE WHEN v_items_summary <> '' THEN ' [' || v_items_summary || ']' ELSE '' END

