        || ' - ' || v_formula_desc

        || ' - Ù„ÙˆØ·: ' || COALESCE(v_lot.lot_number, p_lot_id::TEXT);



      -- â”€â”€ Resolve Crop Inventory Account (12412 primary - Ù…Ø®Ø²Ù† Ù…Ø´ØªØ±ÙŠØ§Øª Ø®Ø§Ù…) â”€â”€

      SELECT a.id INTO v_inventory_account_id

      FROM accounts a

      WHERE a.account_code = '12412' AND a.is_leaf = true AND a.deleted_at IS NULL

      LIMIT 1;



      IF v_inventory_account_id IS NULL THEN

        SELECT a.id INTO v_inventory_account_id

        FROM accounts a

        WHERE a.account_code = '1241' AND a.deleted_at IS NULL

        LIMIT 1;

      END IF;



      IF v_inventory_account_id IS NULL THEN

        SELECT a.id INTO v_inventory_account_id

