        END IF;

      END IF;



    END IF;

  END IF;

END;

$$;



-- â”€â”€ Backfill: Update existing crop journal entry descriptions to granular format â”€â”€

-- This updates all existing lot_receipt journal entries and their ledger lines

DO $$

DECLARE

  r RECORD;

  v_lot RECORD;

  v_supplier_name TEXT;

  v_product_name TEXT;

  v_currency_symbol TEXT;

  v_qty_desc TEXT;

  v_unit_price_desc TEXT;

  v_debit_desc TEXT;

  v_credit_desc TEXT;

  v_header_desc TEXT;

  v_exchange_rate NUMERIC;

  v_total_cost NUMERIC;

  v_lot_currency TEXT;

  v_inventory_account_id BIGINT;

  v_supplier_account_id BIGINT;

  v_formula_desc TEXT;

  v_effective_weight NUMERIC;

BEGIN

  -- Resolve inventory account (12412 Raw Crop Inventory - Ù…Ø®Ø²Ù† Ù…Ø´ØªØ±ÙŠØ§Øª Ø®Ø§Ù…)

  SELECT a.id INTO v_inventory_account_id

  FROM accounts a

  WHERE a.account_code = '12412' AND a.is_leaf = true AND a.deleted_at IS NULL

  LIMIT 1;



  IF v_inventory_account_id IS NULL THEN

    SELECT a.id INTO v_inventory_account_id

    FROM accounts a

    WHERE a.account_code = '1241' AND a.deleted_at IS NULL

    LIMIT 1;

  END IF;



  IF v_inventory_account_id IS NULL THEN

    SELECT a.id INTO v_inventory_account_id

    FROM accounts a

    WHERE a.account_code LIKE '124%' AND a.is_leaf = true AND a.deleted_at IS NULL

    ORDER BY a.account_code ASC

    LIMIT 1;

  END IF;



  IF v_inventory_account_id IS NULL THEN

    SELECT a.id INTO v_inventory_account_id

    FROM accounts a

    WHERE a.account_code = '1030' AND a.deleted_at IS NULL

    LIMIT 1;

  END IF;



  IF v_inventory_account_id IS NULL THEN

    RAISE NOTICE 'Skipping backfill: no inventory account found';

    RETURN;

  END IF;



  FOR r IN

    SELECT je.id AS je_id, je.source_id

    FROM journal_entries je

    WHERE je.source_type = 'lot_receipt'

      AND je.deleted_at IS NULL

  LOOP

    SELECT * INTO v_lot FROM lot_receipts WHERE id::TEXT = r.source_id;

    IF NOT FOUND THEN CONTINUE; END IF;



    v_product_name := COALESCE(v_lot.product_name, 'Ù…Ø­ØµÙˆÙ„');

    v_lot_currency := COALESCE(NULLIF(v_lot.currency, ''), 'EGP');

    v_exchange_rate := COALESCE(NULLIF(v_lot.exchange_rate, 0), 1.0);

    v_total_cost := COALESCE(v_lot.total_fruit_cost, 0);



    SELECT name INTO v_supplier_name FROM suppliers WHERE id = v_lot.supplier_id;



    v_currency_symbol := CASE UPPER(v_lot_currency)

      WHEN 'EGP' THEN 'Ø¬.Ù…'

      WHEN 'USD' THEN '$'

      WHEN 'EUR' THEN 'â‚¬'

      WHEN 'GBP' THEN 'Â£'

      ELSE v_lot_currency

    END;



    IF COALESCE(v_lot.purchase_mode, 'weight') = 'carton' THEN

      v_qty_desc := COALESCE(v_lot.carton_count, 0)::TEXT || ' ÙƒØ±ØªÙˆÙ†Ø©';

      IF COALESCE(v_lot.price_per_carton, 0) > 0 THEN

        v_unit_price_desc := ROUND(v_lot.price_per_carton::NUMERIC, 2)::TEXT || ' ' || v_currency_symbol || '/ÙƒØ±ØªÙˆÙ†Ø©';

      ELSE

        v_unit_price_desc := '';

      END IF;

      -- Formula strictly cartons: e.g. 1000 ÙƒØ±ØªÙˆÙ†Ø© Ã— 2.00 $ = 2,000.00 $

      v_formula_desc := COALESCE(v_lot.carton_count, 0)::TEXT || ' ÙƒØ±ØªÙˆÙ†Ø© Ã— '

        || CASE 

             WHEN COALESCE(v_lot.price_per_carton, 0) > 0 THEN ROUND(v_lot.price_per_carton::NUMERIC, 2)::TEXT

             WHEN COALESCE(v_lot.carton_count, 0) > 0 THEN ROUND((v_total_cost / v_lot.carton_count)::NUMERIC, 2)::TEXT

             ELSE '0.00'

           END

        || ' ' || v_currency_symbol

        || ' = ' || ROUND(v_total_cost::NUMERIC, 2)::TEXT || ' ' || v_currency_symbol;

    ELSE

      -- Weight mode: Total Amount = Net Weight (Ø§Ù„ÙˆØ²Ù† Ø§Ù„ØµØ§ÙÙŠ) Ã— Price per Unit/Kg (Ø³Ø¹Ø± Ø§Ù„ÙƒÙŠÙ„Ùˆ)

      v_effective_weight := CASE 

        WHEN COALESCE(v_lot.net_weight_kg, 0) > 0 THEN v_lot.net_weight_kg 

        ELSE COALESCE(v_lot.gross_weight_kg, 0) 

      END;

      v_qty_desc := ROUND(v_effective_weight::NUMERIC, 2)::TEXT || ' ÙƒØ¬Ù… (ØµØ§ÙÙŠ)';

      IF v_effective_weight > 0 THEN

        v_unit_price_desc := ROUND((v_total_cost / v_effective_weight)::NUMERIC, 2)::TEXT || ' ' || v_currency_symbol || '/ÙƒØ¬Ù…';

      ELSE

        v_unit_price_desc := '';

      END IF;

      -- Formula: e.g. 500.00 ÙƒØ¬Ù… Ã— 25.00 $ = 12,500.00 $

      v_formula_desc := ROUND(v_effective_weight::NUMERIC, 2)::TEXT || ' ÙƒØ¬Ù… Ã— '

        || CASE 

             WHEN v_effective_weight > 0 THEN ROUND((v_total_cost / v_effective_weight)::NUMERIC, 2)::TEXT 

             ELSE '0.00' 

           END

        || ' ' || v_currency_symbol

        || ' = ' || ROUND(v_total_cost::NUMERIC, 2)::TEXT || ' ' || v_currency_symbol;

    END IF;



    -- Debit: "Ù…Ø®Ø²ÙˆÙ† Ø§Ù„Ù…Ø­Ø§ØµÙŠÙ„ - Ù…Ø§Ù†Ø¬Ùˆ - ÙƒÙ…ÙŠØ©: 1000 ÙƒØ±ØªÙˆÙ†Ø© - Ø³Ø¹Ø±: 2.00 $/ÙƒØ±ØªÙˆÙ†Ø© (1000 ÙƒØ±ØªÙˆÙ†Ø© Ã— 2.00 $ = 2,000.00 $) - Ù„ÙˆØ·: LOT-00001"

    v_debit_desc := 'Ù…Ø®Ø²ÙˆÙ† Ø§Ù„Ù…Ø­Ø§ØµÙŠÙ„ - ' || v_product_name

      || ' - ÙƒÙ…ÙŠØ©: ' || v_qty_desc;

    IF v_unit_price_desc != '' THEN

      v_debit_desc := v_debit_desc || ' - Ø³Ø¹Ø±: ' || v_unit_price_desc;

    END IF;

    v_debit_desc := v_debit_desc || ' (' || v_formula_desc || ')';

    v_debit_desc := v_debit_desc || ' - Ù„ÙˆØ·: ' || COALESCE(v_lot.lot_number, r.source_id);



    -- Credit: "Ù…Ø³ØªØ­Ù‚Ø§Øª Ù…ÙˆØ±Ø¯ - Ø£Ø­Ù…Ø¯ - Ù…Ø§Ù†Ø¬Ùˆ (1000 ÙƒØ±ØªÙˆÙ†Ø© Ã— 2.00 $ = 2,000.00 $) - Ù„ÙˆØ·: LOT-00001"

    v_credit_desc := 'Ù…Ø³ØªØ­Ù‚Ø§Øª Ù…ÙˆØ±Ø¯'

      || CASE WHEN v_supplier_name IS NOT NULL THEN ' - ' || v_supplier_name ELSE '' END

      || ' - ' || v_product_name

      || ' (' || v_formula_desc || ')';

    IF UPPER(v_lot_currency) != 'EGP' AND v_exchange_rate > 1.0 THEN

      v_credit_desc := v_credit_desc || ' [Ø³Ø¹Ø± ØµØ±Ù ' || ROUND(v_exchange_rate::NUMERIC, 2)::TEXT || ' Ø¬.Ù…]';

    END IF;

    v_credit_desc := v_credit_desc || ' - Ù„ÙˆØ·: ' || COALESCE(v_lot.lot_number, r.source_id);



    -- Header description: "Ø´Ø±Ø§Ø¡ Ù…Ø§Ù†Ø¬Ùˆ Ù…Ù† Ø£Ø­Ù…Ø¯ - 1000 ÙƒØ±ØªÙˆÙ†Ø© Ã— 2.00 $ = 2,000.00 $ - Ù„ÙˆØ·: LOT-00001"

    v_header_desc := 'Ø´Ø±Ø§Ø¡ ' || v_product_name

      || CASE WHEN v_supplier_name IS NOT NULL THEN ' Ù…Ù† ' || v_supplier_name ELSE '' END

      || ' - ' || v_formula_desc

      || ' - Ù„ÙˆØ·: ' || COALESCE(v_lot.lot_number, r.source_id);



    -- Update header

    UPDATE journal_entries SET description = v_header_desc WHERE id = r.je_id;



    -- Update debit line (inventory)

    UPDATE account_ledger_entries

    SET description = v_debit_desc

    WHERE journal_entry_id = r.je_id AND account_id = v_inventory_account_id;



    -- Update credit line (supplier) â€” match any account that is NOT the inventory account

    UPDATE account_ledger_entries

    SET description = v_credit_desc

    WHERE journal_entry_id = r.je_id AND account_id != v_inventory_account_id;



  END LOOP;



  RAISE NOTICE 'Backfill complete: updated all lot_receipt journal entry descriptions to granular format';

END $$;



