              'base_debit', 0,
              'credit', v_paid_amount,
              'base_credit', (v_paid_amount * v_exchange_rate),
              'currency', v_inv_currency,
              'description', 'ØµØ±Ù Ù…Ù† Ø®Ø²ÙŠÙ†Ø©: ' || COALESCE(v_treasury_name, '')
            )
          ),
