        'Ø³Ø¯Ø§Ø¯ ÙØ§ØªÙˆØ±Ø© Ù…Ø´ØªØ±ÙŠØ§Øª Ø±Ù‚Ù… ' || COALESCE(v_purchase.invoice_number, '') || ' - Ø§Ù„Ù…ÙˆØ±Ø¯: ' || COALESCE(v_supplier_name, ''),
        v_effective_user_id, v_inv_currency, v_exchange_rate, (v_paid_amount * v_exchange_rate),
