        );
      END IF;
    END IF;

    UPDATE purchase_invoices SET payment_processed = true WHERE id = v_purchase.id;
  END IF;

  -- â”€â”€ PHASE 4: Finalize Purchase Invoice Status â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  UPDATE purchase_invoices
