        item_name,
        category,
        quantity,
        unit_price,
        currency,
        exchange_rate,
        total_in_currency,
        amount,
        notes,
        is_confirmed
    ) VALUES (
        'packing_station',
        'Ù…Ø­Ø·Ø© Ø§Ù„ØªØ¹Ø¨Ø¦Ø© ÙˆØ§Ù„ØªØ¬Ù‡ÙŠØ²',
        'operational',
        'opening_balance',
        'ob_rm_' || p_raw_material_id::text,
        CURRENT_DATE,
        NULL,
        'Ø±ØµÙŠØ¯ Ø£ÙˆÙ„ Ø§Ù„Ù…Ø¯Ø©',
        NULL::bigint,
        p_raw_material_id,
        COALESCE(v_material_name, 'Ù…Ø§Ø¯Ø© ØªØ¹Ø¨Ø¦Ø©'),
        'Ù…ÙˆØ§Ø¯ Ø§Ù„ØªØ¹Ø¨Ø¦Ø©',
        COALESCE(p_quantity, 0),
        COALESCE(p_unit_price, 0),
        COALESCE(p_currency, 'EGP'),
        v_rate,
        v_total_foreign,
        v_total_base,
        v_desc,
        TRUE
    )
    ON CONFLICT (source_type, source_id) DO UPDATE SET
        cost_center_id = EXCLUDED.cost_center_id,
        cost_center_name = EXCLUDED.cost_center_name,
        cost_center_type = EXCLUDED.cost_center_type,
        transaction_date = EXCLUDED.transaction_date,
        supplier_id = EXCLUDED.supplier_id,
        supplier_name = EXCLUDED.supplier_name,
        product_id = EXCLUDED.product_id,
        raw_material_id = EXCLUDED.raw_material_id,
        item_name = EXCLUDED.item_name,
        category = EXCLUDED.category,
        quantity = EXCLUDED.quantity,
        unit_price = EXCLUDED.unit_price,
