-- â”€â”€ 2. RPC: Robust Collision-Proof Next Sub-Account Code â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

CREATE OR REPLACE FUNCTION public.get_next_sub_account_code(
    p_parent_code TEXT,
    p_company_id UUID DEFAULT NULL
)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_company_id UUID := p_company_id;
    v_parent_id BIGINT;
    v_next_code TEXT;
    v_suffix INT;
BEGIN
    IF v_company_id IS NULL THEN
        SELECT id INTO v_company_id FROM public.sys_companies LIMIT 1;
    END IF;

    SELECT id INTO v_parent_id
    FROM public.accounts
    WHERE account_code = p_parent_code
      AND (company_id = v_company_id OR company_id IS NULL)
    LIMIT 1;

    IF v_parent_id IS NULL THEN
        RAISE EXCEPTION 'Parent account % not found', p_parent_code;
    END IF;

    -- 1. Try single-digit extension: p_parent_code || '1' ... '9'
    FOR v_suffix IN 1..9 LOOP
        v_next_code := p_parent_code || v_suffix::TEXT;
        IF NOT EXISTS (SELECT 1 FROM public.accounts WHERE account_code = v_next_code) THEN
            RETURN v_next_code;
        END IF;
    END LOOP;

    -- 2. If single digits are exhausted (e.g. 3211-3219), switch to 2-digit extension (32101..32199)
    FOR v_suffix IN 1..99 LOOP
        v_next_code := p_parent_code || LPAD(v_suffix::TEXT, 2, '0');
        IF NOT EXISTS (SELECT 1 FROM public.accounts WHERE account_code = v_next_code) THEN
            RETURN v_next_code;
        END IF;
    END LOOP;

    -- 3. If 2 digits exhausted, switch to 3-digit extension (321001..321999)
    FOR v_suffix IN 1..999 LOOP
        v_next_code := p_parent_code || LPAD(v_suffix::TEXT, 3, '0');
        IF NOT EXISTS (SELECT 1 FROM public.accounts WHERE account_code = v_next_code) THEN
            RETURN v_next_code;
        END IF;
    END LOOP;

    RETURN p_parent_code || '_' || EXTRACT(EPOCH FROM NOW())::INT::TEXT;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_next_sub_account_code(TEXT, UUID) TO authenticated, service_role, anon;

-- â”€â”€ 3. Helper: Resolve Parent Account under Root 3 â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

CREATE OR REPLACE FUNCTION public.fn_resolve_category_parent_account(
    p_scope TEXT,
    p_name TEXT,
    p_supplier_type TEXT DEFAULT NULL
)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_clean_name TEXT := LOWER(TRIM(COALESCE(p_name, '')));
    v_clean_scope TEXT := LOWER(TRIM(COALESCE(p_scope, 'all')));
    v_clean_type TEXT := LOWER(TRIM(COALESCE(p_supplier_type, '')));
BEGIN
    -- 1. Station Suppliers / Operation Costs -> Level 4 Control: 3124 (ØªÙƒØ§Ù„ÙŠÙ ÙˆÙ…ØµØ±ÙˆÙØ§Øª ØªØ´ØºÙŠÙ„ Ø§Ù„Ù…Ø­Ø·Ø§Øª)
    IF v_clean_type = 'station' OR v_clean_name ~* '(Ù…Ø­Ø·Ø©|ØªØ¨Ø±ÙŠØ¯|ØªØ´ØºÙŠÙ„|Ø­ÙØ¸ Ù…Ø¨Ø±Ø¯|ØªÙ‚ÙÙŠÙ„ ÙƒØ±ØªÙˆÙ†|ØªØ¹ØªÙŠÙ‚|ØªØ¯ÙˆÙŠØ±|ØªØ¨Ø®ÙŠØ±|station)' THEN
        RETURN '3124';
    END IF;

    -- 2. Deduction Suppliers / Inspection Fees -> Level 4 Control: 3126 (Ø±Ø³ÙˆÙ… ÙØ­Øµ ÙˆØªØ®ØµÙŠÙ…Ø§Øª Ø§Ù„ØªØ´ØºÙŠÙ„)
    IF v_clean_type IN ('deduction', 'deductions') OR v_clean_name ~* '(ØªØ®ØµÙŠÙ…|ÙØ­Øµ|ØªØ­Ù„ÙŠÙ„|Ø¹ÙŠÙ†Ø©|Ø¹ÙŠÙ†Ø§Øª|Ø­Ø¬Ø± Ø²Ø±Ø§Ø¹ÙŠ|Ø³Ù„Ø§Ù…Ø© ØºØ°Ø§Ø¡|ÙˆØ¬Ø§Øª|deduction|inspection)' THEN
        RETURN '3126';
    END IF;

    -- 3. Packaging waste / scrap -> 3124 (Ù‡Ø§Ù„Ùƒ ÙˆÙØ§Ù‚Ø¯ Ø§Ù„ØªØ´ØºÙŠÙ„)
    IF v_clean_scope = 'packing_waste' OR v_clean_name ~* '(Ù‡Ø§Ù„Ùƒ|ÙØ§Ù‚Ø¯|ØªØ§Ù„Ù|ØªÙˆØ§Ù„Ù|waste|scrap)' THEN
        RETURN '3124';
    END IF;

    -- 4. Direct Sales Costs / Produce purchases -> 3411 (ØªÙƒØ§Ù„ÙŠÙ Ø§Ù„Ù…Ø¨ÙŠØ¹Ø§Øª)
    IF v_clean_name ~* '(Ù…Ø­ØµÙˆÙ„|Ù…Ø­Ø§ØµÙŠÙ„|Ø´Ø±Ø§Ø¡ Ø®Ø§Ù…|ÙØ±Ø§ÙˆÙ„Ø©|Ù…Ø§Ù†Ø¬Ùˆ|Ù…Ø¨ÙŠØ¹Ø§Øª|Ø®Ø§Ù…|produce|crop)' THEN
        RETURN '3411';
    END IF;

    -- 5. Shipping, Freight, Customs, Logistics -> 3411 (Ù…ØµØ±ÙˆÙØ§Øª Ø§Ù„Ø´Ø­Ù† ÙˆØ§Ù„ØªØ®Ù„ÙŠØµ ÙˆØ§Ù„Ù„ÙˆØ¬Ø³ØªÙŠØ§Øª)
    IF v_clean_scope = 'shipment' OR v_clean_name ~* '(Ø´Ø­Ù†|Ù†ÙˆÙ„ÙˆÙ†|ØªØ®Ù„ÙŠØµ|Ù„ÙˆØ¬Ø³Øª|Ù…Ø´Ø§Ù„|Ù†Ù‚Ù„|Ø¬Ù…Ø§Ø±Ùƒ|Ù…Ø®Ù„Øµ|shipping|freight|customs|logistics)' THEN
        RETURN '3411';
    END IF;

    -- 6. General & Administrative -> 3131 / 3132
    IF v_clean_scope IN ('general_admin', 'admin') THEN
        IF v_clean_name ~* '(Ø§Ø³ØªØ´Ø§Ø±|Ø§Ø´ØªØ±Ø§Ùƒ|Ø±Ø³ÙˆÙ…|Ø£ØªØ¹Ø§Ø¨|Ù…Ø±Ø§Ø¬Ø¹Ø©|legal|consulting)' THEN
            RETURN '3132';
        END IF;
        RETURN '3131';
    END IF;

    -- 7. Fallback based on scope
    IF v_clean_scope = 'packing' THEN
        RETURN '3124';
    ELSIF v_clean_scope = 'shipment' THEN
        RETURN '3411';
    ELSE
        RETURN '3131';
    END IF;
END;
$$;

