            created_at
        ) VALUES (
            p_customer_id::text,
            'customer',
            v_revenue,
            v_currency,
            'debit',
            p_sorting_id,
            'payment',
            'sorting_sale',
            'ÙØ§ØªÙˆØ±Ø© Ø¨ÙŠØ¹ ÙØ±Ø² - ' || COALESCE(v_sorting.product_name, '') || ' (' || trim(to_char(p_qty, '9999990.9')) || ' ÙƒØ¬Ù…)',
            COALESCE(p_user_id, auth.uid()),
            now()
        );

        -- 2. Ø­Ø±ÙƒØ© Ø§Ù„Ø³Ø¯Ø§Ø¯ Ø§Ù„Ù†Ù‚Ø¯ÙŠ Ø¨Ø§Ù„Ø®Ø²ÙŠÙ†Ø© (Ø¯Ø§Ø¦Ù† Ø§Ù„Ø¹Ù…ÙŠÙ„)
        INSERT INTO public.ledger_entries (
            entity_id,
            entity_type,
            amount,
            currency,
            entry_type,
            reference_id,
            reference_type,
            reference_text,
            description,
            created_by,
            created_at
        ) VALUES (
            p_customer_id::text,
            'customer',
            v_revenue,
            v_currency,
            'credit',
            p_sorting_id,
            'payment',
            'sorting_sale_cash',
            'Ø³Ø¯Ø§Ø¯ Ù†Ù‚Ø¯ÙŠ Ù„Ø¨ÙŠØ¹ Ø§Ù„ÙØ±Ø² - Ø®Ø²ÙŠÙ†Ø©: ' || COALESCE(p_treasury_name, 'Ø§Ù„Ø®Ø²ÙŠÙ†Ø©'),
            COALESCE(p_user_id, auth.uid()),
            now() + interval '1 millisecond'
        );
    END IF;

    -- ========================================================================
    -- Cost Center Resolution and Net Cost Offsetting Transaction
    -- ========================================================================
    v_fruit_name := v_sorting.product_name;

    IF v_sorting.packing_order_id IS NOT NULL THEN
        SELECT po.fruit_type_id::bigint, po.product_name, po.order_number
        INTO v_fruit_type_id, v_fruit_name, v_order_number
        FROM public.packing_orders po
        WHERE po.id = v_sorting.packing_order_id;
        
        IF v_fruit_name IS NULL OR v_fruit_name = '' THEN
            v_fruit_name := v_sorting.product_name;
        END IF;
    END IF;

    -- Strict Item-Bound Cost Center Resolution
    SELECT r.cost_center_id, r.cost_center_name
    INTO v_cc_id, v_cc_name
    FROM public.fn_resolve_active_crop_cost_center(
      COALESCE(v_fruit_name, 'Ù…Ø­ØµÙˆÙ„'),
      v_fruit_type_id
    ) r;
    v_cc_type := 'variety';

    v_source_id := 'sorting_sale_' || p_sorting_id || '_' || v_tx_id;

    INSERT INTO public.cost_center_transactions (
        cost_center_id,
        cost_center_name,
        cost_center_type,
        source_type,
        source_id,
        transaction_date,
        product_id,
        item_name,
        category,
        quantity,
        unit_price,
        currency,
        exchange_rate,
        total_in_currency,
        amount,
        notes,
        is_confirmed
    ) VALUES (
        v_cc_id,
        COALESCE(v_cc_name, v_fruit_name, 'Ù…Ø­ØµÙˆÙ„'),
        COALESCE(v_cc_type, 'variety'),
        'sorting_sale',
        v_source_id,
        CURRENT_DATE,
        v_fruit_type_id,
        'Ù…Ø¨ÙŠØ¹Ø§Øª ÙØ±Ø²Ø© - ' || COALESCE(v_fruit_name, 'Ù…Ø­ØµÙˆÙ„') || CASE WHEN v_order_number IS NOT NULL THEN ' (ØªØ´ØºÙŠÙ„Ø© ' || v_order_number || ')' ELSE '' END,
        'ØªÙƒÙ„ÙØ© Ø§Ù„ÙØ±Ø²',
        p_qty,
