        true
    )
    ON CONFLICT (source_type, source_id)
    DO UPDATE SET
        amount = EXCLUDED.amount,
        total_in_currency = EXCLUDED.total_in_currency,
        quantity = EXCLUDED.quantity,
        unit_price = EXCLUDED.unit_price,
