    ELSE

        v_txn_type := 'cash_payment';

    END IF;



    v_desc := COALESCE(p_description, 'Ø³Ø¯Ø§Ø¯ Ù„Ù…ÙˆØ±Ø¯ Ù†Ù‚Ù„ - ' || v_supplier.name);



    v_supplier_acct_id := v_supplier.account_id;

